/* The browser bundle's entry point (package.json "browser").
 *
 * It installs the web host - Web Serial instead of mpremote, an IndexedDB folder instead of
 * Documents, a pseudoterminal instead of a shell - and then hands over to the same activate() the
 * desktop runs. This bundle contains no Node builtin at all: if one ever creeps into a shared
 * module, scripts/build.js fails here rather than in someone's browser. */
import * as vscode from 'vscode';
import { setHost } from './platform/host';
import { WebHost } from './platform/web';
import { activate as activateShared, deactivate as deactivateShared } from './extension';

export function activate(context: vscode.ExtensionContext): Promise<void> {
    setHost(new WebHost());
    return activateShared(context);
}

export function deactivate(): void {
    deactivateShared();
}
