/* The "EVN ALPHA" terminal in the browser.
 *
 * On the desktop this terminal is a real shell running scripts/evn_run.py, which drives mpremote.
 * A browser has neither, so the same thing is done here in a vscode.Pseudoterminal straight over
 * Web Serial: the same header line, the same colours, the same Ctrl-C ("stop the program and coast
 * the motors"), the same REPL afterwards with Ctrl-] to leave, and the same phase reporting that
 * the status bar in runStatus.ts reads (an in-memory state here instead of the temp file).
 *
 * The port has one owner: the terminal takes it while it is open and gives it back on close, which
 * is exactly the coordination the live console already does through pauseConsole/resumeConsole.
 */
import * as vscode from 'vscode';
import { RunState } from '../host';
import { RawRepl, lastLine, pyBytes, pyStr } from './rawrepl';
import { ByteStream, Wire, decode, delay, encode } from './stream';
import { openPort } from './ports';
import { log } from '../../util';

const CYAN = '\x1b[36m', GREEN = '\x1b[32m', RED = '\x1b[31m', YELLOW = '\x1b[33m', DIM = '\x1b[90m', OFF = '\x1b[0m';
const RULE = '-'.repeat(72);
const CTRL_C = '\x03';
const CTRL_RBRACKET = '\x1d';

/* ---- the run state the status bar reads -------------------------------------------------- */

let state: RunState | undefined;

export function webRunState(): RunState | undefined { return state; }
export function clearWebRunState(): void { state = undefined; }

function setState(phase: string, file: string, port: string, rc: number | null = null): void {
    state = { phase, rc, file, port, t: Date.now() / 1000 };
}

/* ---- the terminal -------------------------------------------------------------------------- */

export interface TerminalJob {
    kind: 'run' | 'repl';
    port: string;
    /** the program to run (`run` only) */
    file?: vscode.Uri;
    /** open the REPL when the program has finished (`run` only) */
    repl?: boolean;
}

class BoardPty implements vscode.Pseudoterminal {
    private readonly writeEmitter = new vscode.EventEmitter<string>();
    private readonly closeEmitter = new vscode.EventEmitter<number | void>();
    readonly onDidWrite = this.writeEmitter.event;
    readonly onDidClose = this.closeEmitter.event;

    private stream: ByteStream | undefined;
    private wire: Wire | undefined;
    private repl: RawRepl | undefined;
    private interactive = false;         // the friendly REPL is up: keystrokes go to the board
    private stopping = false;
    private finished = false;
    private relay: Promise<void> | undefined;

    constructor(private readonly job: TerminalJob) { }

    open(): void { void this.go(); }

    close(): void {
        this.finished = true;
        this.interactive = false;
        void this.release();
    }

    handleInput(data: string): void {
        if (data.includes(CTRL_RBRACKET)) { this.say(`\r\n${DIM}leaving the REPL${OFF}\r\n`); this.closeEmitter.fire(0); return; }
        if (!this.interactive) {
            if (data.includes(CTRL_C)) { this.stopping = true; }
            return;
        }
        const wire = this.wire;
        if (!wire) { return; }
        void wire.write(encode(data)).catch(() => { /* the port went away; the loop reports it */ });
    }

    private say(text: string): void { this.writeEmitter.fire(text); }

    /** Board output to a terminal: bare \n has to become \r\n or the lines stair-step. */
    private board(text: string): void { this.writeEmitter.fire(text.replace(/\r?\n/g, '\r\n')); }

    private async release(): Promise<void> {
        const wire = this.wire;
        this.wire = undefined;
        this.repl = undefined;
        this.stream = undefined;
        if (!wire) { return; }
        try { if (!wire.gone) { await wire.write('\r\x02'); await delay(100); } } catch { /* going anyway */ }
        try { await wire.close(); } catch { /* already gone */ }
    }

    private async go(): Promise<void> {
        const { port } = this.job;
        const name = this.job.file ? fileName(this.job.file) : '';
        try {
            this.stream = await openPort(port);
            this.wire = new Wire(this.stream);
            this.repl = new RawRepl(this.wire);
        } catch (e: any) {
            this.say(`${RED}EVN ALPHA: ${port} could not be opened: ${e?.message ?? e}${OFF}\r\n`);
            setState('closed', name, port);
            this.closeEmitter.fire(1);
            return;
        }
        try {
            if (this.job.kind === 'repl') {
                await this.friendlyRepl(true);
                return;
            }
            await this.runProgram();
        } catch (e: any) {
            this.say(`\r\n${RED}EVN ALPHA: ${e?.message ?? e}${OFF}\r\n`);
            setState('error', name, port, 1);
            this.say(`${DIM}press Ctrl-] to close this terminal${OFF}\r\n`);
        }
    }

    /* ---- running a program ------------------------------------------------------------- */

    private async runProgram(): Promise<void> {
        const repl = this.repl as RawRepl;
        const uri = this.job.file as vscode.Uri;
        const name = fileName(uri);
        const port = this.job.port;
        const source = await vscode.workspace.fs.readFile(uri);

        this.say(`${CYAN}EVN ALPHA: running ${name} on ${port}  (Ctrl-C stops the program and coasts the motors)${OFF}\r\n`);
        this.say(`${DIM}${RULE}${OFF}\r\n`);
        setState('running', uri.toString(), port);

        await repl.enter(true);
        await repl.paste(source);
        // follow the program's output until it ends, or until the user pressed Ctrl-C
        const r = await repl.follow(24 * 3600, (text) => this.board(text), () => this.stopping);

        let rc = 0;
        if (this.stopping) {
            rc = 130;
            setState('interrupted', uri.toString(), port, rc);
            this.say(`\r\n${YELLOW}EVN ALPHA: Ctrl-C -> stopping the program on the board and coasting the motors${OFF}\r\n`);
            await repl.interrupt();
            try { await repl.enter(false); await repl.evaluate('import evn; evn.stop_all()', 10); }
            catch (e: any) { this.say(`${DIM}(${e?.message ?? e})${OFF}\r\n`); }
        } else if (!r.ok) {
            rc = 1;
            this.board('\n' + r.err + '\n');
        }

        this.say(`${DIM}${RULE}${OFF}\r\n`);
        if (rc === 0 && !this.stopping) {
            setState('finished', uri.toString(), port, 0);
            this.say(`${GREEN}EVN ALPHA: program finished${OFF}\r\n`);
        } else if (!this.stopping) {
            setState('error', uri.toString(), port, rc);
            this.say(`${RED}EVN ALPHA: program ended with an error; the traceback is above${OFF}\r\n`);
            this.say(`${RED}EVN ALPHA: click the line number above to jump to the error${OFF}\r\n`);
        }

        if (this.job.repl) {
            setState('repl', uri.toString(), port, rc);
            await this.friendlyRepl(false);
        } else {
            this.say(`${CYAN}EVN ALPHA: press Ctrl-] to close this terminal${OFF}\r\n`);
            setState('closed', uri.toString(), port, rc);
        }
    }

    /* ---- the REPL ----------------------------------------------------------------------- */

    private async friendlyRepl(announceOnly: boolean): Promise<void> {
        const wire = this.wire as Wire;
        const port = this.job.port;
        if (announceOnly) { setState('repl', '', port); }
        this.say(`${CYAN}EVN ALPHA: REPL attached. Ctrl-C coasts the motors, Ctrl-] leaves the REPL and closes this terminal.${OFF}\r\n`);
        await wire.write('\r\x02');           // friendly REPL
        await delay(120);
        await wire.write('\r\n');
        this.interactive = true;
        this.relay = (async () => {
            while (this.interactive && !this.finished) {
                try {
                    await wire.pump(80);
                    const data = wire.takeAll();
                    if (data.length) { this.board(decode(data)); }
                } catch {
                    this.say(`\r\n${RED}EVN ALPHA: the board is no longer there${OFF}\r\n`);
                    this.closeEmitter.fire(1);
                    return;
                }
            }
        })();
        await this.relay;
    }
}

function fileName(uri: vscode.Uri): string {
    const p = uri.path;
    return p.slice(p.lastIndexOf('/') + 1) || uri.toString();
}

/** The one terminal that may hold the port, in the browser. */
export function createBoardTerminal(job: TerminalJob): vscode.Terminal {
    log(`web terminal: ${job.kind} on ${job.port}${job.file ? ` (${job.file.toString()})` : ''}`);
    return vscode.window.createTerminal({
        name: 'EVN ALPHA',
        pty: new BoardPty(job),
        iconPath: new vscode.ThemeIcon('circuit-board'),
    });
}

/* ---- the one-shot board operations (what mpremote does on the desktop) --------------------- */

/**
 * Open the port, put the board in the raw REPL, do one thing, hand the friendly REPL back.
 * Every caller in extension.ts and boardView.ts has already paused the live console, so the port
 * is free - the same rule as on the desktop, where mpremote would fail otherwise.
 */
export async function withBoard<T>(port: string, fn: (repl: RawRepl) => Promise<T>): Promise<T> {
    const stream = await openPort(port);
    const wire = new Wire(stream);
    const repl = new RawRepl(wire);
    try {
        await repl.enter(true);
        return await fn(repl);
    } finally {
        try { await repl.exitToFriendly(); } catch { /* going anyway */ }
        try { await stream.close(); } catch { /* already gone */ }
    }
}

/** `mpremote connect PORT exec CODE`. */
export async function boardExec(port: string, code: string, timeoutSeconds = 20): Promise<{ out: string; err: string }> {
    return withBoard(port, async (repl) => {
        const r = await repl.exec(code, timeoutSeconds);
        return { out: r.out, err: r.ok ? '' : r.err };
    });
}

/** `mpremote connect PORT exec --no-follow CODE`: the link drops on purpose (reset, bootloader). */
export async function boardExecNoFollow(port: string, code: string): Promise<void> {
    const stream = await openPort(port);
    const wire = new Wire(stream);
    const repl = new RawRepl(wire);
    try {
        await repl.enter(true);
        await repl.paste(encode(code));
        await delay(200);
    } finally {
        try { await stream.close(); } catch { /* the board is going away anyway */ }
    }
}

/** `mpremote connect PORT ls`, in mpremote's own layout. */
export async function boardLs(port: string): Promise<string> {
    const out = await withBoard(port, (repl) => repl.evaluate(
        "import os\nfor n in sorted(os.listdir('/')):\n"
        + "    st = os.stat('/' + n)\n"
        + "    print('%9d %s' % (0 if st[0] & 0x4000 else st[6], n + ('/' if st[0] & 0x4000 else '')))", 15));
    return `ls :\n${out}`;
}

/** `mpremote connect PORT rm :NAME`. */
export async function boardRm(port: string, name: string): Promise<void> {
    await withBoard(port, (repl) => repl.evaluate(`import os\nos.remove(${pyStr('/' + name.replace(/^[:/]+/, ''))})`, 15));
}

/** `mpremote connect PORT cp FILE :main.py`, from whatever file system the Uri lives on. */
export async function boardUpload(port: string, file: vscode.Uri, target = 'main.py',
    onProgress?: (done: number, total: number) => void): Promise<void> {
    const content = await vscode.workspace.fs.readFile(file);
    await withBoard(port, async (repl) => {
        await repl.writeFile(target, content, onProgress);
    });
}

export { pyBytes, lastLine };
