/* Documentation links for the symbol under the cursor, and the extension / firmware update check.
 *
 * Both features only ever talk to the documentation site (the `evn.docsUrl` setting, default
 * https://evn.coresg.tech):
 *
 *   evn.openDocsForSymbol   the word under the cursor is resolved against the bundled docs/API.md
 *                           and the site is opened at `${docsUrl()}/#/api/<slug>` (see docs/PUBLISHING.md
 *                           for the URL convention the site renderer honours).
 *   evn.checkForUpdates     one small GET of `${docsUrl()}/latest.json`, compared with this extension's
 *                           version and with firmware/BUILD.txt. Nothing is downloaded or installed
 *                           without the user asking for it; a failure is never an error toast.
 */
import * as vscode from 'vscode';
import { log } from './util';
import { docsUrl } from './extension';

/* ---- docs/API.md: headings, slugs and the symbol lookup ---------------------------------- */

interface Section {
    /** heading text as written, without the leading #s */
    text: string;
    /** GitHub-style anchor slug */
    slug: string;
    /** heading depth (1 = #) */
    level: number;
    /** the inline `code spans` of the section body, joined (what a symbol is looked up in) */
    code: string;
}

let sections: Section[] | undefined;    // parsed once per session

/** GitHub-style anchor: lowercase, spaces to `-`, then everything but letters, digits, `-` and `_` dropped. */
export function slugify(heading: string): string {
    return heading
        .trim()
        .toLowerCase()
        .replace(/\s+/g, '-')
        .replace(/[^a-z0-9\-_]/g, '');
}

function escapeRe(s: string): string { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/**
 * Split a Markdown document into sections at its ATX headings.
 * Fenced code blocks are skipped (a ``` block is not a heading and not an inline mention), so only
 * real headings and real `inline code` count.
 */
export function parseSections(markdown: string): Section[] {
    const out: Section[] = [];
    let current: Section | undefined;
    let fenced = false;
    for (const raw of markdown.split(/\r?\n/)) {
        if (/^\s*(```|~~~)/.test(raw)) { fenced = !fenced; continue; }
        if (fenced) { continue; }
        const h = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(raw);
        if (h) {
            current = { text: h[2].trim(), slug: slugify(h[2]), level: h[1].length, code: '' };
            out.push(current);
            continue;
        }
        if (!current) { continue; }
        for (const m of raw.matchAll(/`([^`]+)`/g)) { current.code += m[1] + '\n'; }
    }
    return out;
}

async function apiSections(ctx: vscode.ExtensionContext): Promise<Section[]> {
    if (sections) { return sections; }
    let text = '';
    try {
        const bytes = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(ctx.extensionUri, 'docs', 'API.md'));
        text = new TextDecoder().decode(bytes);
    } catch (e) { log(`docs: could not read the bundled docs/API.md: ${e}`); }
    sections = parseSections(text);
    return sections;
}

/**
 * The best section of the API reference for `word`:
 *   1. a heading that contains the word as a whole word (an exact heading wins over a longer one);
 *   2. else the first section whose body mentions it in backticks as a call, `run_angle(`;
 *   3. else the first section whose body mentions it in backticks at all;
 *   4. else the top of the document.
 * Case-sensitive first (the API is CamelCase), then case-insensitive.
 */
export function findSection(all: Section[], word: string): Section | undefined {
    if (!all.length || !word) { return undefined; }
    const w = escapeRe(word);
    for (const flags of ['', 'i']) {
        const whole = new RegExp(`(^|[^A-Za-z0-9_])${w}($|[^A-Za-z0-9_])`, flags);
        const call = new RegExp(`(^|[^A-Za-z0-9_])${w}\\s*\\(`, flags);

        let exact: Section | undefined;
        let inHeading: Section | undefined;
        for (const s of all) {
            const bare = s.text.replace(/`/g, '').trim();
            if (!exact && (flags ? bare.toLowerCase() === word.toLowerCase() : bare === word)) { exact = s; }
            if (!inHeading && whole.test(s.text)) { inHeading = s; }
        }
        if (exact) { return exact; }
        if (inHeading) { return inHeading; }

        const called = all.find((s) => call.test(s.code));
        if (called) { return called; }
        const mentioned = all.find((s) => whole.test(s.code));
        if (mentioned) { return mentioned; }
    }
    return undefined;
}

/** The word to look up: the selection if there is one, else the identifier under the cursor. */
function wordAtCursor(editor: vscode.TextEditor | undefined): string | undefined {
    if (!editor) { return undefined; }
    const sel = editor.selection;
    if (!sel.isEmpty) {
        const m = /[A-Za-z_][A-Za-z0-9_]*/.exec(editor.document.getText(sel));
        return m ? m[0] : undefined;
    }
    const range = editor.document.getWordRangeAtPosition(sel.active, /[A-Za-z_][A-Za-z0-9_]*/);
    return range ? editor.document.getText(range) : undefined;
}

/**
 * Open the online documentation at the section that documents the word under the cursor.
 * With no Python editor, no word, or no match, the documentation root is opened instead.
 */
async function openDocsForSymbol(ctx: vscode.ExtensionContext): Promise<void> {
    const editor = vscode.window.activeTextEditor;
    const word = editor && editor.document.languageId === 'python' ? wordAtCursor(editor) : undefined;
    let url = docsUrl();                                    // no editor, no word: the documentation root
    if (word) {
        const all = await apiSections(ctx);
        const section = findSection(all, word);
        // an unknown word still lands on the API reference, at its top
        const slug = section?.slug ?? all[0]?.slug ?? '';
        url = `${docsUrl()}/#/api/${slug}`;
    }
    log(word ? `docs: ${word} -> ${url}` : `docs: no symbol under the cursor -> ${url}`);
    await vscode.env.openExternal(vscode.Uri.parse(url));
}

/* ---- latest.json ------------------------------------------------------------------------- */

/** One product in latest.json. */
interface Release {
    version?: string;
    /** the download of that release (the .vsix for the extension, the .uf2 for the firmware) */
    vsix?: string;
    uf2?: string;
    notes?: string;
}
interface Latest {
    extension?: Release;
    firmware?: Release;
}

const FETCH_TIMEOUT_MS = 8000;
const MAX_BODY = 256 * 1024;

/**
 * GET a small JSON document with the global fetch (the desktop extension host of VS Code 1.106
 * has it, and so does every browser), with a timeout and a cap on the body. Redirects are the
 * runtime's business; non-2xx and anything oversized is an error, and a failure is never fatal:
 * the caller turns it into a log line, not a toast.
 */
export async function fetchJson(url: string, timeoutMs = FETCH_TIMEOUT_MS): Promise<any> {
    let target: URL;
    try { target = new URL(url); }
    catch { throw new Error(`bad url ${url}`); }
    if (target.protocol !== 'http:' && target.protocol !== 'https:') {
        throw new Error(`unsupported address ${url}`);
    }
    const control = new AbortController();
    const timer = setTimeout(() => control.abort(), timeoutMs);
    try {
        const res = await fetch(target.toString(), {
            headers: { accept: 'application/json' },
            signal: control.signal,
            redirect: 'follow',
        });
        if (!res.ok) { throw new Error(`HTTP ${res.status || 'no status'}`); }
        const body = await res.text();
        if (body.length > MAX_BODY) { throw new Error('the answer is too large'); }
        try { return JSON.parse(body); }
        catch { throw new Error('the answer is not JSON'); }
    } catch (e: any) {
        if (e?.name === 'AbortError') { throw new Error(`no answer within ${Math.round(timeoutMs / 1000)} s`); }
        throw e instanceof Error ? e : new Error(String(e));
    } finally {
        clearTimeout(timer);
    }
}

/* ---- versions ---------------------------------------------------------------------------- */

/** Dotted numeric compare: >0 when `a` is newer than `b`, 0 when they are the same release. */
export function compareVersions(a: string, b: string): number {
    const parts = (v: string) => v.trim().replace(/^v/i, '').split('.').map((p) => parseInt(p, 10) || 0);
    const x = parts(a);
    const y = parts(b);
    for (let i = 0; i < Math.max(x.length, y.length); i++) {
        const d = (x[i] ?? 0) - (y[i] ?? 0);
        if (d) { return d > 0 ? 1 : -1; }
    }
    return 0;
}

function isVersion(v: unknown): v is string {
    return typeof v === 'string' && /^v?\d+(\.\d+)*$/.test(v.trim());
}

/** The `version:` line of the bundled firmware/BUILD.txt (the firmware in this package). */
export async function bundledFirmwareVersion(ctx: vscode.ExtensionContext): Promise<string | undefined> {
    let text: string;
    try {
        const bytes = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(ctx.extensionUri, 'firmware', 'BUILD.txt'));
        text = new TextDecoder().decode(bytes);
    }
    catch (e) { log(`updates: could not read firmware/BUILD.txt: ${e}`); return undefined; }
    const m = /^﻿?\s*version:\s*(\S+)\s*$/m.exec(text);
    return m ? m[1] : undefined;
}

/* ---- the update check --------------------------------------------------------------------- */

const LAST_CHECK_KEY = 'evn.updates.lastCheck';          // ms since epoch of the last automatic check
const ANNOUNCED_KEY = 'evn.updates.announced';           // { "extension:0.2.17": { at, remindAt? } }
const DAY_MS = 24 * 60 * 60 * 1000;
const REMIND_MS = 7 * DAY_MS;
const STARTUP_DELAY_MS = 20000;

interface Announcement { at: number; remindAt?: number; }
type Announcements = Record<string, Announcement>;

function announcements(ctx: vscode.ExtensionContext): Announcements {
    return ctx.globalState.get<Announcements>(ANNOUNCED_KEY, {}) ?? {};
}

/** True when this version has not been announced yet, or "Remind me later" has run out. */
function shouldAnnounce(ctx: vscode.ExtensionContext, key: string): boolean {
    const a = announcements(ctx)[key];
    if (!a) { return true; }
    return a.remindAt !== undefined && Date.now() >= a.remindAt;
}

async function remember(ctx: vscode.ExtensionContext, key: string, remindAt?: number): Promise<void> {
    const all = announcements(ctx);
    all[key] = { at: Date.now(), remindAt };
    await ctx.globalState.update(ANNOUNCED_KEY, all);
}

function looksLikeUrl(u: unknown): u is string {
    return typeof u === 'string' && /^https?:\/\//i.test(u.trim());
}

async function openUrl(url: string): Promise<void> {
    await vscode.env.openExternal(vscode.Uri.parse(url));
}

/**
 * Compare the published versions with what is installed and say so.
 * `silent` is the daily check: nothing is shown when everything is current or when the newer version
 * has already been announced, and a failure only reaches the log.
 */
async function check(ctx: vscode.ExtensionContext, silent: boolean): Promise<void> {
    const url = `${docsUrl()}/latest.json`;
    let latest: Latest;
    try {
        log(`updates: GET ${url}`);
        latest = (await fetchJson(url)) as Latest;
    } catch (e: any) {
        const reason = e?.message ?? String(e);
        log(`updates: ${url} failed: ${e?.stack ?? e}`);
        if (!silent) { vscode.window.showInformationMessage(`EVN: could not check for updates (${reason})`); }
        return;
    }

    const here = String(ctx.extension?.packageJSON?.version ?? '0.0.0');
    const firmwareHere = await bundledFirmwareVersion(ctx);
    const ext = latest?.extension;
    const fw = latest?.firmware;
    if (!isVersion(ext?.version) && !isVersion(fw?.version)) {
        log(`updates: latest.json holds no version (${JSON.stringify(latest).slice(0, 200)})`);
        if (!silent) { vscode.window.showInformationMessage('EVN: could not check for updates (latest.json has no version)'); }
        return;
    }

    const newerExt = isVersion(ext?.version) && compareVersions(ext!.version!, here) > 0 ? ext! : undefined;
    const newerFw = isVersion(fw?.version) && !!firmwareHere && compareVersions(fw!.version!, firmwareHere) > 0 ? fw! : undefined;
    log(`updates: extension ${here} (published ${ext?.version ?? '?'}), firmware ${firmwareHere ?? '?'} (published ${fw?.version ?? '?'})`);

    if (!newerExt && !newerFw) {
        if (!silent) { vscode.window.showInformationMessage('EVN: extension and firmware are up to date'); }
        return;
    }

    // One message: the extension update is the headline, because it brings the firmware with it.
    const kind = newerExt ? 'extension' : 'firmware';
    const version = (newerExt ?? newerFw)!.version!;
    const key = `${kind}:${version}`;
    if (silent && !shouldAnnounce(ctx, key)) { log(`updates: ${key} already announced`); return; }

    let message: string;
    const buttons: string[] = [];
    const download = newerExt ? (looksLikeUrl(newerExt.vsix) ? newerExt.vsix : undefined)
        : (looksLikeUrl(newerFw!.uf2) ? newerFw!.uf2 : undefined);
    const notes = (newerExt ?? newerFw)!.notes;

    if (newerExt) {
        message = `EVN: extension ${version} is available (you have ${here})`;
        if (newerFw) { message += `; it brings firmware ${newerFw.version}`; }
        if (download) { buttons.push('Download'); }
    } else {
        message = `EVN: a newer firmware ${version} is available (the board's package here is ${firmwareHere}); `
            + 'it comes with the next extension release, which flashes it for you';
        if (download) { buttons.push('Download UF2'); }
    }
    if (looksLikeUrl(notes)) { buttons.push('Release notes'); }
    if (silent) { buttons.push('Remind me later'); }

    const answer = await vscode.window.showInformationMessage(message, ...buttons);
    if (silent) {
        await remember(ctx, key, answer === 'Remind me later' ? Date.now() + REMIND_MS : undefined);
    }
    if ((answer === 'Download' || answer === 'Download UF2') && download) { await openUrl(download); }
    else if (answer === 'Release notes' && looksLikeUrl(notes)) { await openUrl(notes); }
}

/** The daily check: 20 s after activation, at most once every 24 h, and never in the way of anything. */
function scheduleDailyCheck(ctx: vscode.ExtensionContext): vscode.Disposable {
    const timer = setTimeout(() => {
        void (async () => {
            try {
                if (!vscode.workspace.getConfiguration('evn').get<boolean>('updates.check', true)) { return; }
                const last = ctx.globalState.get<number>(LAST_CHECK_KEY, 0) ?? 0;
                if (Date.now() - last < DAY_MS) { log('updates: checked less than a day ago'); return; }
                await ctx.globalState.update(LAST_CHECK_KEY, Date.now());
                await check(ctx, true);
            } catch (e: any) {
                log(`updates: the daily check failed: ${e?.stack ?? e}`);
            }
        })();
    }, STARTUP_DELAY_MS);
    return new vscode.Disposable(() => clearTimeout(timer));
}

/* ---- registration --------------------------------------------------------------------------- */

export function registerDocsLinks(ctx: vscode.ExtensionContext): void {
    const reg = (id: string, fn: () => Promise<void>) =>
        ctx.subscriptions.push(vscode.commands.registerCommand(id, async () => {
            try { await fn(); }
            catch (e: any) { log(`ERROR ${id}: ${e?.stack ?? e}`); }
        }));

    reg('evn.openDocsForSymbol', () => openDocsForSymbol(ctx));
    reg('evn.checkForUpdates', async () => {
        // a check by hand also counts as today's check, so the daily one does not repeat it
        await ctx.globalState.update(LAST_CHECK_KEY, Date.now());
        await check(ctx, false);
    });

    try { ctx.subscriptions.push(scheduleDailyCheck(ctx)); }
    catch (e: any) { log(`updates: could not schedule the daily check: ${e?.stack ?? e}`); }
}
