/* The battery warning in the status bar.
 *
 * A flat pack is the most common cause of a robot that "stopped working": the motors lose torque
 * long before the board browns out, and nothing on the desk says why. The live console already
 * carries the pack voltage in every `tele` event, so the warning costs the board nothing at all:
 * this file only listens. No timer, no poll, no extra traffic — when the console is not connected
 * there is no telemetry and there is no warning either.
 *
 * It appears below evn.battery.warnVolts (7.0 V by default: the pack is two cells, so 3.5 V a
 * cell) and goes away again 0.2 V above it, so a pack sitting on the threshold does not blink at
 * every sample; a motor starting pulls the pack down for a moment, which is exactly why the
 * hysteresis is there.
 */
import * as vscode from 'vscode';
import { onDidReceiveTelemetry, onDidChangeConsole, consoleState, Telemetry } from './console';
import { log } from './util';

/** how far above the threshold the pack has to come back before the warning goes away */
const HYSTERESIS_MV = 200;

/** Volts below which the warning shows; 0 (or nonsense) turns it off. */
function warnVolts(): number {
    const v = vscode.workspace.getConfiguration('evn').get<number>('battery.warnVolts', 7.0);
    return typeof v === 'number' && isFinite(v) && v > 0 ? v : 0;
}

function volts(mv: number): string {
    return (mv / 1000).toFixed(1);
}

export function registerBatteryStatus(ctx: vscode.ExtensionContext): void {
    const item = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 48);
    item.name = 'EVN ALPHA battery';
    item.command = 'evn.board.focus';
    item.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
    ctx.subscriptions.push(item);

    let showing = false;

    const hide = (why: string): void => {
        if (!showing) { return; }
        showing = false;
        item.hide();
        log(`battery warning cleared (${why})`);
    };

    ctx.subscriptions.push(onDidReceiveTelemetry((t: Telemetry) => {
        const warn = warnVolts();
        if (!warn) { hide('evn.battery.warnVolts is 0'); return; }
        const mv = t.batt;
        if (typeof mv !== 'number' || mv <= 0) { return; }      // the board could not read the pack
        const threshold = warn * 1000;
        // below the threshold it appears, and it only goes away 0.2 V above it again
        if (showing ? mv >= threshold + HYSTERESIS_MV : mv >= threshold) {
            hide(`the pack is back at ${volts(mv)} V`);
            return;
        }
        item.text = `$(warning) EVN battery ${volts(mv)} V`;
        const cells = (t.cells ?? []).filter((c) => typeof c === 'number');
        item.tooltip = [
            `The battery pack is at ${volts(mv)} V (the warning is set at ${warn.toFixed(1)} V).`,
            cells.length ? `Cells: ${cells.map(volts).join(' V, ')} V.` : '',
            'Charge the pack: below this the motors lose torque long before the board stops.',
            'The threshold is evn.battery.warnVolts (0 turns this off).',
        ].filter(Boolean).join('\n');
        if (!showing) {
            showing = true;
            item.show();
            log(`battery warning: the pack is at ${volts(mv)} V (below ${warn.toFixed(1)} V)`);
        }
    }));

    // No telemetry means no reading at all: a warning left on the status bar would be a number
    // from minutes ago. The console going quiet takes it down with it.
    ctx.subscriptions.push(onDidChangeConsole(() => {
        const state = consoleState();
        if (state !== 'live' && state !== 'busy') { hide('the live console is not connected'); }
    }));

    ctx.subscriptions.push(vscode.workspace.onDidChangeConfiguration((e) => {
        if (e.affectsConfiguration('evn.battery.warnVolts') && !warnVolts()) { hide('evn.battery.warnVolts is 0'); }
    }));
}
