/* The projects folder in the browser: a FileSystemProvider for the scheme `evn-projects`, backed
 * by IndexedDB.
 *
 * On the desktop the user's programs live in Documents/EVN Projects. A browser has no such place,
 * so the same folder is a small store in the browser's own database: it survives reloads, browser
 * restarts and updates of the IDE, and it belongs to that browser profile on that machine. VS Code
 * treats it as an ordinary folder - the editor, the tree, "Open my projects folder as the
 * workspace", rename, duplicate and delete all go through vscode.workspace.fs, which lands here.
 *
 * Clearing the site's data in the browser deletes it, and it is not synchronised anywhere: the
 * "Export Python" and the download of a program are how work leaves this machine.
 */
import * as vscode from 'vscode';

export const PROJECTS_SCHEME = 'evn-projects';
export const PROJECTS_ROOT = vscode.Uri.from({ scheme: PROJECTS_SCHEME, path: '/' });

const DB_NAME = 'evn-alpha-projects';
const DB_VERSION = 1;
const STORE = 'files';

interface Entry {
    /** '/', '/blink.py', '/robots/line.evnblocks' - always with a leading slash, never a trailing one */
    path: string;
    type: 'file' | 'dir';
    ctime: number;
    mtime: number;
    data?: Uint8Array;
}

/* ---- IndexedDB, promise shaped ------------------------------------------------------------ */

function idb(): IDBFactory {
    const f = (globalThis as any).indexedDB as IDBFactory | undefined;
    if (!f) { throw new Error('this browser has no IndexedDB, so the projects folder cannot be stored'); }
    return f;
}

function wrap<T>(req: IDBRequest<T>): Promise<T> {
    return new Promise((resolve, reject) => {
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error ?? new Error('IndexedDB error'));
    });
}

let dbPromise: Promise<IDBDatabase> | undefined;

function open(): Promise<IDBDatabase> {
    if (dbPromise) { return dbPromise; }
    dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
        const req = idb().open(DB_NAME, DB_VERSION);
        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(STORE)) { db.createObjectStore(STORE, { keyPath: 'path' }); }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error ?? new Error('IndexedDB could not be opened'));
    });
    return dbPromise;
}

async function tx<T>(mode: IDBTransactionMode, fn: (store: IDBObjectStore) => Promise<T>): Promise<T> {
    const db = await open();
    const t = db.transaction(STORE, mode);
    const out = await fn(t.objectStore(STORE));
    await new Promise<void>((resolve, reject) => {
        t.oncomplete = () => resolve();
        t.onerror = () => reject(t.error ?? new Error('IndexedDB transaction failed'));
        t.onabort = () => reject(t.error ?? new Error('IndexedDB transaction aborted'));
    });
    return out;
}

/* ---- paths --------------------------------------------------------------------------------- */

function norm(uri: vscode.Uri): string {
    let p = uri.path || '/';
    if (!p.startsWith('/')) { p = '/' + p; }
    p = p.replace(/\/{2,}/g, '/');
    if (p.length > 1 && p.endsWith('/')) { p = p.slice(0, -1); }
    return p;
}

function parentOf(p: string): string {
    if (p === '/') { return '/'; }
    const i = p.lastIndexOf('/');
    return i <= 0 ? '/' : p.slice(0, i);
}

function nameOf(p: string): string { return p.slice(p.lastIndexOf('/') + 1); }

/* ---- the provider --------------------------------------------------------------------------- */

export class ProjectsFileSystem implements vscode.FileSystemProvider {
    private readonly emitter = new vscode.EventEmitter<vscode.FileChangeEvent[]>();
    readonly onDidChangeFile = this.emitter.event;
    private queued: vscode.FileChangeEvent[] = [];
    private flushTimer: any;

    watch(): vscode.Disposable { return new vscode.Disposable(() => { /* every change is fired below */ }); }

    private fire(type: vscode.FileChangeType, uri: vscode.Uri): void {
        this.queued.push({ type, uri });
        if (this.flushTimer) { return; }
        this.flushTimer = setTimeout(() => {
            this.flushTimer = undefined;
            const all = this.queued;
            this.queued = [];
            this.emitter.fire(all);
        }, 5);
    }

    private async entry(p: string): Promise<Entry | undefined> {
        if (p === '/') { return { path: '/', type: 'dir', ctime: 0, mtime: 0 }; }
        return tx('readonly', (s) => wrap<Entry | undefined>(s.get(p) as IDBRequest<Entry | undefined>));
    }

    async stat(uri: vscode.Uri): Promise<vscode.FileStat> {
        const p = norm(uri);
        const e = await this.entry(p);
        if (!e) { throw vscode.FileSystemError.FileNotFound(uri); }
        return {
            type: e.type === 'dir' ? vscode.FileType.Directory : vscode.FileType.File,
            ctime: e.ctime,
            mtime: e.mtime,
            size: e.data ? e.data.byteLength : 0,
        };
    }

    async readDirectory(uri: vscode.Uri): Promise<[string, vscode.FileType][]> {
        const dir = norm(uri);
        const e = await this.entry(dir);
        if (!e) { throw vscode.FileSystemError.FileNotFound(uri); }
        if (e.type !== 'dir') { throw vscode.FileSystemError.FileNotADirectory(uri); }
        const all = await tx('readonly', (s) => wrap<Entry[]>(s.getAll() as IDBRequest<Entry[]>));
        return all
            .filter((x) => parentOf(x.path) === dir && x.path !== '/')
            .map((x): [string, vscode.FileType] => [nameOf(x.path), x.type === 'dir' ? vscode.FileType.Directory : vscode.FileType.File]);
    }

    async createDirectory(uri: vscode.Uri): Promise<void> {
        const p = norm(uri);
        if (p === '/') { return; }
        const parent = await this.entry(parentOf(p));
        if (!parent) { throw vscode.FileSystemError.FileNotFound(uri.with({ path: parentOf(p) })); }
        const existing = await this.entry(p);
        if (existing) {
            if (existing.type === 'dir') { return; }
            throw vscode.FileSystemError.FileExists(uri);
        }
        const now = Date.now();
        await tx('readwrite', (s) => wrap(s.put({ path: p, type: 'dir', ctime: now, mtime: now } as Entry)));
        this.fire(vscode.FileChangeType.Created, uri);
    }

    async readFile(uri: vscode.Uri): Promise<Uint8Array> {
        const e = await this.entry(norm(uri));
        if (!e || e.type !== 'file') { throw vscode.FileSystemError.FileNotFound(uri); }
        return e.data ? new Uint8Array(e.data) : new Uint8Array(0);
    }

    async writeFile(uri: vscode.Uri, content: Uint8Array, options: { create: boolean; overwrite: boolean }): Promise<void> {
        const p = norm(uri);
        const existing = await this.entry(p);
        if (!existing && !options.create) { throw vscode.FileSystemError.FileNotFound(uri); }
        if (existing && !options.overwrite) { throw vscode.FileSystemError.FileExists(uri); }
        if (existing && existing.type === 'dir') { throw vscode.FileSystemError.FileIsADirectory(uri); }
        await this.ensureParents(p);
        const now = Date.now();
        const entry: Entry = {
            path: p,
            type: 'file',
            ctime: existing?.ctime ?? now,
            mtime: now,
            data: new Uint8Array(content),
        };
        await tx('readwrite', (s) => wrap(s.put(entry)));
        this.fire(existing ? vscode.FileChangeType.Changed : vscode.FileChangeType.Created, uri);
    }

    /** Every folder on the way is made, as `mkdir -p` would (a save into a new folder just works). */
    private async ensureParents(p: string): Promise<void> {
        const parts = p.split('/').filter(Boolean);
        parts.pop();
        let at = '';
        for (const part of parts) {
            at += '/' + part;
            const e = await this.entry(at);
            if (!e) {
                const now = Date.now();
                await tx('readwrite', (s) => wrap(s.put({ path: at, type: 'dir', ctime: now, mtime: now } as Entry)));
            } else if (e.type !== 'dir') {
                throw vscode.FileSystemError.FileNotADirectory(vscode.Uri.from({ scheme: PROJECTS_SCHEME, path: at }));
            }
        }
    }

    async delete(uri: vscode.Uri, options: { recursive: boolean }): Promise<void> {
        const p = norm(uri);
        const e = await this.entry(p);
        if (!e) { throw vscode.FileSystemError.FileNotFound(uri); }
        const all = await tx('readonly', (s) => wrap<Entry[]>(s.getAll() as IDBRequest<Entry[]>));
        const under = all.filter((x) => x.path === p || x.path.startsWith(p + '/'));
        if (e.type === 'dir' && under.length > 1 && !options.recursive) {
            throw vscode.FileSystemError.NoPermissions(uri);
        }
        await tx('readwrite', async (s) => {
            for (const x of under) { await wrap(s.delete(x.path)); }
        });
        this.fire(vscode.FileChangeType.Deleted, uri);
    }

    async rename(from: vscode.Uri, to: vscode.Uri, options: { overwrite: boolean }): Promise<void> {
        const src = norm(from);
        const dst = norm(to);
        const e = await this.entry(src);
        if (!e) { throw vscode.FileSystemError.FileNotFound(from); }
        const already = await this.entry(dst);
        if (already && !options.overwrite) { throw vscode.FileSystemError.FileExists(to); }
        await this.ensureParents(dst);
        const all = await tx('readonly', (s) => wrap<Entry[]>(s.getAll() as IDBRequest<Entry[]>));
        const under = all.filter((x) => x.path === src || x.path.startsWith(src + '/'));
        await tx('readwrite', async (s) => {
            for (const x of under) {
                await wrap(s.delete(x.path));
                await wrap(s.put({ ...x, path: dst + x.path.slice(src.length), mtime: Date.now() }));
            }
        });
        this.fire(vscode.FileChangeType.Deleted, from);
        this.fire(vscode.FileChangeType.Created, to);
    }

    async copy(from: vscode.Uri, to: vscode.Uri, options: { overwrite: boolean }): Promise<void> {
        const src = norm(from);
        const dst = norm(to);
        const e = await this.entry(src);
        if (!e) { throw vscode.FileSystemError.FileNotFound(from); }
        const already = await this.entry(dst);
        if (already && !options.overwrite) { throw vscode.FileSystemError.FileExists(to); }
        await this.ensureParents(dst);
        const all = await tx('readonly', (s) => wrap<Entry[]>(s.getAll() as IDBRequest<Entry[]>));
        const under = all.filter((x) => x.path === src || x.path.startsWith(src + '/'));
        const now = Date.now();
        await tx('readwrite', async (s) => {
            for (const x of under) {
                await wrap(s.put({ ...x, path: dst + x.path.slice(src.length), ctime: now, mtime: now }));
            }
        });
        this.fire(vscode.FileChangeType.Created, to);
    }
}

/** Register the provider; returns the root Uri of the projects folder. */
export function registerProjectsFileSystem(ctx: vscode.ExtensionContext): vscode.Uri {
    const provider = new ProjectsFileSystem();
    ctx.subscriptions.push(vscode.workspace.registerFileSystemProvider(PROJECTS_SCHEME, provider, { isCaseSensitive: true }));
    return PROJECTS_ROOT;
}
