const READ_FIELDS: [string, string][] = [
    ['v', 'str(evn.version)'],
    ['mp', 'os.uname().version'],
    ['mv', 'evn.battery.voltage()'],
    ['cells', 'list(evn.battery.cells())'],
    ['files', '[[f, os.stat("/" + f)[6]] for f in os.listdir("/")]'],
];

/** One JSON line with everything the view shows; every value is wrapped on its own, so one
 *  missing attribute (an older firmware) does not lose the rest. */
const READ_SCRIPT = [
    'import os, json', 'd = {}', 'try:', '    import evn', 'except Exception:', '    evn = None',
    ...READ_FIELDS.map(([key, expr]) => `try:\n    d["${key}"] = ${expr}\nexcept Exception:\n    pass`),
    'print(json.dumps(d))',
].join('\n');

