/** The baud rate a UART header runs at when it was never chosen. */
const DEFAULT_BAUD = 115200;
/** What the board accepts (the firmware raises ValueError outside this range). */
const MIN_BAUD = 300;
const MAX_BAUD = 3000000;
/** The usual baud rates, offered before "Other...". */
const BAUD_CHOICES = [9600, 19200, 38400, 57600, 115200, 230400, 460800, 921600];

/** The baud of a serial setting, whatever an older configuration left behind. */
function baudOf(s: SerialSetting | undefined): number {
    const b = s?.baud;
    return typeof b === 'number' && b >= MIN_BAUD && b <= MAX_BAUD ? Math.round(b) : DEFAULT_BAUD;
}

/** Ask for the baud rate of a UART header: the usual eight, or any number the board accepts. */
async function askBaud(port: number, current: number): Promise<number | undefined> {
    type BaudPick = vscode.QuickPickItem & { baud?: number; other?: boolean };
    const items: BaudPick[] = BAUD_CHOICES.map((b) => ({
        label: String(b),
        description: b === current ? 'current' : (b === DEFAULT_BAUD ? 'default' : undefined),
        baud: b,
    }));
    items.push({ label: 'Other...', detail: `any whole number from ${MIN_BAUD} to ${MAX_BAUD}`, other: true });
    const pick = await vscode.window.showQuickPick(items, {
        title: `Serial ${port}: how fast does it run?`,
        placeHolder: 'The board opens the UART at this baud rate; both ends have to agree.',
    });
    if (!pick) { return undefined; }
    if (!pick.other) { return pick.baud; }
    const typed = await vscode.window.showInputBox({
        title: `Serial ${port}: baud rate`,
        value: String(current),
        prompt: `A whole number from ${MIN_BAUD} to ${MAX_BAUD}.`,
        validateInput: (v) => {
            const t = v.trim();
            if (!/^[0-9]+$/.test(t)) { return 'a whole number, like 9600'; }
            const n = Number(t);
            if (n < MIN_BAUD || n > MAX_BAUD) { return `the board takes ${MIN_BAUD} to ${MAX_BAUD}`; }
            return undefined;
        },
    });
    if (typed === undefined) { return undefined; }
    return Number(typed.trim());
}

function motorLabel(id: string | undefined): string | undefined {
    if (!id) { return undefined; }
    return MOTOR_MODELS.find((m) => m.id === id)?.label;
}

function servoLabel(id: string | undefined): string {
    if (!id) { return 'nothing'; }
    return SERVO_PROFILES.find((s) => s.id === id)?.label ?? id;
}

