/** One value an action asks the user for. `choices` turns the question into a QuickPick. */
interface Field {
    /** the keyword name (a kwargs field) or a plain label (a positional argument) */
    name: string;
    prompt: string;
    /** number: parsed as a number; bool: on/off; list: whitespace- or comma-separated numbers */
    kind: 'number' | 'string' | 'bool' | 'list';
    choices?: string[];
}

/** One settable property of a device kind, built from stubs/evn.pyi. */
interface Setter {
    label: string;
    method: string;
    detail: string;
    /** asked for in order and sent as `args` */
    args?: Field[];
    /** asked for in order and sent as `kwargs`; an empty answer is left out (the API keeps the value) */
    kwargs?: Field[];
    /** always sent as `kwargs` on top of the answers (wait=False so the call does not block) */
    fixed?: Record<string, any>;
}

const num = (name: string, prompt: string, choices?: string[]): Field => ({ name, prompt, kind: 'number', choices });
const str = (name: string, prompt: string, choices?: string[]): Field => ({ name, prompt, kind: 'string', choices });
const bool = (name: string, prompt: string): Field => ({ name, prompt, kind: 'bool', choices: ['on', 'off'] });

