/* ---- helpers -------------------------------------------------------------------------- */

/** "0.2.15" out of "0.2.15", "v0.2.15" or "(0, 2, 15)"; undefined when there are no numbers. */
function normalizeVersion(raw: string | undefined): string | undefined {
    if (!raw) { return undefined; }
    const dotted = raw.match(/\d+(?:\.\d+)+/);
    if (dotted) { return dotted[0]; }
    const parts = raw.match(/\d+/g);
    return parts && parts.length ? parts.join('.') : undefined;
}

/** -1 / 0 / 1 comparing dotted version numbers part by part. */
function compareVersions(a: string, b: string): number {
    const pa = a.split('.').map((s) => parseInt(s, 10) || 0);
    const pb = b.split('.').map((s) => parseInt(s, 10) || 0);
    for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
        const x = pa[i] ?? 0, y = pb[i] ?? 0;
        if (x !== y) { return x < y ? -1 : 1; }
    }
    return 0;
}

/* firmware/BUILD.txt is read once at activation (the tree items are built synchronously, and
 * vscode.workspace.fs - the one reader both hosts have - is asynchronous). */
let bundledBuild: { version?: string; text: string } = { version: undefined, text: '' };

async function loadBundledVersion(ctx: vscode.ExtensionContext): Promise<void> {
    try {
        const bytes = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(ctx.extensionUri, 'firmware', 'BUILD.txt'));
        const text = new TextDecoder().decode(bytes).trim();
        const m = text.match(/^version:\s*(.+)$/m);
        bundledBuild = { version: normalizeVersion(m ? m[1].trim() : undefined), text };
    } catch (e) {
        log(`board view: no firmware/BUILD.txt (${e})`);
        bundledBuild = { version: undefined, text: '' };
    }
}

function bundledVersion(_ctx: vscode.ExtensionContext): { version?: string; text: string } {
    return bundledBuild;
}

/** "just now", "12 seconds ago", "3 minutes ago", "2 hours ago", "5 days ago", "2 months ago". */
function agoText(d: Date): string {
    const secs = Math.max(0, Math.floor((Date.now() - d.getTime()) / 1000));
    const unit = (n: number, one: string) => `${n} ${one}${n === 1 ? '' : 's'} ago`;
    if (secs < 5) { return 'just now'; }
    if (secs < 60) { return unit(secs, 'second'); }
    const mins = Math.floor(secs / 60);
    if (mins < 60) { return unit(mins, 'minute'); }
    const hours = Math.floor(mins / 60);
    if (hours < 24) { return unit(hours, 'hour'); }
    const days = Math.floor(hours / 24);
    if (days < 30) { return unit(days, 'day'); }
    const months = Math.floor(days / 30);
    if (months < 12) { return unit(months, 'month'); }
    return unit(Math.floor(months / 12), 'year');
}

function sizeText(bytes: number): string {
    if (bytes < 0) { return 'folder'; }
    return bytes === 1 ? '1 byte' : `${bytes} bytes`;
}

function hex(addr: number): string {
    return `0x${addr.toString(16).padStart(2, '0')}`;
}

function volts(mv: number): string {
    return `${(mv / 1000).toFixed(2)} V`;
}

function degrees(v: number | null | undefined): string {
    return typeof v === 'number' ? `${Math.round(v)}°` : '?';
}

function speed(v: number | null | undefined): string {
    return typeof v === 'number' ? `${Math.round(v)} °/s` : '?';
}

/** At most two decimals, and no trailing ".00" (a row is narrow). */
function roundText(n: number): string {
    if (!isFinite(n)) { return String(n); }
    return String(Math.round(n * 100) / 100);
}

/** A watched value in as few characters as possible: `12° 80 40`, `1 2 3`, `12.5`, `yes`. */
function valueText(v: any): string {
    if (v === null || v === undefined) { return 'none'; }
    if (typeof v === 'number') { return roundText(v); }
    if (typeof v === 'boolean') { return v ? 'yes' : 'no'; }
    if (typeof v === 'string') { return v; }
    if (Array.isArray(v)) { return v.map(valueText).join(' '); }
    if (typeof v === 'object') {
        // an evn.Color comes over the wire as {h, s, v}; bytes as {hex: "aabb"}
        if (typeof v.h === 'number' && typeof v.s === 'number' && typeof v.v === 'number') {
            return `${Math.round(v.h)}° ${Math.round(v.s)} ${Math.round(v.v)}`;
        }
        if (typeof v.hex === 'string') { return v.hex; }
        return Object.entries(v).map(([k, x]) => `${k} ${valueText(x)}`).join(' ');
    }
    return String(v);
}

/** One row of a watched device: `hsv 12° 80 40`, or `hsv: OSError ...` when the call raised. */
function watchText(w: WatchValue): string {
    const name = w.m || 'value';
    if (typeof w.e === 'string' && w.e) {
        const line = w.e.split(/\r?\n/).map((s) => s.trim()).filter(Boolean).pop() ?? w.e;
        return `${name}: ${line}`;
    }
    return `${name} ${valueText(w.v)}`;
}

/** "1 byte" / "12 bytes". */
function byteText(n: number): string {
    return n === 1 ? '1 byte' : `${n} bytes`;
}

/** evn.Bluetooth.state() in words. */
function btStateText(state: string | undefined): string {
    switch (state) {
        case 'data': return 'data mode';
        case 'command': return 'command mode';
        case 'probing': return 'looking for the module';
        case 'configuring': return 'setting the module up';
        case 'resetting': return 'restarting the module';
        case 'closed': return 'closed';
        default: return state ? state : 'unknown state';
    }
}

/* ---- the tree ------------------------------------------------------------------------- */

type ItemKind =
    | 'console' | 'commands' | 'port' | 'firmware' | 'battery'
    | 'motorsRoot' | 'motor' | 'servosRoot' | 'servo' | 'serialRoot' | 'serial'
    | 'devicesRoot' | 'device' | 'filesRoot' | 'file' | 'placeholder';

class BoardItem extends vscode.TreeItem {
    fileName?: string;
    /** 1..4 for a motor or servo row, 1..2 for a serial row, 1..16 for an I2C device row */
    portNumber?: number;
    /** the `evn` class name of an identified I2C device ('ColorSensor', ...) */
    deviceKind?: string;
    constructor(
        public readonly kind: ItemKind,
        label: string,
        collapsible: vscode.TreeItemCollapsibleState = vscode.TreeItemCollapsibleState.None,
    ) {
        super(label, collapsible);
    }
}

class BoardProvider implements vscode.TreeDataProvider<BoardItem> {
    private readonly emitter = new vscode.EventEmitter<BoardItem | undefined>();
    readonly onDidChangeTreeData = this.emitter.event;
    reading: Reading | undefined;
    battery: Battery | undefined;
    busy = false;
    /** why a serial port has no object on the board, from the last `configure` answer */
    readonly serialErrors = new Map<number, string>();
    /** the item instances, so a single row can be refreshed without redrawing the tree */
    private readonly cache = new Map<string, BoardItem>();

    constructor(
        private readonly ctx: vscode.ExtensionContext,
        private readonly config: () => PortConfig,
        private readonly watches: () => Record<string, WatchSpec>,
    ) { }

    refresh(): void { this.emitter.fire(undefined); }

    /** Redraw only the rows that telemetry changes: battery, the four motor ports and every
     *  I2C device that is being read live (its value rides along in the telemetry packet). */
    refreshLive(): void {
        const live: BoardItem[] = [this.batteryItem(), ...[1, 2, 3, 4].map((p) => this.motorItem(p))];
        const watched = this.watches();
        if (Object.keys(watched).length) {
            for (const d of latestDevices() ?? []) {
                if (watched[String(d.port)]) { live.push(this.deviceItem(d)); }
            }
        }
        for (const item of live) { this.emitter.fire(item); }
    }

    /** Redraw the two serial rows (a `serial` event arrived). */
    refreshSerial(): void {
        for (const p of [1, 2]) { this.emitter.fire(this.serialItem(p)); }
    }

    getTreeItem(element: BoardItem): vscode.TreeItem { return element; }

    getChildren(element?: BoardItem): BoardItem[] {
        // no mpremote: no items at all, so the view's welcome content (with Install) shows instead
        if (!boardState().hasMpremote) { return []; }
        if (!element) {
            const rows: BoardItem[] = [this.consoleItem()];
            if (consoleLive()) { rows.push(this.commandsItem()); }
            rows.push(
                this.portItem(), this.firmwareItem(), this.batteryItem(),
                this.motorsRootItem(), this.servosRootItem(), this.serialRootItem(),
                this.devicesRootItem(), this.filesRootItem(),
            );
            return rows;
        }
        switch (element.kind) {
            case 'motorsRoot': return [1, 2, 3, 4].map((p) => this.motorItem(p));
            case 'servosRoot': return [1, 2, 3, 4].map((p) => this.servoItem(p));
            case 'serialRoot': return [1, 2].map((p) => this.serialItem(p));
            case 'devicesRoot': return this.deviceItems();
            case 'filesRoot': return this.fileItems();
            default: return [];
        }
    }

    /** The one instance of a row, blanked and ready to be filled again. */
    private row(id: string, kind: ItemKind, label: string, collapsible = vscode.TreeItemCollapsibleState.None): BoardItem {
        let item = this.cache.get(id);
        if (!item) {
            item = new BoardItem(kind, label, collapsible);
            item.id = id;
            this.cache.set(id, item);
        }
        item.label = label;
        item.description = undefined;
        item.tooltip = undefined;
        item.command = undefined;
        item.contextValue = undefined;
        item.iconPath = undefined;
        return item;
    }

    /** "last read 3 minutes ago, board unplugged" once the board is gone but a reading is up. */
    private staleNote(): string | undefined {
        const st = boardState();
        if (this.reading && !st.present) { return `last read ${agoText(this.reading.at)}, board unplugged`; }
        return undefined;
    }

    /* ---- the console row ---------------------------------------------------------------- */

    private consoleItem(): BoardItem {
        const state = consoleState();
        const detail = consoleDetail();
        // the same link, reached over the air: the row says so, because the cable can be out
        const wireless = consoleTransport() === 'bluetooth';
        const item = this.row('console', 'console', 'Live console');
        switch (state) {
            case 'live': {
                // how often the board really sends telemetry: four times a second over USB, and
                // whatever evn.console.bluetoothRate says over the air. The row repeats what the
                // helper reported rather than a hard-coded 4, so the number is never a lie.
                const rate = consoleStatus().rate ?? 4;
                const updates = `${rate} updates/s`;
                const times = rate === 4 ? 'four times a second' : `${rate} times a second`;
                if (wireless) {
                    const via = consoleStatus().port;
                    // on the link because the user asked for it, not because the cable is out
                    const chosen = wirelessPreferred();
                    item.label = chosen
                        ? 'Live console: connected over Bluetooth (USB ignored)'
                        : 'Live console: connected over Bluetooth';
                    item.description = via ? `${updates} · ${via}` : updates;
                    item.contextValue = 'evnBoardConsoleLive';
                    item.iconPath = new vscode.ThemeIcon('broadcast', new vscode.ThemeColor('charts.green'));
                    item.tooltip = `The extension is talking to the board over its wireless link${via ? ` (${via})` : ''}: motor angles, battery and the I2C ports ${times}.${detail ? `\n\n${detail}` : ''}\n\n`
                        + (chosen
                            ? 'You asked for the wireless link with the arrow-swap button on the Bluetooth serial row, so the cable is ignored for now. The same button there ("Switch the board back to USB") hands USB back, and so does restarting VS Code: the choice is never saved.'
                            : 'The USB cable can stay out. Put it back in and the console moves to USB by itself, with your ports, your live reads and your settings.');
                    break;
                }
                item.label = 'Live console: connected';
                item.description = updates;
                item.contextValue = 'evnBoardConsoleLive';
                item.iconPath = new vscode.ThemeIcon('plug', new vscode.ThemeColor('charts.green'));
                item.tooltip = `The extension is talking to the board: motor angles, battery and the I2C ports ${times}.${detail ? `\n\n${detail}` : ''}\n\nIt lets go of the port by itself when you run a program or open the REPL.`;
                break;
            }
            case 'connecting':
                item.label = 'Live console: connecting...';
                item.description = detail || undefined;
                item.contextValue = 'evnBoardConsoleConnecting';
                item.iconPath = new vscode.ThemeIcon('plug');
                item.tooltip = 'Opening the port and starting the agent on the board.';
                break;
            case 'busy':
                item.label = "Board is running its program (main.py)";
                item.description = 'not interrupted';
                item.contextValue = 'evnBoardConsoleBusy';
                item.iconPath = new vscode.ThemeIcon('debug-pause', new vscode.ThemeColor('list.warningForeground'));
                item.tooltip = 'The board started its own program at power-on. Nothing here interrupts it. Its output is in the "EVN Console" panel. Use the stop button to end it and connect the live console.';
                break;
            case 'paused':
                item.label = 'Live console: paused';
                item.description = detail || 'paused by you';
                item.contextValue = 'evnBoardConsolePaused';
                item.iconPath = new vscode.ThemeIcon('debug-pause');
                item.tooltip = `The live console let go of the port: ${detail || 'you paused it'}. It comes back by itself when the port is free; the plug button connects it now.`;
                break;
            case 'gone':
                if (wireless) {
                    item.label = 'Live console: the Bluetooth link dropped';
                    item.description = detail || 'out of range or switched off';
                    item.contextValue = 'evnBoardConsoleGone';
                    item.iconPath = new vscode.ThemeIcon('warning', new vscode.ThemeColor('list.warningForeground'));
                    item.tooltip = `The wireless link stopped answering: ${detail || 'out of range, or the board was switched off'}.\n\nNothing to do: the console keeps trying by itself, and it comes back when the board is in range again - or straight away over USB when you put the cable in.`;
                    break;
                }
                item.label = 'Live console: the board is gone';
                item.description = detail || 'unplugged';
                item.contextValue = 'evnBoardConsoleGone';
                item.iconPath = new vscode.ThemeIcon('warning', new vscode.ThemeColor('list.warningForeground'));
                item.tooltip = `The board disappeared from USB: ${detail || 'unplugged or reset'}. Plug it back in; the console reconnects by itself.`;
                break;
            case 'error':
                item.label = 'Live console: not connected';
                item.description = detail || 'error';
                item.contextValue = 'evnBoardConsoleError';
                item.iconPath = new vscode.ThemeIcon('warning', new vscode.ThemeColor('list.errorForeground'));
                item.tooltip = `The live console could not be started: ${detail || 'unknown error'}. Click the plug to try again; the "EVN ALPHA" output panel has the details.`;
                break;
            default: {
                const off = !vscode.workspace.getConfiguration('evn').get<boolean>('console.enabled', true);
                item.label = 'Live console: off';
                item.description = off ? 'evn.console.enabled' : (detail || 'not connected');
                item.contextValue = 'evnBoardConsoleOff';
                item.iconPath = new vscode.ThemeIcon('plug');
                item.tooltip = off
                    ? 'The live console is switched off in the settings (evn.console.enabled). Click the plug to switch it on.'
                    : `The live console is not connected${detail ? `: ${detail}` : ''}. Click the plug to connect.`;
                break;
            }
        }
        return item;
    }

    private commandsItem(): BoardItem {
        const item = this.row('commands', 'commands', 'Command line');
        item.description = 'send Python to the board';
        item.contextValue = 'evnBoardCommands';
        item.iconPath = new vscode.ThemeIcon('terminal');
        item.command = { command: 'evn.console.send', title: 'Send a command to the board' };
        item.tooltip = 'Run one line of Python on the board right now: m1..m4 are the four motors, s1..s4 the servos you configured, evn is imported. The answer goes to the "EVN Console" panel.';
        return item;
    }

    /* ---- the board rows ----------------------------------------------------------------- */

    private portItem(): BoardItem {
        const st = boardState();
        const bootsel = st.bootsel;
        if (bootsel && !st.present) {
            const item = this.row('port', 'port', 'Board in UF2 (BOOTSEL) mode');
            item.description = 'flash the firmware';
            item.contextValue = 'evnBoardPortBootsel';
            item.iconPath = new vscode.ThemeIcon('circuit-board', new vscode.ThemeColor('list.warningForeground'));
            item.tooltip = `The board is a USB drive (${bootsel}), not a MicroPython board: it is waiting for firmware. Use the flash button to write the bundled firmware, then the board restarts by itself.`;
            return item;
        }
        const label = st.port ? (st.name ? `${st.port} · ${st.name}` : st.port) : 'No board on USB';
        const item = this.row('port', 'port', label);
        item.contextValue = st.present ? 'evnBoardPortPresent' : 'evnBoardPortAbsent';
        item.iconPath = new vscode.ThemeIcon('circuit-board');
        item.command = { command: 'evn.selectPort', title: 'Choose the board port' };
        if (!st.port) {
            item.description = 'plug it in';
            item.tooltip = 'No EVN ALPHA found on USB. Plug the board in with the USB cable and switch it on. Click to choose a port by hand.';
        } else if (!st.present) {
            item.description = 'configured port not present';
            item.tooltip = `The port ${st.port} is set in the settings but nothing is on it right now. Click to choose another port.`;
            item.iconPath = new vscode.ThemeIcon('circuit-board', new vscode.ThemeColor('list.warningForeground'));
        } else if (st.boards > 1) {
            item.description = `${st.boards} boards, click to choose`;
            item.tooltip = `${st.boards} EVN ALPHA boards are plugged in; this one is in use. Click to choose another.`;
        } else {
            item.description = 'connected';
            item.tooltip = `The EVN ALPHA is on ${st.port}${st.name ? ` ("${st.name}")` : ''}. Click to choose another port.`;
        }
        if (portBusy()) {
            item.description = 'in use by the program terminal';
            item.tooltip = 'Your program (or the REPL) is using the board. Close the EVN ALPHA terminal, or stop the program, before reading the board.';
        }
        return item;
    }

    private firmwareItem(): BoardItem {
        const bundled = bundledVersion(this.ctx);
        const board = this.reading?.version;
        const item = this.row('firmware', 'firmware', board ? `Firmware ${board}` : 'Firmware: not read');
        item.iconPath = new vscode.ThemeIcon('chip');
        item.tooltip = bundled.text || undefined;
        if (!board) {
            item.description = 'click Read the board';
            item.command = { command: 'evn.refreshBoard', title: 'Read the board' };
            item.tooltip = `The board has not been read yet. Click to read it.${bundled.version ? `\n\nThe extension brings firmware ${bundled.version}.` : ''}\n\n${bundled.text}`;
            return item;
        }
        const stale = this.staleNote();
        if (!bundled.version) {
            item.description = stale ?? 'on the board';
        } else {
            const cmp = compareVersions(board, bundled.version);
            if (cmp < 0) {
                item.description = stale ?? `board has ${board}, bundled ${bundled.version}: update`;
                item.contextValue = 'evnBoardFirmwareOutdated';
                item.iconPath = new vscode.ThemeIcon('warning', new vscode.ThemeColor('list.warningForeground'));
                item.command = { command: 'evn.flashFirmware', title: 'Flash the bundled firmware' };
                item.tooltip = `The board runs firmware ${board}; this extension brings ${bundled.version}. Click to flash the newer one (your files on the board are kept).\n\n${bundled.text}`;
            } else if (cmp > 0) {
                item.description = stale ?? 'newer than the bundled build';
                item.tooltip = `The board runs firmware ${board}, which is newer than the ${bundled.version} this extension brings. Nothing to do.\n\n${bundled.text}`;
            } else {
                item.description = stale ?? 'up to date';
                item.tooltip = `The board runs firmware ${board}, the same as this extension brings.\n\n${bundled.text}`;
            }
        }
        if (this.reading?.micropython) { item.tooltip = `MicroPython: ${this.reading.micropython}\n\n${item.tooltip ?? ''}`.trim(); }
        if (this.reading?.fs && this.reading.fs.length === 2) {
            const [total, free] = this.reading.fs;
            item.tooltip = `${item.tooltip ?? ''}\n\nFlash: ${Math.round(free / 1024)} kB free of ${Math.round(total / 1024)} kB.`.trim();
        }
        return item;
    }

    /** The pack is always two cells in series: 8.12 V, "4.06 V / 4.06 V". */
    private batteryItem(): BoardItem {
        const b = this.battery;
        const item = this.row('battery', 'battery', b ? `Battery ${volts(b.millivolts)}` : 'Battery: not read');
        item.iconPath = new vscode.ThemeIcon('zap');
        if (!b) {
            item.description = 'click Read the board';
            item.command = { command: 'evn.refreshBoard', title: 'Read the board' };
            item.tooltip = 'The battery voltage has not been read yet. Click to read the board (or connect the live console).';
            return item;
        }
        const pack = b.millivolts / 1000;
        const cells = b.cells && b.cells.length >= 2 ? b.cells.slice(0, 2) : undefined;
        const stale = this.staleNote();
        item.description = stale ?? (cells ? `${volts(cells[0])} / ${volts(cells[1])}` : '2-cell pack');
        const cellText = cells
            ? `The two cells are at ${volts(cells[0])} and ${volts(cells[1])}.`
            : 'The two cell voltages were not reported.';
        item.tooltip = `${pack.toFixed(2)} V at the 2-cell pack. ${cellText}`;
        if (pack < PACK_LOW_V) {
            item.iconPath = new vscode.ThemeIcon('zap', new vscode.ThemeColor('list.errorForeground'));
            item.tooltip += ` Below ${PACK_LOW_V.toFixed(1)} V (3.3 V a cell) the board is about to switch off: change the cells now.`;
        } else if (pack < PACK_WARN_V) {
            item.iconPath = new vscode.ThemeIcon('zap', new vscode.ThemeColor('list.warningForeground'));
            item.tooltip += ` Below ${PACK_WARN_V.toFixed(1)} V (3.6 V a cell) the pack is getting low; have fresh cells ready.`;
        } else {
            item.tooltip += ' That is a healthy level.';
        }
        if (cells && Math.abs(cells[0] - cells[1]) > 200) {
            item.tooltip += ' The two cells are more than 0.2 V apart, which usually means one of them is worn out.';
        }
        return item;
    }

    /* ---- motors ------------------------------------------------------------------------- */

    private motorsRootItem(): BoardItem {
        const item = this.row('motorsRoot', 'motorsRoot', 'Motors', vscode.TreeItemCollapsibleState.Expanded);
        item.iconPath = new vscode.ThemeIcon('gear');
        item.contextValue = 'evnBoardMotors';
        item.tooltip = 'The four motor ports. The angles and speeds are live while the console is connected.';
        return item;
    }

    private motorItem(port: number): BoardItem {
        const item = this.row(`motor:${port}`, 'motor', `Port ${port}`);
        item.portNumber = port;
        const id = this.config().motors[String(port)] ?? '';
        // ...Set is what the menus hang the play / target / stop buttons on: no model, no buttons
        item.contextValue = id ? 'evnBoardMotorPortSet' : 'evnBoardMotorPort';
        item.iconPath = new vscode.ThemeIcon('debug-step-over');
        const model = motorLabel(id);
        const tele = consoleLive() ? latestTelemetry() : undefined;
        const i = port - 1;
        const angle = tele?.enc?.[i];
        const spd = tele?.spd?.[i];
        const readings = tele
            ? (angle === null || angle === undefined ? 'not readable' : `${degrees(angle)} · ${speed(spd)}`)
            : '—';
        item.description = model ? `${model} · ${readings}` : readings;
        const buttons = id && consoleLive()
            ? '\n\nThe buttons run it: play asks for a speed, the target button for a speed and an angle, the square stops it.'
            : '';
        item.tooltip = `Motor port ${port}${model ? `: ${model}` : ''}. ${tele ? 'The angle and speed come from the live console.' : 'Connect the live console to see the angle and speed.'}\n\nClick the gear to say what is connected (this is a note for you; the firmware decides the real motor settings).${buttons}\n\nIt is m${port} in the command line.`;
        return item;
    }

    /* ---- servo ports -------------------------------------------------------------------- */

    private servosRootItem(): BoardItem {
        const item = this.row('servosRoot', 'servosRoot', 'Servo ports', vscode.TreeItemCollapsibleState.Collapsed);
        item.iconPath = new vscode.ThemeIcon('gear');
        item.contextValue = 'evnBoardServos';
        item.tooltip = 'What is plugged into each of the four servo ports. The live console creates the matching object (s1..s4, or l1..l4 for an LED strip) so you can use it in the command line.';
        return item;
    }

    private servoItem(port: number): BoardItem {
        const item = this.row(`servo:${port}`, 'servo', `Servo port ${port}`);
        item.portNumber = port;
        const id = this.config().servos[String(port)] ?? '';
        // ...Set is what the menus hang the play / stop buttons on: nothing configured, no buttons
        item.contextValue = id ? 'evnBoardServoPortSet' : 'evnBoardServoPort';
        item.iconPath = new vscode.ThemeIcon('symbol-event');
        item.description = servoLabel(id);
        const name = id === 'rgbled' ? `l${port}` : `s${port}`;
        const what = id === 'rgbled' ? 'the play button picks a colour, the square switches the strip off'
            : id === 'geekservo_cr' ? 'the play button asks for a speed in percent, the square stops it'
                : 'the play button asks for an angle, the square lets the servo go';
        item.tooltip = id
            ? `Servo port ${port}: ${servoLabel(id)}. It is ${name} in the command line.\n\nClick the gear to change it.${consoleLive() ? `\n\nWhile the console is live ${what}.` : ''}`
            : `Nothing is set for servo port ${port}. Click the gear to say what is plugged in; the live console then creates the object for it.`;
        return item;
    }

    /* ---- serial ports ------------------------------------------------------------------- */

    private serialRootItem(): BoardItem {
        const item = this.row('serialRoot', 'serialRoot', 'Serial ports', vscode.TreeItemCollapsibleState.Expanded);
        item.iconPath = new vscode.ThemeIcon('radio-tower');
        item.contextValue = 'evnBoardSerials';
        item.tooltip = 'The two serial headers. Say what is on each one with the gear; the live console then creates the object for it (bt1 / bt2 for an EVN Bluetooth module, u1 / u2 for a raw UART).\n\nAn EVN Bluetooth module can carry the board\'s REPL, and then the whole extension works over the air, without the USB cable.';
        return item;
    }

    private serialItem(port: number): BoardItem {
        const item = this.row(`serial:${port}`, 'serial', `Serial ${port}`);
        item.portNumber = port;
        item.iconPath = new vscode.ThemeIcon('broadcast');
        const setting = this.config().serial[String(port)];
        const kind = setting?.kind ?? '';
        const status = kind ? latestSerial()?.find((s) => s.port === port) : undefined;
        const failed = this.serialErrors.get(port);
        if (kind === 'bluetooth') {
            // the wireless link belongs to the board, not to the header: it is keyed by the board's serial
            const link = bluetoothLinkFor(boardState().serial);
            // the arrow-swap button puts the console on the link with the cable still in: the row
            // has to say so, because USB being present no longer means USB is in use
            const chosen = wirelessPreferred();
            item.contextValue = 'evnBoardSerialPortBluetooth';
            item.description = `Bluetooth · ${this.serialDetail(status, failed, true)} · ${link ? `link ${linkLabel(link)}` : 'no wireless link'}`
                + (chosen ? ' · on the wireless link by choice' : '');
            item.tooltip =
                `Serial ${port}: an EVN Bluetooth module (an HC-05 at 230400 baud). It is bt${port} in the command line: `
                + `bt${port}.write(b"hello"), bt${port}.read(), bt${port}.repl(True).\n\n`
                + 'Three buttons, once each: pair the module in Windows (the link button; it shows up as "HC-05" or "EVN Bluetooth", the PIN is 1234), '
                + 'put the board\'s REPL on the module (the broadcast button), then choose its "Standard Serial over Bluetooth link (COMxx)" port as the wireless link of this board (the plug button).\n\n'
                + (link
                    ? `The wireless link of this board is ${linkLabel(link)}${link.description ? ` ("${link.description}")` : ''}. `
                    : 'This board has no wireless link yet. ')
                + 'From then on, unplugging the USB cable moves the live console to Bluetooth by itself, and plugging it back in moves it to USB - with the same ports, live reads and settings, because they follow the board.\n\n'
                + (chosen
                    ? 'The console is on the link right now because you asked for it: the USB cable is ignored until you press the arrow-swap button ("Switch the board back to USB"), or until VS Code restarts - the choice is never saved.'
                    : 'The arrow-swap button tries that failover without pulling the cable: "Switch the board to Bluetooth now" moves the console onto the link while the cable stays in, and the same button ("Switch the board back to USB") ends it. Restarting VS Code ends it too: the choice is never saved.')
                + '\n\nThe link is kept by the module\'s own Bluetooth address rather than by its COM number, so it still finds this board when Windows renumbers the port. Windows\' incoming Bluetooth ports - one per adapter, they can never reach a module - are left out of the picker.';
            return item;
        }
        if (kind === 'uart') {
            const baud = baudOf(setting);
            item.contextValue = 'evnBoardSerialPortUart';
            item.description = `UART ${baud} · ${this.serialDetail(status, failed, false)}`;
            item.tooltip =
                `Serial ${port}: a raw UART at ${baud} baud. It is u${port} in the command line: `
                + `u${port}.write(b"hello"), u${port}.read(), u${port}.any().\n\nClick the gear to change the baud rate, or what is on this header.`;
            return item;
        }
        item.contextValue = 'evnBoardSerialPort';
        item.description = 'nothing';
        item.tooltip =
            `Nothing is set for serial port ${port}. Click the gear to say what is on the header: an EVN Bluetooth module `
            + `(bt${port} in the command line, and it can carry the board's REPL so the extension works without the USB cable) `
            + `or a raw UART at the baud rate you choose (u${port}).`;
        return item;
    }

    /** The part of a serial row's description that comes from the board. */
    private serialDetail(status: SerialPortStatus | undefined, failed: string | undefined, bluetooth: boolean): string {
        if (status?.err) { return `not answering: ${status.err}`; }
        if (!status) {
            // the object was never created (no module on the header): the configure answer says why
            if (failed) { return `not answering: ${failed}`; }
            return 'waiting for the board';
        }
        const waiting = typeof status.any === 'number' && status.any > 0
            ? `${byteText(status.any)} waiting` : undefined;
        if (!bluetooth) { return waiting ?? '0 bytes waiting'; }
        const bits = [btStateText(status.state), `REPL ${status.repl ? 'on' : 'off'}`];
        if (waiting) { bits.push(waiting); }
        return bits.join(' · ');
    }

    /* ---- I2C devices -------------------------------------------------------------------- */

    private devicesRootItem(): BoardItem {
        const item = this.row('devicesRoot', 'devicesRoot', 'I2C devices', vscode.TreeItemCollapsibleState.Collapsed);
        item.iconPath = new vscode.ThemeIcon('circuit-board');
        item.contextValue = 'evnBoardDevices';
        item.tooltip = 'What answered on the 16 I2C ports, identified by its part-ID register. Refresh the board to scan again.';
        return item;
    }

    private deviceItems(): BoardItem[] {
        if (!consoleLive()) {
            const item = this.row('device:none', 'placeholder', 'I2C ports not scanned');
            item.description = '—';
            item.iconPath = new vscode.ThemeIcon('info');
            item.tooltip = 'The live console is not connected, so the I2C ports have not been scanned.';
            return [item];
        }
        const devices = latestDevices();
        if (!devices) {
            const item = this.row('device:none', 'placeholder', 'scanning...');
            item.iconPath = new vscode.ThemeIcon('info');
            return [item];
        }
        if (!devices.length) {
            const item = this.row('device:none', 'placeholder', 'no devices found');
            item.iconPath = new vscode.ThemeIcon('info');
            item.tooltip = 'Nothing answered on the I2C ports. Check the cables, then refresh the board.';
            return [item];
        }
        return devices.map((d) => this.deviceItem(d));
    }

    private deviceItem(d: I2cDevice): BoardItem {
        const item = this.row(`device:${d.port}:${d.addr}`, 'device', `Port ${d.port}`);
        item.portNumber = d.port;
        item.deviceKind = d.kind ?? undefined;
        item.iconPath = new vscode.ThemeIcon(d.name ? 'plug' : 'question');
        const name = d.name ? `${d.name} (${hex(d.addr)})` : `unknown device at ${hex(d.addr)}`;
        // only an identified device has an evn class, so only it can be set or read from here
        const watch = d.kind ? this.watches()[String(d.port)] : undefined;
        item.contextValue = !d.kind ? 'evnBoardDevice' : (watch ? 'evnBoardDeviceWatched' : 'evnBoardDeviceKnown');
        const value = watch ? latestTelemetry()?.watch?.[String(d.port)] : undefined;
        item.description = watch
            ? (value ? watchText(value) : `${watch.method} ...`)
            : name;
        if (!d.name) {
            item.tooltip = `Something answered on port ${d.port} at address ${hex(d.addr)} but it is not one of the standard peripherals.`;
            return item;
        }
        const lines = [`${d.name} on port ${d.port}, address ${hex(d.addr)}${d.kind ? `.\n\nIn a program: evn.${d.kind}(${d.port})` : '.'}`];
        if (d.kind) {
            lines.push(`It is d${d.port} in the command line.`);
            if (watch) { lines.push(`Being read live: ${watch.method}(). The eye-closed button stops it.`); }
            else if (DEVICE_READERS[d.kind]?.length) { lines.push('The eye button reads it four times a second in this row.'); }
            if (DEVICE_SETTERS[d.kind]?.length) { lines.push('The pencil button changes one of its settings.'); }
        }
        item.tooltip = lines.join('\n\n');
        return item;
    }

    /* ---- files -------------------------------------------------------------------------- */

    private filesRootItem(): BoardItem {
        const item = this.row('filesRoot', 'filesRoot', 'Files on the board', vscode.TreeItemCollapsibleState.Expanded);
        item.iconPath = new vscode.ThemeIcon('folder');
        item.contextValue = 'evnBoardFiles';
        item.tooltip = 'The files stored on the board itself. main.py is the one that runs when the board is switched on.';
        return item;
    }

    private fileItems(): BoardItem[] {
        const files = this.reading?.files;
        if (!files) {
            const empty = this.row('file:none', 'placeholder', 'not read yet: click Read the board');
            empty.iconPath = new vscode.ThemeIcon('info');
            empty.command = { command: 'evn.refreshBoard', title: 'Read the board' };
            return [empty];
        }
        if (!files.length) {
            const empty = this.row('file:none', 'placeholder', 'no files on the board');
            empty.iconPath = new vscode.ThemeIcon('info');
            return [empty];
        }
        const sorted = [...files].sort((a, b) => {
            const am = a.name.toLowerCase() === 'main.py', bm = b.name.toLowerCase() === 'main.py';
            if (am !== bm) { return am ? -1 : 1; }
            return a.name.toLowerCase() < b.name.toLowerCase() ? -1 : a.name.toLowerCase() > b.name.toLowerCase() ? 1 : 0;
        });
        return sorted.map((f) => {
            const isMain = f.name.toLowerCase() === 'main.py';
            const item = this.row(`file:${f.name}`, 'file', f.name);
            item.fileName = f.name;
            item.contextValue = isMain ? 'evnBoardFileMain' : 'evnBoardFile';
            item.iconPath = new vscode.ThemeIcon(isMain ? 'play' : (f.size < 0 ? 'folder' : 'file'));
            item.description = isMain ? 'runs at power-on' : sizeText(f.size);
            item.tooltip = isMain
                ? `main.py (${sizeText(f.size)}) is the program the board runs when it is switched on.`
                : `${f.name} on the board (${sizeText(f.size)}).`;
            return item;
        });
    }
}

/* ---- registration --------------------------------------------------------------------- */

export function registerBoardView(ctx: vscode.ExtensionContext, deps: BoardViewDeps): void {
    void loadBundledVersion(ctx);       // firmware/BUILD.txt, read once (the tree items are sync)
    // The Board view lives in the secondary side bar, which is closed by default: open it once so the
    // panel is discovered (the Start section keeps a "Show the Board panel" link for later).
    const REVEAL_KEY = 'evn.board.revealed.v1';
    if (!ctx.globalState.get<boolean>(REVEAL_KEY)) {
        void ctx.globalState.update(REVEAL_KEY, true);
        setTimeout(() => { void vscode.commands.executeCommand('evn.board.focus'); }, 2500);
    }
    /* what is plugged into the ports, remembered per board (by USB serial when it is known) */
    const boardKey = (): string => {
        const st = boardState();
        return st.serial ?? st.port ?? 'default';
    };
    const configKey = (): string => `evn.portConfig.${boardKey()}`;
    /** The serial headers as they are stored, with the plain strings 0.2.15 and older wrote
     *  ('bluetooth' / 'uart') read as settings, so nobody has to set their headers up again. */
    const readSerial = (raw: unknown): Record<string, SerialSetting> => {
        const out: Record<string, SerialSetting> = {};
        if (!raw || typeof raw !== 'object') { return out; }
        for (const [port, value] of Object.entries(raw as Record<string, unknown>)) {
            if (value === 'bluetooth') { out[port] = { kind: 'bluetooth' }; continue; }
            if (value === 'uart') { out[port] = { kind: 'uart', baud: DEFAULT_BAUD }; continue; }
            if (!value || typeof value !== 'object') { continue; }
            const setting = value as SerialSetting;
            if (setting.kind === 'bluetooth') { out[port] = { kind: 'bluetooth' }; }
            if (setting.kind === 'uart') { out[port] = { kind: 'uart', baud: baudOf(setting) }; }
        }
        return out;
    };
    const readConfig = (): PortConfig => {
        const raw = ctx.globalState.get<PortConfig>(configKey());
        return {
            motors: (raw && typeof raw.motors === 'object' && raw.motors) || {},
            servos: (raw && typeof raw.servos === 'object' && raw.servos) || {},
            serial: readSerial(raw?.serial),
        };
    };
    const writeConfig = async (cfg: PortConfig): Promise<void> => {
        await ctx.globalState.update(configKey(), cfg);
    };

    /* which I2C port is being read live, remembered per board so it comes back with the console */
    const watchKey = (): string => `evn.deviceWatch.${boardKey()}`;
    const readWatches = (): Record<string, WatchSpec> => {
        const raw = ctx.globalState.get<Record<string, WatchSpec>>(watchKey());
        if (!raw || typeof raw !== 'object') { return {}; }
        const out: Record<string, WatchSpec> = {};
        for (const [port, w] of Object.entries(raw)) {
            if (w && typeof w.kind === 'string' && typeof w.method === 'string') { out[port] = w; }
        }
        return out;
    };
    const writeWatches = async (w: Record<string, WatchSpec>): Promise<void> => {
        await ctx.globalState.update(watchKey(), w);
    };

    /* the last speed / angle / colour a port was driven with, so the boxes come up filled in */
    const lastKey = (what: string): string => `evn.lastValue.${boardKey()}.${what}`;
    const lastValue = (what: string, fallback: string): string =>
        ctx.globalState.get<string>(lastKey(what)) ?? fallback;
    const rememberValue = async (what: string, value: string): Promise<void> => {
        await ctx.globalState.update(lastKey(what), value);
    };

    const provider = new BoardProvider(ctx, readConfig, readWatches);
    const treeView = vscode.window.createTreeView('evn.board', { treeDataProvider: provider, showCollapseAll: false });
    ctx.subscriptions.push(treeView);

    const info = (msg: string) => vscode.window.showInformationMessage(`EVN: ${msg}`);

    // While the console is live the rows are refreshed four times a second, so "read N ago" would be
    // a lie: what is worth knowing then is how long the link has been up. "read N ago" is kept for
    // the other case, where the one mpremote read really is what the view shows.
    const updateMessage = () => {
        if (provider.busy) { treeView.message = 'reading the board...'; return; }
        if (consoleLive()) {
            const since = consoleSince();
            const how = consoleTransport() === 'bluetooth' ? 'live over Bluetooth' : 'live';
            treeView.message = since ? `${how} · connected ${agoText(since)}` : how;
            return;
        }
        const r = provider.reading;
        if (!r) { treeView.message = undefined; return; }
        if (!boardState().present) { treeView.message = `last read ${agoText(r.at)}, board unplugged`; return; }
        treeView.message = `read ${agoText(r.at)}`;
    };
    /** Set by the ticking block below; keeps "read 3 minutes ago" moving after the first read. */
    let ensureTicking = () => { /* replaced further down */ };
    const redraw = () => { updateMessage(); provider.refresh(); ensureTicking(); };

    /* ---- reading the board ------------------------------------------------------------- */

    /** The live console holds the port, so mpremote must not open it. */
    const consoleHoldsPort = (): boolean => {
        const s = consoleState();
        return s === 'live' || s === 'busy' || s === 'connecting';
    };

    /** firmware, MicroPython and the file list over the live console. */
    const readViaConsole = async (quiet: boolean): Promise<boolean> => {
        try {
            const r = await consoleRequest({ cmd: 'info' }, 10000);
            provider.reading = {
                at: new Date(),
                version: normalizeVersion(typeof r?.v === 'string' ? r.v : undefined),
                micropython: typeof r?.mp === 'string' ? r.mp : undefined,
                files: Array.isArray(r?.files)
                    ? r.files.map((f: any) => ({ name: String(f?.[0]), size: Number(f?.[1]) }))
                    : undefined,
                fs: Array.isArray(r?.fs) ? r.fs.map((n: any) => Number(n)) : undefined,
            };
            log(`board info over the console: firmware ${provider.reading.version ?? '?'}, ${provider.reading.files?.length ?? 0} files`);
            return true;
        } catch (e: any) {
            log(`ERROR reading the board over the console: ${e?.stack ?? e}`);
            if (!quiet) { vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`); }
            return false;
        }
    };

    /** Ask the board once over mpremote. Returns false when nothing was read. */
    const readViaMpremote = async (quiet: boolean): Promise<boolean> => {
        if (portBusy()) {
            if (!quiet) { info('the program terminal is using the port: close it or stop the program first.'); }
            return false;
        }
        if (consoleHoldsPort()) {
            if (!quiet) {
                info(consoleState() === 'busy'
                    ? 'the board is running its own program (main.py); stop it first, then read the board.'
                    : 'the live console is holding the port; pause it first, then read the board.');
            }
            return false;
        }
        const st = boardState();
        if (!st.hasMpremote) {
            if (!quiet) { info('mpremote was not found. Install it from the Board section first.'); }
            return false;
        }
        if (!st.port || !st.present) {
            await refreshBoardState();
            const again = boardState();
            if (!again.port || !again.present) {
                if (!quiet) { info('no board on USB. Plug it in and switch it on, then read again.'); }
                return false;
            }
        }
        const port = boardState().port as string;
        const py = await findPython();
        if (!py) {
            if (!quiet) { info('mpremote was not found. Install it from the Board section first.'); }
            return false;
        }
        try {
            const r = await mpremote(py, ['connect', port, 'exec', READ_SCRIPT], READ_TIMEOUT_MS);
            const line = (r.stdout || '').split(/\r?\n/).map((s) => s.trim()).filter((s) => s.startsWith('{')).pop();
            if (r.code !== 0 || !line) {
                const why = r.timedOut ? 'the board did not answer in time' : (r.stderr || r.stdout || '').trim() || 'no answer';
                throw new Error(`could not read the board on ${port}: ${why}`);
            }
            const d = JSON.parse(line) as { v?: string; mp?: string; mv?: number; cells?: number[]; files?: [string, number][] };
            provider.reading = {
                at: new Date(),
                version: normalizeVersion(d.v),
                micropython: typeof d.mp === 'string' ? d.mp : undefined,
                files: Array.isArray(d.files) ? d.files.map((f) => ({ name: String(f[0]), size: Number(f[1]) })) : undefined,
            };
            if (typeof d.mv === 'number') {
                provider.battery = {
                    at: new Date(),
                    millivolts: d.mv,
                    cells: Array.isArray(d.cells) ? d.cells.filter((c) => typeof c === 'number') : undefined,
                };
            }
            log(`board read on ${port}: firmware ${provider.reading.version ?? '?'}, ${provider.battery?.millivolts ?? '?'} mV, ${provider.reading.files?.length ?? 0} files`);
            return true;
        } catch (e: any) {
            log(`ERROR reading the board: ${e?.stack ?? e}`);
            if (!quiet) { vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`); }
            return false;
        }
    };

    const readBoard = async (quiet: boolean): Promise<boolean> => {
        if (provider.busy) { return false; }
        provider.busy = true;
        redraw();
        try {
            if (consoleLive()) {
                const ok = await readViaConsole(quiet);
                if (ok) { void consoleRequest({ cmd: 'scan' }, 15000).catch(() => undefined); }
                return ok;
            }
            return await readViaMpremote(quiet);
        } finally {
            provider.busy = false;
            redraw();
        }
    };

    /** One warning per (board, bundled) pair, so the same mismatch is not asked twice. */
    const offerFlash = async (): Promise<void> => {
        const board = provider.reading?.version;
        const bundled = bundledVersion(ctx).version;
        if (!board || !bundled || compareVersions(board, bundled) >= 0) { return; }
        const key = `${board}->${bundled}`;
        if (ctx.globalState.get<string>(PROMPT_KEY) === key) { return; }
        await ctx.globalState.update(PROMPT_KEY, key);
        const choice = await vscode.window.showWarningMessage(
            `EVN: the board runs firmware ${board}; the extension bundles ${bundled}. Flash the newer one?`,
            'Flash', 'Not now');
        if (choice === 'Flash') { await deps.flashFirmware(); }
    };

    /* ---- commands ---------------------------------------------------------------------- */

    const reg = (id: string, fn: (...a: any[]) => any) =>
        ctx.subscriptions.push(vscode.commands.registerCommand(id, async (...a: any[]) => {
            try { await fn(...a); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));

    reg('evn.refreshBoard', async () => {
        if (await readBoard(false)) { await offerFlash(); }
    });

    reg('evn.deleteBoardFile', async (item?: BoardItem) => {
        const name = item?.fileName;
        if (!name) { info('right-click a file under "Files on the board" to delete it.'); return; }
        const isMain = name.toLowerCase() === 'main.py';
        const live = consoleLive();
        if (!live) {
            if (portBusy()) { info('the program terminal is using the port: close it or stop the program first.'); return; }
            if (consoleHoldsPort()) { info('the live console is holding the port; pause it first, or stop the board\'s program.'); return; }
            const st = boardState();
            if (!st.hasMpremote || !st.port || !st.present) { info('no board on USB. Plug it in and switch it on first.'); return; }
        }
        const ok = await vscode.window.showWarningMessage(
            `Delete ${name} from the board?`,
            { modal: true, detail: `It cannot be undone${isMain ? ', nothing will run at power-on' : ''}.` },
            'Delete');
        if (ok !== 'Delete') { return; }
        if (live) {
            const r = await consoleRequest({ cmd: 'rm', name }, 10000);
            if (!r?.ok) { throw new Error(`could not delete ${name}: ${r?.err || 'the board refused'}`); }
        } else {
            const py = await findPython();
            if (!py) { info('mpremote was not found. Install it from the Board section first.'); return; }
            const port = boardState().port as string;
            const r = await mpremote(py, ['connect', port, 'rm', `:${name}`], READ_TIMEOUT_MS);
            if (r.code !== 0) {
                throw new Error(`could not delete ${name}: ${(r.stderr || r.stdout).trim() || 'no answer from the board'}`);
            }
        }
        log(`deleted ${name} from the board`);
        vscode.window.showInformationMessage(`EVN: ${name} deleted from the board.${isMain ? ' Nothing runs at power-on now.' : ''}`);
        await readBoard(true);
    });

    /** Send every configured servo and serial port to the board, so s1..s4 / l1..l4 and bt1 / bt2 /
     *  u1 / u2 exist there. A serial header without its module answers with an error naming the
     *  port; that error is kept so the row can say "not answering: ..." instead of going quiet.
     *  Opening the Bluetooth module takes up to 3 s per port, hence the longer timeout. */
    const sendConfig = async (quiet = true): Promise<void> => {
        if (!consoleLive()) { return; }
        const cfg = readConfig();
        const servos: Record<string, string> = {};
        for (const [port, profile] of Object.entries(cfg.servos)) {
            if (profile) { servos[port] = profile; }
        }
        // a plain 'bluetooth' string keeps an older helper happy; a UART carries its baud
        const serial: Record<string, string | { kind: string; baud: number }> = {};
        for (const [port, setting] of Object.entries(cfg.serial)) {
            if (setting?.kind === 'bluetooth') { serial[port] = 'bluetooth'; }
            if (setting?.kind === 'uart') { serial[port] = { kind: 'uart', baud: baudOf(setting) }; }
        }
        try {
            const r = await consoleRequest({ cmd: 'configure', servos, serial }, 20000);
            provider.serialErrors.clear();
            if (!r?.ok) {
                const err = String(r?.err ?? '');
                for (const part of err.split(';')) {
                    const m = part.match(/serial port\s+(\d+)\s*:\s*(.+)$/);
                    if (m) { provider.serialErrors.set(Number(m[1]), m[2].trim()); }
                }
                if (!quiet) {
                    vscode.window.showWarningMessage(`EVN: the board could not set every port up: ${err || 'no reason given'}`);
                }
            }
        } catch (e: any) {
            log(`console: configure failed (${e?.message ?? e})`);
            if (!quiet) { vscode.window.showWarningMessage(`EVN: ${e?.message ?? e}`); }
        }
        // the `serial` event that follows the configure is handled before this promise resolves, so
        // the rows are drawn again here: a header that failed to open is only known from the answer
        provider.refreshSerial();
    };

    /** Put the remembered live reads back on the board (after a configure, on every connect). */
    const sendWatches = async (): Promise<void> => {
        if (!consoleLive()) { return; }
        for (const [port, w] of Object.entries(readWatches())) {
            try {
                await consoleRequest({ cmd: 'watch', port: Number(port), kind: w.kind, method: w.method }, 10000);
            } catch (e: any) {
                log(`console: could not watch ${w.kind}.${w.method}() on port ${port} (${e?.message ?? e})`);
            }
        }
    };

    reg('evn.configurePort', async (item?: BoardItem) => {
        if (!item || (item.kind !== 'motor' && item.kind !== 'servo' && item.kind !== 'serial') || !item.portNumber) {
            info('click the gear next to a motor port, a servo port or a serial port to say what is connected.');
            return;
        }
        const port = item.portNumber;
        const cfg = readConfig();
        if (item.kind === 'serial') {
            const current = cfg.serial[String(port)];
            const pick = await vscode.window.showQuickPick(
                SERIAL_KINDS.map((s) => ({
                    label: s.label,
                    description: s.id === (current?.kind ?? '') ? 'current' : undefined,
                    detail: s.detail,
                    id: s.id,
                })),
                { title: `Serial ${port}: what is on this header?`, placeHolder: 'The live console creates the matching object on the board.' });
            if (!pick) { return; }
            if (pick.id === 'uart') {
                const baud = await askBaud(port, baudOf(current));
                if (baud === undefined) { return; }
                cfg.serial[String(port)] = { kind: 'uart', baud };
            } else if (pick.id === 'bluetooth') {
                cfg.serial[String(port)] = { kind: 'bluetooth' };
            } else {
                delete cfg.serial[String(port)];
            }
            await writeConfig(cfg);
            provider.serialErrors.delete(port);
            redraw();
            await sendConfig(false);
            return;
        }
        if (item.kind === 'motor') {
            const current = cfg.motors[String(port)] ?? '';
            const pick = await vscode.window.showQuickPick(
                MOTOR_MODELS.map((m) => ({
                    label: m.label,
                    description: m.id === current ? 'current' : undefined,
                    detail: m.detail,
                    id: m.id,
                })),
                { title: `Motor port ${port}: what is connected?`, placeHolder: 'This is a note for you; the firmware decides the motor settings.' });
            if (!pick) { return; }
            if (pick.id) { cfg.motors[String(port)] = pick.id; } else { delete cfg.motors[String(port)]; }
            await writeConfig(cfg);
            redraw();
            return;
        }
        const current = cfg.servos[String(port)] ?? '';
        const pick = await vscode.window.showQuickPick(
            SERVO_PROFILES.map((s) => ({
                label: s.label,
                description: s.id === current ? 'current' : undefined,
                detail: s.detail,
                id: s.id,
            })),
            { title: `Servo port ${port}: what is connected?`, placeHolder: 'The live console creates the matching object on the board.' });
        if (!pick) { return; }
        if (pick.id) { cfg.servos[String(port)] = pick.id; } else { delete cfg.servos[String(port)]; }
        await writeConfig(cfg);
        redraw();
        await sendConfig(false);
    });

    /* ---- driving the board from the rows ----------------------------------------------- */

    /** Nothing here ever throws at the user when the console is simply not there: it says so. */
    const requireLive = (what: string): boolean => {
        if (consoleLive()) { return true; }
        const s = consoleState();
        const why = s === 'busy' ? "the board is running its own program (main.py); stop it first"
            : s === 'connecting' ? 'the live console is still connecting, try again in a moment'
                : s === 'gone' ? 'the board is not on USB'
                    : (consoleDetail() || 'the live console is not connected');
        info(`${what} needs the live console: ${why}.`);
        return false;
    };

    /** One `call` command; the board's error text comes back as the message the user sees. */
    const callBoard = async (cmd: object, timeoutMs = 15000): Promise<any> => {
        const r = await consoleRequest(cmd, timeoutMs);
        if (!r?.ok) { throw new Error(String(r?.err || 'the board refused the call')); }
        return r.value;
    };

    /** An input box that only takes a number, prefilled with what was used last time. */
    const askNumber = async (title: string, prompt: string, value: string): Promise<number | undefined> => {
        const typed = await vscode.window.showInputBox({
            title, prompt, value, ignoreFocusOut: true,
            valueSelection: [0, value.length],
            validateInput: (t) => {
                const s = t.trim();
                if (!s) { return 'type a number'; }
                return isFinite(Number(s)) ? undefined : 'type a number';
            },
        });
        if (typed === undefined || !typed.trim()) { return undefined; }
        return Number(typed.trim());
    };

    /** One value of a device setter. 'skip' means "leave that keyword out". */
    const askField = async (
        f: Field, title: string, optional: boolean, prefill: string,
    ): Promise<{ value: string } | 'skip' | undefined> => {
        if (f.choices?.length) {
            const items: (vscode.QuickPickItem & { value?: string; skip?: boolean })[] = f.choices.map((c) => ({
                label: c,
                description: c === prefill ? 'last time' : undefined,
                value: c,
            }));
            if (optional) { items.push({ label: 'keep it as it is', skip: true }); }
            const pick = await vscode.window.showQuickPick(items, { title, placeHolder: f.prompt, ignoreFocusOut: true });
            if (!pick) { return undefined; }
            if (pick.skip) { return 'skip'; }
            return { value: String(pick.value) };
        }
        const typed = await vscode.window.showInputBox({
            title,
            prompt: optional ? `${f.prompt} - leave it empty to keep it as it is` : f.prompt,
            value: prefill,
            ignoreFocusOut: true,
            validateInput: (t) => {
                const s = t.trim();
                if (!s) { return optional ? undefined : 'type a value'; }
                if (f.kind === 'number' && !isFinite(Number(s))) { return 'type a number'; }
                if (f.kind === 'list' && s.split(/[\s,]+/).filter(Boolean).some((x) => !isFinite(Number(x)))) {
                    return 'type the numbers separated by spaces';
                }
                return undefined;
            },
        });
        if (typed === undefined) { return undefined; }
        if (!typed.trim()) { return optional ? 'skip' : undefined; }
        return { value: typed.trim() };
    };

    /** A number stays a number, a list becomes a list of numbers, everything else is text. */
    const parseField = (f: Field, raw: string): any => {
        switch (f.kind) {
            case 'number': return Number(raw);
            case 'bool': return raw === 'on' || raw === 'true' || raw === 'yes';
            case 'list': return raw.split(/[\s,]+/).filter(Boolean).map((x) => Number(x));
            default: return raw;
        }
    };

    /* ---- motors ------------------------------------------------------------------------ */

    const motorPortOf = (item?: BoardItem): number | undefined => {
        if (item?.kind === 'motor' && item.portNumber) { return item.portNumber; }
        info('use the buttons next to a motor port that has a motor set on it (the gear sets one).');
        return undefined;
    };

    reg('evn.motor.run', async (item?: BoardItem) => {
        const port = motorPortOf(item);
        if (!port) { return; }
        if (!requireLive('running a motor')) { return; }
        const key = `motor.${port}.speed`;
        const speed = await askNumber(`Motor port ${port}: run`, 'Speed in degrees per second (negative = backwards)', lastValue(key, '200'));
        if (speed === undefined) { return; }
        await rememberValue(key, String(speed));
        await callBoard({ cmd: 'call', obj: `m${port}`, method: 'run', args: [speed] });
    });

    reg('evn.motor.runTarget', async (item?: BoardItem) => {
        const port = motorPortOf(item);
        if (!port) { return; }
        if (!requireLive('running a motor to an angle')) { return; }
        const speedKey = `motor.${port}.speed`;
        const angleKey = `motor.${port}.target`;
        const speed = await askNumber(`Motor port ${port}: run to an angle (1 of 2)`, 'Speed in degrees per second', lastValue(speedKey, '200'));
        if (speed === undefined) { return; }
        const angle = await askNumber(`Motor port ${port}: run to an angle (2 of 2)`, 'Target angle in degrees', lastValue(angleKey, '90'));
        if (angle === undefined) { return; }
        await rememberValue(speedKey, String(speed));
        await rememberValue(angleKey, String(angle));
        // wait=False: the board answers at once, so the agent keeps sending telemetry and the row
        // shows the angle moving instead of the view freezing until the move is over.
        await callBoard({ cmd: 'call', obj: `m${port}`, method: 'run_target', args: [speed, angle], kwargs: { wait: false } });
    });

    reg('evn.motor.runTime', async (item?: BoardItem) => {
        const port = motorPortOf(item);
        if (!port) { return; }
        if (!requireLive('running a motor for a time')) { return; }
        // the speed is the one key all three run buttons share, so a speed typed for "run" is
        // still the prefill here; the time is this button's own
        const speedKey = `motor.${port}.speed`;
        const timeKey = `motor.${port}.time`;
        const speed = await askNumber(`Motor port ${port}: run for a time (1 of 2)`, 'Speed in degrees per second (negative = backwards)', lastValue(speedKey, '200'));
        if (speed === undefined) { return; }
        const ms = await askNumber(`Motor port ${port}: run for a time (2 of 2)`, 'How long to run, in milliseconds', lastValue(timeKey, '1000'));
        if (ms === undefined) { return; }
        await rememberValue(speedKey, String(speed));
        await rememberValue(timeKey, String(ms));
        // wait=False, as for run to an angle: the board answers at once, so the telemetry keeps
        // coming and the row counts the angle up while the motor runs out its time.
        await callBoard({ cmd: 'call', obj: `m${port}`, method: 'run_time', args: [speed, ms], kwargs: { wait: false } });
    });

    reg('evn.motor.stop', async (item?: BoardItem) => {
        const port = motorPortOf(item);
        if (!port) { return; }
        if (!requireLive('stopping a motor')) { return; }
        await callBoard({ cmd: 'call', obj: `m${port}`, method: 'stop' });
    });

    /* ---- servo ports ------------------------------------------------------------------- */

    const servoPortOf = (item?: BoardItem): number | undefined => {
        if (item?.kind === 'servo' && item.portNumber) { return item.portNumber; }
        info('use the buttons next to a servo port that has something set on it (the gear sets it).');
        return undefined;
    };

    reg('evn.servo.drive', async (item?: BoardItem) => {
        const port = servoPortOf(item);
        if (!port) { return; }
        const profile = readConfig().servos[String(port)] ?? '';
        if (!profile) { info(`nothing is set for servo port ${port}: click the gear first.`); return; }
        if (!requireLive('driving a servo port')) { return; }
        if (profile === 'rgbled') {
            const key = `led.${port}.color`;
            const current = lastValue(key, 'RED');
            const items = [
                ...LED_COLORS.map((c) => ({
                    label: c,
                    id: c,
                    description: c === current ? 'last time' : undefined,
                    detail: `l${port}.on(evn.Color.${c})`,
                })),
                { label: 'off', id: '', description: undefined as string | undefined, detail: `l${port}.off()` },
            ];
            const pick = await vscode.window.showQuickPick(items, {
                title: `RGB LED strip on servo port ${port}`,
                placeHolder: 'The whole strip takes this colour.',
            });
            if (!pick) { return; }
            if (pick.id) { await rememberValue(key, pick.id); }
            // an evn.Color is an object, not JSON, so this one goes through exec and not call
            const code = pick.id ? `l${port}.on(evn.Color.${pick.id})` : `l${port}.off()`;
            const r = await consoleRequest({ cmd: 'exec', code }, 15000);
            if (!r?.ok) { throw new Error(String(r?.err || 'the board refused').split(/\r?\n/).filter(Boolean).pop() ?? 'the board refused'); }
            return;
        }
        if (profile === 'geekservo_cr') {
            const key = `servo.${port}.duty`;
            const pct = await askNumber(`Servo port ${port}: continuous servo`, 'Duty in percent, -100..100 (0 stops)', lastValue(key, '50'));
            if (pct === undefined) { return; }
            await rememberValue(key, String(pct));
            await callBoard({ cmd: 'call', obj: `s${port}`, method: 'duty', args: [pct] });
            return;
        }
        const max = profile === 'geekservo_270' ? 270 : 180;
        const key = `servo.${port}.angle`;
        const deg = await askNumber(`Servo port ${port}: ${servoLabel(profile)}`, `Angle in degrees (0..${max})`, lastValue(key, String(Math.round(max / 2))));
        if (deg === undefined) { return; }
        await rememberValue(key, String(deg));
        await callBoard({ cmd: 'call', obj: `s${port}`, method: 'angle', args: [deg] });
    });

    reg('evn.servo.stop', async (item?: BoardItem) => {
        const port = servoPortOf(item);
        if (!port) { return; }
        const profile = readConfig().servos[String(port)] ?? '';
        if (!profile) { info(`nothing is set for servo port ${port}: click the gear first.`); return; }
        if (!requireLive('stopping a servo port')) { return; }
        if (profile === 'rgbled') { await callBoard({ cmd: 'call', obj: `l${port}`, method: 'off' }); }
        else { await callBoard({ cmd: 'call', obj: `s${port}`, method: 'stop' }); }
    });

    /* ---- I2C devices ------------------------------------------------------------------- */

    /** The port and the evn class of an identified device row, or nothing (with a word why). */
    const deviceOf = (item?: BoardItem): { port: number; kind: string } | undefined => {
        if (item?.kind === 'device' && item.portNumber && item.deviceKind) {
            return { port: item.portNumber, kind: item.deviceKind };
        }
        info('use the buttons next to an I2C device the board recognised; an unknown device has nothing to offer.');
        return undefined;
    };

    reg('evn.device.set', async (item?: BoardItem) => {
        const d = deviceOf(item);
        if (!d) { return; }
        if (!requireLive('changing a device setting')) { return; }
        const setters = DEVICE_SETTERS[d.kind];
        if (!setters?.length) {
            info(`there is nothing to set on the ${d.kind} from here; use the command line (it is d${d.port} there).`);
            return;
        }
        const pick = await vscode.window.showQuickPick(
            setters.map((s) => ({ label: s.label, detail: s.detail, setter: s })),
            { title: `${d.kind} on port ${d.port}: what do you want to set?`, placeHolder: 'The board does it right away.' });
        if (!pick) { return; }
        const s = pick.setter;
        const title = `${d.kind} on port ${d.port}: ${s.label}`;
        const args: any[] = [];
        for (const f of s.args ?? []) {
            const key = `device.${d.port}.${s.method}.${f.name}`;
            const a = await askField(f, title, false, lastValue(key, ''));
            if (a === undefined || a === 'skip') { return; }
            await rememberValue(key, a.value);
            args.push(parseField(f, a.value));
        }
        const kwargs: Record<string, any> = { ...(s.fixed ?? {}) };
        let asked = 0;
        for (const f of s.kwargs ?? []) {
            const key = `device.${d.port}.${s.method}.${f.name}`;
            const a = await askField(f, title, true, lastValue(key, ''));
            if (a === undefined) { return; }
            if (a === 'skip') { continue; }
            await rememberValue(key, a.value);
            kwargs[f.name] = parseField(f, a.value);
            asked++;
        }
        if (!args.length && !asked) { info('nothing was filled in, so nothing was changed.'); return; }
        const cmd: any = { cmd: 'call', port: d.port, kind: d.kind, method: s.method, args };
        if (Object.keys(kwargs).length) { cmd.kwargs = kwargs; }
        const r = await consoleRequest(cmd, 20000);
        if (!r?.ok) {
            vscode.window.showWarningMessage(`EVN: ${d.kind}.${s.method}() on port ${d.port}: ${r?.err ?? 'the board refused'}`);
            return;
        }
        info(r.value === null || r.value === undefined
            ? `${d.kind}.${s.method}() on port ${d.port}: done.`
            : `${d.kind}.${s.method}() on port ${d.port}: ${valueText(r.value)}`);
    });

    reg('evn.device.watch', async (item?: BoardItem) => {
        const d = deviceOf(item);
        if (!d) { return; }
        if (!requireLive('reading a device live')) { return; }
        const readers = DEVICE_READERS[d.kind];
        if (!readers?.length) {
            info(`the ${d.kind} has nothing to read: it shows things, it does not measure them.`);
            return;
        }
        const current = readWatches()[String(d.port)]?.method;
        const pick = await vscode.window.showQuickPick(
            readers.map((m) => ({
                label: m,
                description: m === current ? 'shown now' : undefined,
                detail: READER_DETAIL[m],
            })),
            {
                title: `${d.kind} on port ${d.port}: what should the row show?`,
                placeHolder: 'The board reads it four times a second, with the rest of the telemetry.',
            });
        if (!pick) { return; }
        const r = await consoleRequest({ cmd: 'watch', port: d.port, kind: d.kind, method: pick.label }, 10000);
        if (!r?.ok) {
            vscode.window.showWarningMessage(`EVN: could not read ${d.kind}.${pick.label}() on port ${d.port}: ${r?.err ?? 'the board refused'}`);
            return;
        }
        const w = readWatches();
        w[String(d.port)] = { kind: d.kind, method: pick.label };
        await writeWatches(w);
        redraw();
    });

    reg('evn.device.unwatch', async (item?: BoardItem) => {
        const d = deviceOf(item);
        if (!d) { return; }
        if (!requireLive('stopping a live reading')) { return; }
        const r = await consoleRequest({ cmd: 'watch', port: d.port }, 10000);
        if (!r?.ok) {
            vscode.window.showWarningMessage(`EVN: could not stop reading port ${d.port}: ${r?.err ?? 'the board refused'}`);
            return;
        }
        const w = readWatches();
        delete w[String(d.port)];
        await writeWatches(w);
        redraw();
    });

    /* ---- the Bluetooth module ---------------------------------------------------------- */

    /** boot.py as it is now, or an empty string when there is none. */
    const BOOT_READ = [
        'import os',
        "print(open('boot.py').read() if 'boot.py' in os.listdir('/') else '')",
    ].join('\n');

    const serialPortOf = (item?: BoardItem): number | undefined => {
        if (item?.kind === 'serial' && item.portNumber) { return item.portNumber; }
        info('use the buttons next to a serial port that has an EVN Bluetooth module set on it.');
        return undefined;
    };

    /** Put `import evn` / `evn.Bluetooth(n).repl(True)` into boot.py, once. */
    const makeReplPermanent = async (port: number): Promise<void> => {
        const read = await consoleRequest({ cmd: 'exec', code: BOOT_READ }, 15000);
        if (!read?.ok) { throw new Error(String(read?.err || 'could not read boot.py on the board')); }
        const raw: string = typeof read.out === 'string' ? read.out : '';
        const existing = raw.replace(/\r\n/g, '\n').replace(/\n$/, '');
        const lines: string[] = existing.split('\n');
        const hasImport = lines.some((l) => /^\s*import\s+evn\s*(?:$|,|\s+as\s)/.test(l));
        const hasRepl = lines.some((l) => l.includes(`Bluetooth(${port})`) && /repl\s*\(\s*True\s*\)/.test(l));
        if (hasImport && hasRepl) {
            info(`boot.py on the board already puts the REPL on the module on Serial ${port}; nothing was changed.`);
            return;
        }
        const add: string[] = [];
        if (!hasImport) { add.push('import evn'); }
        if (!hasRepl) { add.push(`evn.Bluetooth(${port}).repl(True)`); }
        const body = existing.replace(/\s+$/, '');
        const next = `${body ? `${body}\n` : ''}${add.join('\n')}\n`;
        // JSON escaping is a subset of Python's, so the file goes over as one literal
        const code = [
            "_f = open('boot.py', 'w')",
            `_f.write(${JSON.stringify(next)})`,
            '_f.close()',
        ].join('\n');
        const write = await consoleRequest({ cmd: 'exec', code }, 15000);
        if (!write?.ok) { throw new Error(String(write?.err || 'could not write boot.py on the board')); }
        vscode.window.showInformationMessage(
            `EVN: ${add.join(' and ')} ${add.length > 1 ? 'were' : 'was'} added to boot.py on the board, so the REPL is on the Bluetooth module every time the board is switched on.`);
        await readBoard(true);
        redraw();
    };

    reg('evn.bluetooth.repl', async (item?: BoardItem) => {
        const port = serialPortOf(item);
        if (!port) { return; }
        if (readConfig().serial[String(port)]?.kind !== 'bluetooth') {
            info(`Serial ${port} is not set to an EVN Bluetooth module: click the gear first.`);
            return;
        }
        if (!requireLive('putting the REPL on the Bluetooth module')) { return; }
        await callBoard({ cmd: 'call', obj: `bt${port}`, method: 'repl', args: [true] }, 20000);
        provider.refreshSerial();
        const choice = await vscode.window.showInformationMessage(
            `EVN: the board's REPL is on the Bluetooth module on Serial ${port} now (only one module carries it at a time). Connect to its COM port and you are at the board's prompt. A soft reset keeps it; switching the board off does not.`,
            'Make it permanent', 'Not now');
        if (choice !== 'Make it permanent') { return; }
        await makeReplPermanent(port);
    });

    reg('evn.bluetooth.pair', async () => {
        await vscode.env.openExternal(vscode.Uri.parse('ms-settings:bluetooth'));
        vscode.window.showInformationMessage(
            'EVN: in the Windows Bluetooth settings, add the device shown as "HC-05" or "EVN Bluetooth" - the PIN is 1234. '
            + 'Windows then lists an outgoing "Standard Serial over Bluetooth link (COMxx)" port; that is the one to pick in the EVN port picker, where it has a broadcast icon.');
    });

    /* ---- following the board, the console and the clock -------------------------------- */

    // the board state carries the transport and the wireless link as well as the port, so this
    // redraw is what puts "connected over Bluetooth" and "link COMxx" on the rows
    ctx.subscriptions.push(onDidChangeBoardState(() => { redraw(); }));
    ctx.subscriptions.push(onDidChangeTerminal(() => { redraw(); }));

    // the console coming up: read the board once and hand the servo configuration over
    let wasLive = false;
    ctx.subscriptions.push(onDidChangeConsole(() => {
        const live = consoleLive();
        if (live && !wasLive) {
            void (async () => {
                await sendConfig(true);
                await sendWatches();
                if (await readBoard(true)) { await offerFlash(); }
                redraw();
            })();
        }
        if (!live && wasLive) { provider.serialErrors.clear(); }
        wasLive = live;
        redraw();
    }));

    // telemetry: at most four row updates a second, and nothing at all while the view is hidden
    let liveTimer: NodeJS.Timeout | undefined;
    let pendingLive = false;
    const scheduleLiveRefresh = () => {
        if (!treeView.visible) { pendingLive = false; return; }
        pendingLive = true;
        if (liveTimer) { return; }
        liveTimer = setTimeout(() => {
            liveTimer = undefined;
            if (!pendingLive) { return; }
            pendingLive = false;
            if (!treeView.visible) { return; }
            provider.refreshLive();
        }, LIVE_REFRESH_MS);
    };
    ctx.subscriptions.push(onDidReceiveTelemetry((t: Telemetry) => {
        if (typeof t.batt === 'number') {
            provider.battery = { at: t.at, millivolts: t.batt, cells: t.cells };
        }
        scheduleLiveRefresh();
    }));
    // the 5 s device sweep: redraw the I2C folder, but never while the view is off screen
    ctx.subscriptions.push(onDidReceiveDevices((_d: I2cDevice[]) => { if (treeView.visible) { provider.refresh(); } }));
    // the serial status rides along with the sweep and follows every configure
    ctx.subscriptions.push(onDidReceiveSerial((ports: SerialPortStatus[]) => {
        // a port that answered is not the one that failed to open
        for (const p of ports) { provider.serialErrors.delete(p.port); }
        if (treeView.visible) { provider.refreshSerial(); }
    }));

    // "connected 3 minutes ago" / "read 3 minutes ago" has to tick, but only while the view is on
    // screen and only while there is something to count: a live link or a reading (or both).
    let messageTimer: NodeJS.Timeout | undefined;
    const wantsTicking = () => treeView.visible && (consoleLive() || !!provider.reading);
    const stopTicking = () => { if (messageTimer) { clearInterval(messageTimer); messageTimer = undefined; } };
    const startTicking = () => {
        stopTicking();
        if (!wantsTicking()) { return; }
        messageTimer = setInterval(() => {
            if (!wantsTicking()) { stopTicking(); return; }
            updateMessage();
            // the rows carry "last read 3 minutes ago, board unplugged" too
            if (!boardState().present) { provider.refresh(); }
        }, MESSAGE_TICK_MS);
    };
    ctx.subscriptions.push(treeView.onDidChangeVisibility(() => {
        if (treeView.visible) { redraw(); startTicking(); } else { stopTicking(); }
    }));
    ctx.subscriptions.push({ dispose: () => { stopTicking(); if (liveTimer) { clearTimeout(liveTimer); } } });
    ensureTicking = () => { if (!messageTimer && wantsTicking()) { startTicking(); } };

    updateMessage();
    startTicking();
}
