/** The helper substitutes these five values in front of the agent source. */
export function agentSource(serial: string, transport: string, port: string, rate: number, teleMs: number): string {
    const s = (v: string) => "'" + v.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
    return `_SERIAL = ${s(serial)}\n_TRANSPORT = ${s(transport)}\n_PORT = ${s(port)}\n`
        + `_RATE = ${rate}\n_TELE_MS = ${teleMs}\n` + AGENT;
}
