/* The one seam between the shared extension code and the two places it runs.
 *
 * Everything that needs a machine - a Python with mpremote, a child process, a folder under
 * Documents, a removable drive, a serial port - goes through the Host below. `src/node-entry.ts`
 * installs the desktop implementation (`platform/node`), `src/web-entry.ts` the browser one
 * (`platform/web`), and esbuild builds one bundle for each; nothing else in `src/` imports a Node
 * builtin, so the browser bundle has no shims at all.
 *
 * The desktop implementation is the code that was in util.ts, flash.ts, projectsFolder.ts and
 * runStatus.ts before the split, moved rather than rewritten: what early users have today must
 * behave exactly as it did.
 */
import * as vscode from 'vscode';

export interface PyCmd {
    /** executable (e.g. "py", "python3", or a full path) */
    cmd: string;
    /** leading arguments (e.g. ["-3"] for the Windows launcher) */
    args: string[];
}

export interface RunResult {
    code: number | null;
    stdout: string;
    stderr: string;
    timedOut: boolean;
}

export interface BoardPort {
    device: string;      // COM7, /dev/ttyACM0 ...
    /** USB serial number (the RP2040 unique id), '' when the port has none (Bluetooth, legacy adapters) */
    serial: string;
    vidpid: string;      // "2e8a:000a"
    /** what the OS calls the port, e.g. "USB Serial Device (COM7)" or "Standard Serial over Bluetooth link (COM11)" */
    description: string;
    /** the OS hardware id pyserial reports ('' when the listing came from mpremote, which drops it) */
    hwid: string;
    /** the remote Bluetooth module's address out of a BTHENUM hwid, e.g. "98:D3:41:F7:18:02" */
    address?: string;
}

/** What scripts/evn_run.py records about the program in the terminal (see runStatus.ts). */
export interface RunState { phase: string; rc: number | null; file: string; port: string; t: number }

/**
 * The console helper as console.ts sees it: a line-oriented process.
 *
 * On the desktop it is `python scripts/evn_console.py PORT` (stdin/stdout); in the browser it is
 * `platform/web/serialHelper.ts`, the same protocol spoken over Web Serial. Both emit exactly the
 * events of docs/CONSOLE_PROTOCOL.md and take exactly its commands.
 */
export interface HelperProcess {
    /** one JSON command; the newline is added here */
    write(line: string): void;
    onLine(cb: (line: string) => void): void;
    onStderr(cb: (line: string) => void): void;
    /** fires once; `code` is 0 after a clean quit */
    onExit(cb: (code: number | null) => void): void;
    kill(): void;
    readonly exited: boolean;
}

export interface Host {
    /** true in the browser (vscode.dev, the self-hosted IDE); false in the desktop extension host */
    readonly web: boolean;
    /** what the platform is called in the diagnostics report */
    readonly label: string;
    /** "Show in the file explorer" and "Install mpremote" only exist where there is a machine */
    readonly hasFileExplorer: boolean;
    readonly hasPython: boolean;

    /** Called once from activate(), before anything else registers. */
    activate(ctx: vscode.ExtensionContext): Promise<void>;

    /* ---- the toolchain --------------------------------------------------------------- */

    /** The Python that has mpremote (desktop), or the marker command of the Web Serial transport. */
    findPython(): Promise<PyCmd | undefined>;
    pythonWithoutMpremote(): PyCmd | undefined;
    forgetPython(): void;
    /** Ports that could be a board; on the web only the ones the user has granted. */
    listPorts(py: PyCmd): Promise<BoardPort[]>;
    /**
     * One mpremote command line (the arguments after `mpremote`), or its Web Serial equivalent.
     * The browser host understands the shapes the extension actually uses:
     * `connect PORT exec CODE`, `connect PORT exec --no-follow CODE`, `connect PORT ls`,
     * `connect PORT rm :NAME`; anything else comes back as a clear failure rather than a silence.
     */
    mpremote(py: PyCmd, args: string[], timeoutMs?: number): Promise<RunResult>;
    /** The one terminal that may hold the port: run a program in it, with the REPL after when asked. */
    runProgram(ctx: vscode.ExtensionContext, py: PyCmd, port: string, file: vscode.Uri, repl: boolean): vscode.Terminal;
    /** The same terminal, opened straight on the REPL. */
    openRepl(ctx: vscode.ExtensionContext, py: PyCmd, port: string): vscode.Terminal;
    /** Copy a file onto the board as main.py, and reset the board when `run`. */
    uploadMain(ctx: vscode.ExtensionContext, py: PyCmd, port: string, file: vscode.Uri, run: boolean): Promise<void>;
    /** The live console's helper for this port. */
    startHelper(ctx: vscode.ExtensionContext, py: PyCmd, port: string, rate?: number): Promise<HelperProcess>;
    /** "EVN: Install mpremote" (desktop) / an explanation (web). */
    installMpremote(): Promise<void>;
    /** What the status bar says when findPython() came back empty: there is no one message. */
    noToolchainStatus(): { text: string; tooltip: string };
    /** The port picker, when the platform has one of its own (Web Serial); undefined = the usual list. */
    requestPort?(): Promise<BoardPort | undefined>;

    /* ---- firmware -------------------------------------------------------------------- */

    /** Root of the mounted RPI-RP2 drive, or undefined (always undefined in a browser). */
    findBootselDrive(): string | undefined;
    /** The whole "EVN: Flash firmware" command: a drive copy on the desktop, an explanation on the web. */
    flashFirmware(ctx: vscode.ExtensionContext, deps: FlashDeps): Promise<void>;

    /* ---- the projects folder ---------------------------------------------------------- */

    /** Documents/EVN Projects on the desktop, evn-projects:/ in the browser. */
    projectsFolder(): vscode.Uri;
    ensureProjectsFolder(ctx: vscode.ExtensionContext): Promise<vscode.Uri>;
    /** Typings, .vscode/settings.json and the project marker (desktop); a no-op where Pylance cannot run. */
    scaffoldPythonSupport(ctx: vscode.ExtensionContext, root: vscode.Uri): Promise<void>;
    /** A writable scratch location for a file that must not be saved (an example that is run). */
    scratchFile(name: string): vscode.Uri;

    /* ---- what the program in the terminal is doing -------------------------------------- */

    /** The argument scripts/evn_run.py is given for its state file (a path on the desktop). */
    runStateRef(): string;
    readRunState(): RunState | undefined;
    clearRunState(): void;
}

/** What the flash command needs from the shared code (it owns the port and the status bar). */
export interface FlashDeps {
    selectedPort(): string | undefined;
    refreshStatus(): Promise<void>;
    releasePort(): Promise<void>;
    boardLabel(): string;
}

let current: Host | undefined;

export function setHost(h: Host): void { current = h; }

export function host(): Host {
    if (!current) { throw new Error('the EVN platform host was not installed'); }
    return current;
}

/** True once the host is installed; used by code that may run before activate(). */
export function hostInstalled(): boolean { return current !== undefined; }
