/* MicroPython's raw REPL over a ByteStream.
 *
 * This is what mpremote does on the desktop, written out over the abstract stream so it runs in the
 * browser over Web Serial and, unchanged, under Node over scripts/serial_bridge.py (which is how it
 * is checked against a real board) or against the scripted mock board in the tests.
 *
 * The sequences are the ones docs/CONSOLE_PROTOCOL.md describes and scripts/evn_console.py uses:
 *   Ctrl-C Ctrl-C  interrupt whatever is running
 *   Ctrl-A         raw REPL ("raw REPL; CTRL-B to exit")
 *   Ctrl-D         soft reset from the raw REPL - main.py is skipped
 *   \x05A\x01      ask for raw-paste mode (flow controlled by the board), else 256-byte chunks
 *   Ctrl-D         end of the source; the board answers, runs, and frames the answer with 0x04
 *   Ctrl-B         back to the friendly REPL (what the next mpremote connect expects)
 */
import { Bytes, Wire, clean, concat, decode, delay, encode, indexOf } from './stream';

export const CHUNK = 256;              // raw-REPL upload chunk (the fallback when raw-paste is not answered)
export const CHUNK_PAUSE_MS = 10;
const RAW_BANNER = 'raw REPL; CTRL-B to exit';

export class ReplError extends Error { }

export interface ExecResult {
    ok: boolean;
    /** what the code printed */
    out: string;
    /** the traceback, empty when it ran */
    err: string;
}

export class RawRepl {
    constructor(private readonly wire: Wire) { }

    /** Idle or busy? Write \r\n and look at what comes back (never interrupts anything). */
    async probe(waitMs: number): Promise<'idle' | 'raw' | 'busy'> {
        this.wire.resetInput();
        await this.wire.write('\r\n');
        const end = Date.now() + waitMs;
        let data: Bytes = new Uint8Array(0);
        while (Date.now() < end) {
            await this.wire.pump(Math.min(50, Math.max(5, end - Date.now())));
            data = concat(data, this.wire.takeAll());
        }
        const text = decode(data);
        if (text.includes('>>> ')) { return 'idle'; }
        if (text.trim().endsWith('>')) { return 'raw'; }
        return 'busy';
    }

    /** True when the probe above found nothing at all (over Bluetooth that has three readings). */
    static silent(text: string): boolean { return !text.trim(); }

    /** Ctrl-C, Ctrl-A: the raw REPL prompt. */
    async enter(interrupt = true): Promise<void> {
        if (interrupt) {
            await this.wire.write('\r\x03');
            await delay(50);
            await this.wire.write('\r\x03');
            await delay(50);
        }
        this.wire.resetInput();
        await this.wire.write('\r\x01');
        if (await this.wire.readUntil(RAW_BANNER, 3.0) === undefined) {
            throw new ReplError('the board did not enter the raw REPL');
        }
    }

    /** Ctrl-D at the raw prompt: a soft reset that skips main.py, back at the raw prompt. */
    async softReset(): Promise<void> {
        await this.wire.write('\x04');
        const tail = await this.wire.readUntil('soft reboot', 3.0);
        // a board that reboots quickly (or a link that buffers) may send both in one read: what
        // followed "soft reboot" goes back into the buffer so the banner is not read past
        if (tail && tail.length) { this.wire.unread(tail); }
        if (await this.wire.readUntil(RAW_BANNER, 8.0) === undefined) {
            throw new ReplError('the board did not come back from the soft reset');
        }
        await delay(50);
        this.wire.resetInput();
    }

    /** Ctrl-B: hand the friendly REPL back (what mpremote and the board's own prompt expect). */
    async exitToFriendly(): Promise<void> {
        await this.wire.write('\r\x02');
        await delay(150);
        this.wire.resetInput();
    }

    /** Ctrl-C twice: interrupt a running program (motors coast on the KeyboardInterrupt). */
    async interrupt(): Promise<void> {
        await this.wire.write('\r\x03');
        await delay(100);
        await this.wire.write('\r\x03');
        await delay(100);
    }

    /**
     * Send a source blob at the raw-REPL prompt without waiting for it to finish.
     * Returns whatever the board had already sent afterwards (the console agent's first line may
     * be in there). Uses raw-paste when the board offers it, else 256-byte chunks.
     */
    async paste(blob: Bytes): Promise<Bytes> {
        const rest = await this.rawPaste(blob);
        if (rest !== undefined) { return rest; }
        for (let i = 0; i < blob.length; i += CHUNK) {
            await this.wire.write(blob.slice(i, i + CHUNK));
            await delay(CHUNK_PAUSE_MS);
        }
        await this.wire.write('\x04');
        const ok = await this.wire.readUntil('OK', 8.0);
        if (ok === undefined) { throw new ReplError('the board did not accept the program'); }
        return ok;
    }

    /**
     * The raw REPL's flow-controlled upload; undefined when the board does not offer it.
     *
     * The board hands out a window and asks for the next one with 0x01 as it consumes the source,
     * so nothing can overrun a buffer on the way - which is what a ~10 KB agent going through an
     * EVN Bluetooth module needs. MicroPython has had it since v1.14.
     */
    private async rawPaste(blob: Bytes): Promise<Bytes | undefined> {
        await this.wire.write('\x05A\x01');
        const head = await this.wire.readExact(2, 2.0);
        if (!(head.length === 2 && head[0] === 0x52 && head[1] === 0x01)) {
            // "R\x00" means "understood, not supported"; anything else is a board that took the
            // bytes for something else. Either way get a clean raw-REPL prompt back and fall back.
            await this.wire.write('\r\x03\r\x01');
            await this.wire.readUntil(RAW_BANNER, 3.0);
            return undefined;
        }
        const win = await this.wire.readExact(2, 2.0);
        if (win.length !== 2) { throw new ReplError('the board did not send the raw-paste window size'); }
        const window = win[0] | (win[1] << 8);
        let remain = window;
        let sent = 0;
        while (sent < blob.length) {
            while (remain === 0 || this.wire.inWaiting) {
                const answer = await this.wire.readExact(1, 8.0);
                if (answer.length === 1 && answer[0] === 0x01) {
                    remain += window;                    // a window was consumed: send the next one
                } else if (answer.length === 1 && answer[0] === 0x04) {
                    await this.wire.write('\x04');       // the board gave up (out of memory)
                    throw new ReplError('the board refused the program');
                } else {
                    throw new ReplError('the board stopped answering during the upload');
                }
            }
            const n = Math.min(remain, blob.length - sent);
            await this.wire.write(blob.slice(sent, sent + n));
            remain -= n;
            sent += n;
        }
        await this.wire.write('\x04');
        const rest = await this.wire.readUntil('\x04', 8.0);   // the board's "I have the whole source"
        if (rest === undefined) { throw new ReplError('the board did not accept the program'); }
        return rest;
    }

    /**
     * Run code at the raw-REPL prompt and wait for it.
     * `onOut` is called with the output as it arrives (that is what makes a program's prints show
     * up in the terminal line by line instead of at the end).
     */
    async exec(code: string, timeoutSeconds = 30, onOut?: (text: string) => void): Promise<ExecResult> {
        await this.paste(encode(code));
        return this.follow(timeoutSeconds, onOut);
    }

    /** Collect a running program's output: everything up to 0x04, then the traceback up to 0x04. */
    async follow(timeoutSeconds: number, onOut?: (text: string) => void, stop?: () => boolean): Promise<ExecResult> {
        const out = await this.readFramed(timeoutSeconds, onOut, stop);
        if (out === undefined) { throw new ReplError('the board did not finish within the time allowed'); }
        const err = await this.readFramed(10, undefined, stop);
        const errText = err === undefined ? '' : clean(err).replace(/\s+$/, '');
        return { ok: !errText, out: clean(out).replace(/\s+$/, ''), err: errText };
    }

    /** Read until the next 0x04, handing every chunk to `onOut` as it comes. */
    private async readFramed(timeoutSeconds: number, onOut?: (text: string) => void, stop?: () => boolean): Promise<Bytes | undefined> {
        const end = Date.now() + timeoutSeconds * 1000;
        let acc: Bytes = new Uint8Array(0);
        for (;;) {
            const i = indexOf(this.wire.peek(), new Uint8Array([0x04]));
            if (i >= 0) {
                const head = this.wire.peek().slice(0, i);
                this.wire.drop(i + 1);
                if (head.length && onOut) { onOut(decode(head)); }
                return concat(acc, head);
            }
            const buffered = this.wire.takeAll();
            if (buffered.length) {
                if (onOut) { onOut(decode(buffered)); }
                acc = concat(acc, buffered);
                continue;
            }
            if (stop?.()) { return acc; }
            if (Date.now() >= end) { return undefined; }
            await this.wire.pump(100);
        }
    }

    /** One expression, as text (`exec` with the traceback turned into an error). */
    async evaluate(code: string, timeoutSeconds = 15): Promise<string> {
        const r = await this.exec(code, timeoutSeconds);
        if (!r.ok) { throw new ReplError(lastLine(r.err)); }
        return r.out;
    }

    /** Write a file onto the board's filesystem, in chunks small enough for its RAM. */
    async writeFile(name: string, content: Bytes, onProgress?: (done: number, total: number) => void): Promise<void> {
        await this.evaluate(`f=open(${pyStr(name)},'wb')\nw=f.write`, 15);
        const step = 512;
        for (let i = 0; i < content.length; i += step) {
            const part = content.slice(i, i + step);
            await this.evaluate(`w(${pyBytes(part)})`, 15);
            onProgress?.(Math.min(i + step, content.length), content.length);
        }
        await this.evaluate('f.close()', 15);
    }
}

/** The last non-empty line of a traceback: what a message shows. */
export function lastLine(text: string): string {
    const lines = text.split(/\r?\n/).filter((l) => l.trim());
    return lines.length ? lines[lines.length - 1] : 'the board reported an error';
}

/** A Python string literal for a name (the board's filenames are plain ASCII). */
export function pyStr(s: string): string {
    return "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r') + "'";
}

/** A Python bytes literal, hex escaped: safe through the raw REPL whatever the content is. */
export function pyBytes(b: Bytes): string {
    let out = "b'";
    for (const x of b) { out += '\\x' + x.toString(16).padStart(2, '0'); }
    return out + "'";
}
