/* The live console: a helper that holds the board's serial port whenever nothing else needs it, and
 * relays JSON lines between the extension and a small agent program on the board. See
 * docs/CONSOLE_PROTOCOL.md for the wire format.
 *
 * The helper is a child process on the desktop (scripts/evn_console.py) and a Web Serial port in
 * the browser (src/platform/web/serialHelper.ts, the same protocol in TypeScript, uploading the
 * very same agent). Everything below talks to the `HelperProcess` interface and does not know
 * which of the two it has.
 *
 * The rules this file follows:
 *  - the port has one owner. The EVN terminal (a program or the REPL) always wins: when it opens
 *    the console is paused (quit, wait for the exit, only then is the port free) and it comes back
 *    a second after the terminal closes.
 *  - a program the board started by itself (main.py at power-on) is never interrupted: the helper
 *    reports "busy", the view offers "Stop the board's program and connect", and only that sends
 *    the `stop` command.
 *  - a helper that keeps dying is not restarted for ever: three failures within a minute leave the
 *    console in "error" until the user connects by hand or the board is unplugged and back.
 *  - the link may be a wire or the board's own Bluetooth module (BoardState.transport). Over the
 *    air the COM port stays listed whatever the board does, so a dropped link is never a plug
 *    event: the console retries by itself (5 s, doubling to 30 s) and the cable going back in is
 *    what clears the three-failure lock.
 */
import * as vscode from 'vscode';
import { HelperProcess, host } from './platform/host';
import { boardState, onDidChangeBoardState, portBusy, onDidChangeTerminal, evnTerminal } from './extension';
import { findPython, log } from './util';

export type ConsoleState = 'off' | 'connecting' | 'live' | 'busy' | 'paused' | 'gone' | 'error';

export interface ConsoleStatus {
    state: ConsoleState;
    detail: string;
    /** how the running helper reaches the board; undefined while the console is off or paused */
    transport?: 'usb' | 'bluetooth';
    /** the device name the running helper was started with (COM7, COM11) */
    port?: string;
    /** telemetry updates a second the running helper asked the board for (4 over USB) */
    rate?: number;
}

/** One `tele` event: the board's own clock, the pack and its two cells, the four motor ports. */
export interface Telemetry {
    /** board milliseconds */
    t: number;
    /** pack millivolts */
    batt?: number;
    /** the two cell millivolts */
    cells?: number[];
    /** angle in degrees, ports 1..4; null when that port could not be read */
    enc: (number | null)[];
    /** speed in degrees per second, ports 1..4 */
    spd: (number | null)[];
    /** watched I2C devices: port -> the watched method and its latest value, or the error text */
    watch?: Record<string, WatchValue>;
    /** when the extension received it */
    at: Date;
}

/** One entry of a `tele` event's `w` map. */
export interface WatchValue {
    /** the watched method name */
    m: string;
    /** its JSON-safe value (absent when the call raised) */
    v?: any;
    /** the exception text when the call raised */
    e?: string;
}

/** One entry of a `serial` event: a serial port the agent set up (1 = Serial 1, 2 = Serial 2). */
export interface SerialPortStatus {
    port: number;
    kind: 'bluetooth' | 'uart';
    /** the baud the agent opened a UART at; absent for a Bluetooth module (it keeps its own) */
    baud?: number;
    /** this module carries the live console itself, so `configure` never closes it */
    carrier?: boolean;
    /** evn.Bluetooth.state(): 'probing' | 'configuring' | 'resetting' | 'command' | 'data' | 'closed' */
    state?: string;
    ready?: boolean;
    /** the board's REPL is mirrored on this module */
    repl?: boolean;
    /** bytes waiting in the receive buffer */
    any?: number;
    /** the object could not be read */
    err?: string;
}

export interface I2cDevice {
    port: number;
    addr: number;
    /** the standard peripheral's name, null when the device was not identified */
    name: string | null;
    /** the `evn` class name, null when the device was not identified */
    kind: string | null;
}

const HISTORY_KEY = 'evn.console.history';
const HISTORY_MAX = 20;
const QUIT_GRACE_MS = 1500;          // after `quit`: how long the helper gets before it is killed
const RESUME_DEBOUNCE_MS = 1000;     // the terminal closed: let the OS release the port first
const START_DEBOUNCE_MS = 400;
const REQUEST_TIMEOUT_MS = 8000;
const FAIL_WINDOW_MS = 60000;
const FAIL_LIMIT = 3;
const BACKOFF_MAX_MS = 8000;
const BT_RETRY_MS = 5000;            // a dropped wireless link: the first retry
const BT_RETRY_MAX_MS = 30000;       // ... doubling up to this

/** Module level, so a listener that subscribes before registerConsole() still gets the events. */
const changedEmitter = new vscode.EventEmitter<void>();
/** fires when three failures in a minute locked the console, with the transport they happened over */
const lockEmitter = new vscode.EventEmitter<'usb' | 'bluetooth' | undefined>();
const telemetryEmitter = new vscode.EventEmitter<Telemetry>();
const devicesEmitter = new vscode.EventEmitter<I2cDevice[]>();
const serialEmitter = new vscode.EventEmitter<SerialPortStatus[]>();
/** every line that goes to the "EVN Console" output channel (commands, answers, the board's output) */
const lineEmitter = new vscode.EventEmitter<string>();

interface Pending {
    /** 'info' | 'devices' | 'done:rm' | 'done:configure' | 'result' */
    key: string;
    /** the exec id, for 'result' */
    id?: number;
    resolve: (value: any) => void;
    reject: (err: Error) => void;
    timer: any;
}

/* ---- the service ---------------------------------------------------------------------- */

class ConsoleService implements vscode.Disposable {
    private proc: HelperProcess | undefined;
    private state: ConsoleState = 'off';
    private detail = '';
    private paused = false;
    private pauseReason = '';
    /** paused by the user (evn.console.pause): only the user (evn.console.connect), a setting change or a
     *  re-plugged board brings it back; the automatic resume after a command or a terminal does not */
    private pausedByUser = false;
    private errorLocked = false;        // three failures in a minute: no more automatic restarts
    private quitting: Promise<void> | undefined;
    private startTimer: any;
    private failures: number[] = [];
    private nextExecId = 1;
    private pending: Pending[] = [];
    private telemetry: Telemetry | undefined;
    private devices: I2cDevice[] | undefined;
    private serialPorts: SerialPortStatus[] | undefined;
    private liveSince: Date | undefined;
    private disposed = false;
    private wasPresent = false;
    private activePort: string | undefined;   // the port the running helper was started with
    private countedThisRun = false;           // one failure per helper run, not one per symptom
    /** how the running helper reaches the board: the board state at start, the `live` event after */
    private transport: 'usb' | 'bluetooth' | undefined;
    /** telemetry updates a second of the running helper (what the `live` event reports) */
    private rate: number | undefined;
    /** the transport of the last board state, to notice the cable going in */
    private wasTransport: 'usb' | 'bluetooth' | undefined;
    /** the wireless link dropped: 5 s, doubling to 30 s (the COM port stays listed, so nothing else
     *  tells the console the board is back) */
    private btRetryMs = 0;

    readonly channel = vscode.window.createOutputChannel('EVN Console');

    constructor(private readonly ctx: vscode.ExtensionContext) {
        this.wasPresent = boardState().present;
        this.wasTransport = boardState().transport;
    }

    /* ---- state ------------------------------------------------------------------------ */

    status(): ConsoleStatus {
        return { state: this.state, detail: this.detail, transport: this.transport, port: this.activePort, rate: this.rate };
    }
    live(): boolean { return this.state === 'live'; }
    latestTelemetry(): Telemetry | undefined { return this.telemetry; }
    latestDevices(): I2cDevice[] | undefined { return this.devices; }
    latestSerial(): SerialPortStatus[] | undefined { return this.serialPorts; }
    /** when the current live link came up; undefined while not live */
    since(): Date | undefined { return this.state === 'live' ? this.liveSince : undefined; }

    /** One line to the "EVN Console" panel and to whoever mirrors it (the console view). */
    say(line: string): void {
        this.channel.appendLine(line);
        lineEmitter.fire(line);
    }

    private setState(state: ConsoleState, detail = ''): void {
        if (this.state === state && this.detail === detail) { return; }
        if (state === 'live' && this.state !== 'live') { this.liveSince = new Date(); }
        if (state !== 'live') { this.serialPorts = undefined; }
        // the transport belongs to a helper that is running or has just died (the `gone` and
        // `error` rows say over which link); nothing is running in `off` and `paused`
        if (state === 'off' || state === 'paused') { this.transport = undefined; this.activePort = undefined; this.rate = undefined; }
        this.state = state;
        this.detail = detail;
        void vscode.commands.executeCommand('setContext', 'evn.console.state', state);
        this.say(`[${new Date().toLocaleTimeString()}] console: ${state}${detail ? ` (${detail})` : ''}`);
        log(`console: ${state}${detail ? ` (${detail})` : ''}`);
        changedEmitter.fire();
    }

    private enabled(): boolean {
        return vscode.workspace.getConfiguration('evn').get<boolean>('console.enabled', true);
    }

    /* ---- starting and stopping -------------------------------------------------------- */

    /** Why the console cannot run right now, or undefined when it may. */
    private blocker(): string | undefined {
        if (this.disposed) { return 'the extension is shutting down'; }
        if (!this.enabled()) { return 'evn.console.enabled'; }
        if (this.paused) { return this.pauseReason || 'paused by you'; }
        if (this.errorLocked) { return this.detail || 'the console could not be started'; }
        if (portBusy()) { return terminalReason(); }
        const st = boardState();
        if (!st.hasMpremote) { return host().hasPython ? 'mpremote was not found' : 'no serial port has been granted in this browser'; }
        if (!st.port || !st.present) { return 'no board on USB or Bluetooth'; }
        return undefined;
    }

    /** Start the helper unless something is in the way; safe to call at any time. */
    scheduleStart(delayMs = START_DEBOUNCE_MS): void {
        if (this.startTimer) { clearTimeout(this.startTimer); }
        this.startTimer = setTimeout(() => { this.startTimer = undefined; void this.start(); }, delayMs);
    }

    async start(): Promise<void> {
        if (this.proc || this.quitting) { return; }
        const why = this.blocker();
        if (why) {
            if (!this.errorLocked) {
                this.setState(this.paused ? 'paused' : 'off', why);
            }
            return;
        }
        const port = boardState().port as string;
        const py = await findPython();
        if (!py) { this.setState('off', host().hasPython ? 'mpremote was not found' : 'this browser has no Web Serial'); return; }
        if (this.proc || this.disposed) { return; }              // findPython() is async: check again

        // the transport is known before the helper answers: the resolver already decided which
        // port this is, and the `live` event confirms it
        this.activePort = port;
        this.transport = boardState().transport;
        this.rate = undefined;
        // Over the air the telemetry shares the module with whatever the user's own program sends,
        // so the rate is a setting there (the board's own work is the same either way: the agent
        // reads the same values, only less often). USB keeps the full 4 a second and passes nothing.
        let rate: number | undefined;
        if (this.transport === 'bluetooth') {
            rate = bluetoothRate();
            log(`console: ${rate} telemetry update${rate === 1 ? '' : 's'} a second over Bluetooth (evn.console.bluetoothRate)`);
        }
        this.setState('connecting', port);
        let child: HelperProcess;
        try {
            child = await host().startHelper(this.ctx, py, port, rate);
        } catch (e: any) {
            this.noteFailure(`could not start the console helper: ${e?.message ?? e}`);
            return;
        }
        if (this.disposed) { child.kill(); return; }
        this.proc = child;
        this.countedThisRun = false;
        child.onLine((line) => { if (this.proc === child) { this.onLine(line); } });
        child.onStderr((line) => log(`console helper: ${line}`));
        child.onExit((code) => this.onExit(child, code));
    }

    /** Send `quit`, wait for the exit (kill after 1.5 s), so the port is free when this resolves. */
    async stop(reason: string, markPaused: boolean): Promise<void> {
        if (this.startTimer) { clearTimeout(this.startTimer); this.startTimer = undefined; }
        if (markPaused) { this.paused = true; this.pauseReason = reason; }
        if (this.quitting) { await this.quitting; }
        const child = this.proc;
        if (!child) {
            if (markPaused) { this.setState('paused', reason); }
            return;
        }
        this.quitting = new Promise<void>((resolve) => {
            let done = false;
            const finish = () => {
                if (done) { return; }
                done = true;
                clearTimeout(killer);
                resolve();
            };
            const killer = setTimeout(() => {
                log('console: the helper did not exit after quit; killing it');
                try { child.kill(); } catch { /* already gone */ }
                setTimeout(finish, 200);
            }, QUIT_GRACE_MS);
            child.onExit(finish);
            if (child.exited) { finish(); }
            try { child.write('{"cmd":"quit"}'); } catch { /* the pipe is already closed */ }
        });
        const wait = this.quitting;
        await wait;
        if (this.quitting === wait) { this.quitting = undefined; }
        this.proc = undefined;
        this.failPending(reason);
        if (markPaused) { this.setState('paused', reason); }
    }

    private onExit(child: HelperProcess, code: number | null): void {
        if (this.proc !== child) { return; }              // an exit we already accounted for
        this.proc = undefined;
        this.failPending('the console link closed');
        log(`console: the helper exited (code ${code ?? 'null'})`);
        if (this.quitting || this.paused || this.disposed) { return; }
        if (this.state === 'gone') {
            if (this.transport === 'bluetooth' && boardState().present) {
                // over the air nothing else will say the board is back: try again, slower and
                // slower, until the link answers or the cable comes in (which clears the count)
                this.btRetryMs = this.btRetryMs ? Math.min(BT_RETRY_MAX_MS, this.btRetryMs * 2) : BT_RETRY_MS;
                this.noteFailure('the Bluetooth link dropped', 'gone', this.btRetryMs);
                return;
            }
            // the board was unplugged: nothing to retry until it comes back
            return;
        }
        if (code === 0) {
            // the helper left on its own without a quit from here: unexpected, but not an error
            this.noteFailure('the console link closed', 'off');
            return;
        }
        this.noteFailure(this.detail || `the console helper stopped (exit code ${code ?? '?'})`);
    }

    /** Count one failure (once per helper run); after three within a minute stay in `error`
     *  until the user connects by hand or the board is unplugged and back. */
    private noteFailure(detail: string, state: ConsoleState = 'error', delayMs?: number): void {
        const now = Date.now();
        this.failures = this.failures.filter((t) => now - t < FAIL_WINDOW_MS);
        if (!this.countedThisRun) {
            this.countedThisRun = true;
            this.failures.push(now);
        }
        if (this.failures.length >= FAIL_LIMIT) {
            this.errorLocked = true;
            const over = this.transport;
            this.setState('error', `${detail} - click the plug to try again`);
            // whoever chose this link has to hear that it is not working (extension.ts gives the
            // board back to USB when the choice was "Bluetooth now")
            lockEmitter.fire(over);
            return;
        }
        this.setState(state, detail);
        const delay = delayMs ?? Math.min(BACKOFF_MAX_MS, 1000 * Math.pow(2, Math.max(0, this.failures.length - 1)));
        this.scheduleStart(delay);
    }

    /* ---- the wire --------------------------------------------------------------------- */

    private onLine(line: string): void {
        let msg: any;
        try { msg = JSON.parse(line); } catch {
            log(`console: helper line that is not JSON: ${line.slice(0, 200)}`);
            return;
        }
        if (!msg || typeof msg !== 'object') { return; }
        switch (msg.ev) {
            case 'state': this.onHelperState(msg); break;
            case 'tele': this.onTelemetry(msg); break;
            case 'devices': this.onDevices(msg); break;
            case 'serial': this.onSerial(msg); break;
            case 'out':
                if (typeof msg.text === 'string') {
                    for (const l of msg.text.split(/\r?\n/)) { this.say(l); }
                }
                break;
            case 'result': this.settle('result', msg, typeof msg.id === 'number' ? msg.id : undefined); break;
            case 'info': this.settle('info', msg); break;
            case 'done': this.settle(`done:${msg.cmd}`, msg, typeof msg.id === 'number' ? msg.id : undefined); break;
            default: log(`console: unknown event ${JSON.stringify(msg).slice(0, 200)}`); break;
        }
    }

    private onHelperState(msg: any): void {
        const state = String(msg.state ?? '');
        const detail = typeof msg.detail === 'string' ? msg.detail : '';
        switch (state) {
            case 'connecting':
                this.setState('connecting', detail || (boardState().port ?? ''));
                break;
            case 'live': {
                this.failures = [];
                this.btRetryMs = 0;
                if (msg.transport === 'bluetooth' || msg.transport === 'usb') { this.transport = msg.transport; }
                if (typeof msg.port === 'string' && msg.port) { this.activePort = msg.port; }
                this.rate = typeof msg.rate === 'number' && msg.rate > 0 ? msg.rate : 4;
                const bits = [msg.v ? `firmware ${msg.v}` : '', msg.serial ? `board ${msg.serial}` : '']
                    .filter(Boolean).join(', ');
                this.setState('live', bits);
                break;
            }
            case 'busy':
                this.setState('busy', detail || 'the board is running its own program');
                break;
            case 'gone':
                if (this.transport === 'bluetooth') {
                    // the COM port of a Bluetooth link stays listed whatever the board does, so the
                    // port listing never reports a plug event: the console has to try again itself
                    this.setState('gone', 'the Bluetooth link dropped');
                    this.failPending('the Bluetooth link dropped');
                } else {
                    this.setState('gone', detail || 'the board is no longer on USB');
                    this.failPending('the board is no longer on USB');
                }
                break;
            case 'error':
                this.failPending(detail || 'the console helper failed');
                this.noteFailure(detail || 'the console helper failed');
                break;
            default:
                log(`console: unknown helper state "${state}"`);
                break;
        }
    }

    private onTelemetry(msg: any): void {
        const nums = (v: any): (number | null)[] => Array.isArray(v)
            ? v.map((x) => (typeof x === 'number' ? x : null))
            : [null, null, null, null];
        const t: Telemetry = {
            t: typeof msg.t === 'number' ? msg.t : 0,
            batt: typeof msg.batt === 'number' ? msg.batt : undefined,
            cells: Array.isArray(msg.cells) ? msg.cells.filter((c: any) => typeof c === 'number') : undefined,
            enc: nums(msg.enc),
            spd: nums(msg.spd),
            at: new Date(),
        };
        if (msg.w && typeof msg.w === 'object') {
            const watch: Record<string, WatchValue> = {};
            for (const [port, entry] of Object.entries<any>(msg.w)) {
                if (!entry || typeof entry !== 'object') { continue; }
                const w: WatchValue = { m: String(entry.m ?? '') };
                if ('v' in entry) { w.v = entry.v; }
                if (typeof entry.e === 'string') { w.e = entry.e; }
                watch[port] = w;
            }
            t.watch = watch;
        }
        this.telemetry = t;
        telemetryEmitter.fire(t);
    }

    private onDevices(msg: any): void {
        const list: I2cDevice[] = Array.isArray(msg.i2c)
            ? msg.i2c.map((d: any) => ({
                port: Number(d?.port ?? 0),
                addr: Number(d?.addr ?? 0),
                name: typeof d?.name === 'string' ? d.name : null,
                kind: typeof d?.kind === 'string' ? d.kind : null,
            }))
            : [];
        this.devices = list;
        devicesEmitter.fire(list);
        this.settle('devices', msg);
    }

    private onSerial(msg: any): void {
        const list: SerialPortStatus[] = Array.isArray(msg.ports)
            ? msg.ports
                .filter((p: any) => p && typeof p === 'object')
                .map((p: any): SerialPortStatus => ({
                    port: Number(p.port ?? 0),
                    kind: p.kind === 'uart' ? 'uart' : 'bluetooth',
                    baud: typeof p.baud === 'number' ? p.baud : undefined,
                    carrier: p.carrier === true ? true : undefined,
                    state: typeof p.state === 'string' ? p.state : undefined,
                    ready: typeof p.ready === 'boolean' ? p.ready : undefined,
                    repl: typeof p.repl === 'boolean' ? p.repl : undefined,
                    any: typeof p.any === 'number' ? p.any : undefined,
                    err: typeof p.err === 'string' ? p.err : undefined,
                }))
            : [];
        this.serialPorts = list;
        serialEmitter.fire(list);
    }

    private settle(key: string, msg: any, id?: number): void {
        const i = this.pending.findIndex((p) => p.key === key && (p.id === undefined || p.id === id));
        if (i < 0) { return; }
        const p = this.pending.splice(i, 1)[0];
        clearTimeout(p.timer);
        p.resolve(msg);
    }

    private failPending(why: string): void {
        const all = this.pending;
        this.pending = [];
        for (const p of all) { clearTimeout(p.timer); p.reject(new Error(why)); }
    }

    /** Write one command object to the helper. Throws when there is no helper. */
    private write(cmd: object): void {
        const child = this.proc;
        if (!child || child.exited) {
            throw new Error('the live console is not connected');
        }
        child.write(JSON.stringify(cmd));
    }

    /** Fire and forget (`stop`, `reset`): allowed while busy, unlike consoleRequest(). */
    send(cmd: object): void { this.write(cmd); }

    request(cmd: any, timeoutMs = REQUEST_TIMEOUT_MS): Promise<any> {
        return new Promise<any>((resolve, reject) => {
            if (this.state !== 'live' || !this.proc) {
                reject(new Error('the live console is not connected'));
                return;
            }
            const name = String(cmd?.cmd ?? '');
            let key: string;
            let id: number | undefined;
            const out: any = { ...cmd };
            switch (name) {
                case 'exec': key = 'result'; id = this.nextExecId++; out.id = id; break;
                case 'call': key = 'done:call'; id = this.nextExecId++; out.id = id; break;
                case 'info': key = 'info'; break;
                case 'scan': key = 'devices'; break;
                case 'rm': case 'configure': case 'watch': key = `done:${name}`; break;
                default: reject(new Error(`the console command "${name}" has no answer`)); return;
            }
            const timer = setTimeout(() => {
                const i = this.pending.findIndex((p) => p.timer === timer);
                if (i >= 0) { this.pending.splice(i, 1); }
                reject(new Error(`the board did not answer "${name}" within ${Math.round(timeoutMs / 1000)} s`));
            }, timeoutMs);
            this.pending.push({ key, id, resolve, reject, timer });
            try { this.write(out); } catch (e: any) {
                const i = this.pending.findIndex((p) => p.timer === timer);
                if (i >= 0) { this.pending.splice(i, 1); }
                clearTimeout(timer);
                reject(e instanceof Error ? e : new Error(String(e)));
            }
        });
    }

    /* ---- what the user does ----------------------------------------------------------- */

    /** The plug button: clears "paused" and the error lock and starts now. */
    async connect(): Promise<void> {
        if (!this.enabled()) {
            const choice = await vscode.window.showInformationMessage(
                'EVN: the live console is switched off (evn.console.enabled).', 'Switch it on');
            if (choice !== 'Switch it on') { return; }
            await vscode.workspace.getConfiguration('evn').update('console.enabled', true, vscode.ConfigurationTarget.Global);
            return;         // the configuration listener starts it
        }
        this.paused = false;
        this.pauseReason = '';
        this.pausedByUser = false;
        this.errorLocked = false;
        this.failures = [];
        this.btRetryMs = 0;
        if (this.proc) {
            if (this.state === 'busy') {
                vscode.window.showInformationMessage('EVN: the board is running its own program. Use "Stop the board\'s program and connect" to interrupt it.');
            }
            return;
        }
        const why = this.blocker();
        if (why) {
            vscode.window.showInformationMessage(`EVN: the live console cannot connect: ${why}.`);
            this.setState('off', why);
            return;
        }
        await this.start();
    }

    async stopProgram(): Promise<void> {
        if (this.state !== 'busy' || !this.proc) {
            vscode.window.showInformationMessage('EVN: the board is not running a program of its own.');
            return;
        }
        this.say('--- stopping the program on the board ---');
        this.send({ cmd: 'stop' });
    }

    /* ---- the command line ------------------------------------------------------------- */

    private history(): string[] {
        const h = this.ctx.globalState.get<string[]>(HISTORY_KEY, []);
        return Array.isArray(h) ? h.filter((s) => typeof s === 'string') : [];
    }

    private async remember(code: string): Promise<void> {
        const h = [code, ...this.history().filter((s) => s !== code)].slice(0, HISTORY_MAX);
        await this.ctx.globalState.update(HISTORY_KEY, h);
    }

    /** A QuickPick over the history that also takes anything typed into it. */
    private askForCode(): Promise<string | undefined> {
        const history = this.history();
        const placeholder = 'Python to run on the board - m1..m4 are the motors, s1..s4 the configured servos, evn is imported';
        if (!history.length) {
            return Promise.resolve(vscode.window.showInputBox({
                title: 'Send a command to the board',
                prompt: placeholder,
                placeHolder: 'm1.run_angle(200, 90)',
                ignoreFocusOut: true,
            })) as Promise<string | undefined>;
        }
        return new Promise<string | undefined>((resolve) => {
            const qp = vscode.window.createQuickPick<vscode.QuickPickItem & { typed?: boolean }>();
            qp.title = 'Send a command to the board';
            qp.placeholder = placeholder;
            qp.ignoreFocusOut = true;
            const recent = history.map((h) => ({ label: h, description: 'recent' }));
            const build = (value: string) => {
                qp.items = value.trim()
                    ? [{ label: value.trim(), description: 'run this', alwaysShow: true, typed: true }, ...recent]
                    : recent;
            };
            build('');
            qp.onDidChangeValue(build);
            qp.onDidAccept(() => {
                const picked = qp.selectedItems[0];
                const value = picked ? picked.label : qp.value.trim();
                qp.hide();
                resolve(value.trim() || undefined);
            });
            qp.onDidHide(() => { qp.dispose(); resolve(undefined); });
            qp.show();
        });
    }

    async sendCommand(): Promise<void> {
        if (this.state !== 'live') {
            const why = this.state === 'busy'
                ? 'the board is running its own program; stop it first'
                : (this.detail || 'the live console is not connected');
            vscode.window.showWarningMessage(`EVN: cannot send a command: ${why}.`);
            return;
        }
        const code = await this.askForCode();
        if (!code) { return; }
        this.channel.show(true);
        const r = await this.runCode(code);
        if (!r.ok) { vscode.window.showWarningMessage(`EVN: ${r.last}`); }
    }

    /** Run one line in the agent's namespace: echoed as `>>> code`, the answer (or the traceback)
     *  goes to the panel line by line, and the line is remembered in the history. */
    async runCode(code: string): Promise<{ ok: boolean; out: string; last: string }> {
        await this.remember(code);
        this.say(`>>> ${code}`);
        try {
            const r = await this.request({ cmd: 'exec', code }, 30000);
            if (r?.ok) {
                const out: string = typeof r.out === 'string' ? r.out.replace(/\s+$/, '') : '';
                if (out) { for (const l of out.split(/\r?\n/)) { this.say(l); } }
                else { this.say('(no output)'); }
                return { ok: true, out, last: '' };
            }
            const err: string = (typeof r?.err === 'string' ? r.err : 'the board reported an error').replace(/\s+$/, '');
            for (const l of err.split(/\r?\n/)) { this.say(l); }
            const last = err.split(/\r?\n/).filter((l) => l.trim()).pop() ?? 'the board reported an error';
            return { ok: false, out: err, last };
        } catch (e: any) {
            const why = e?.message ?? String(e);
            this.say(`! ${why}`);
            return { ok: false, out: why, last: why };
        }
    }

    historyLines(): string[] { return this.history(); }

    /* ---- following the world ---------------------------------------------------------- */

    onBoardState(): void {
        const st = boardState();
        const present = st.present;
        // The cable going in while the board was reached over the air is the plug event of a
        // wireless session: the port listing never lost the Bluetooth COM port, so this is the
        // only thing that says "try again now" after the retries gave up.
        if (st.transport === 'usb' && this.wasTransport === 'bluetooth') {
            this.errorLocked = false;
            this.failures = [];
            this.btRetryMs = 0;
            if (this.state === 'gone' || this.state === 'error') { this.setState('off', 'the board is back on USB'); }
        }
        this.wasTransport = st.transport;
        if (present && !this.wasPresent) {
            // the board was plugged back in: a fresh start, even after three failures
            this.errorLocked = false;
            this.failures = [];
            if (this.state === 'gone' || this.state === 'error') { this.setState('off', 'the board is back'); }
            this.scheduleStart(800);
        } else if (!present && this.wasPresent) {
            // the helper notices this by itself and exits; give it a moment, then make sure
            setTimeout(() => {
                if (this.proc && !boardState().present) {
                    log('console: the port vanished and the helper is still alive; killing it');
                    try { this.proc.kill(); } catch { /* already gone */ }
                }
            }, 3000);
        } else if (present && !this.proc) {
            // a dropped wireless link already has a retry running with its own backoff: a port
            // listing that changed for some other reason must not shorten it
            if (!(this.state === 'gone' && this.transport === 'bluetooth' && this.startTimer)) { this.scheduleStart(); }
        } else if (present && this.proc && this.activePort && st.port && st.port !== this.activePort) {
            // the board in use moved to another port: take the helper with it
            void this.stop('the board port changed', false).then(() => this.scheduleStart(300));
        }
        this.wasPresent = present;
        changedEmitter.fire();
    }

    onTerminal(): void {
        if (portBusy()) {
            void this.stop(terminalReason(), true);
        } else if (this.paused) {
            this.resume();
        }
    }

    pauseByUser(): Promise<void> {
        this.pausedByUser = true;
        return this.stop('paused by you', true);
    }

    resume(): void {
        if (this.pausedByUser) { return; }
        this.paused = false;
        this.pauseReason = '';
        this.scheduleStart(RESUME_DEBOUNCE_MS);
    }

    /** The evn.port setting changed: move the helper to the new port. */
    onPortSettingChange(): void {
        if (!this.proc) { this.scheduleStart(600); return; }
        void this.stop('the board port changed', false).then(() => this.scheduleStart(600));
    }

    onConfigChange(): void {
        if (!this.enabled()) {
            void this.stop('evn.console.enabled', false).then(() => this.setState('off', 'evn.console.enabled'));
        } else {
            this.errorLocked = false;
            this.failures = [];
            this.paused = false;
            this.pauseReason = '';
            this.pausedByUser = false;
            this.scheduleStart(200);
        }
    }

    dispose(): void {
        this.disposed = true;
        if (this.startTimer) { clearTimeout(this.startTimer); this.startTimer = undefined; }
        this.failPending('the extension is shutting down');
        const child = this.proc;
        this.proc = undefined;
        if (child) {
            try { child.write('{"cmd":"quit"}'); } catch { /* the pipe is gone */ }
            setTimeout(() => { try { child.kill(); } catch { /* already gone */ } }, 300);
        }
        this.channel.dispose();
    }
}

/** Telemetry updates a second over Bluetooth (evn.console.bluetoothRate); anything else means 2. */
function bluetoothRate(): number {
    const v = vscode.workspace.getConfiguration('evn').get<number>('console.bluetoothRate', 2);
    return v === 1 || v === 4 ? v : 2;
}

/** "a program is running" / "the REPL is open": the EVN terminal's arguments say which. */
function terminalReason(): string {
    const t = evnTerminal();
    const opts = t?.creationOptions as vscode.TerminalOptions | undefined;
    const args = opts?.shellArgs;
    const flat = Array.isArray(args) ? args.join(' ') : (args ?? '');
    return /\brepl\b/.test(flat) ? 'the REPL is open' : 'a program is running';
}

/* ---- the module's face ----------------------------------------------------------------- */

let service: ConsoleService | undefined;

/** Fires whenever the console's state changes (and when the board state moves under it). */
export const onDidChangeConsole: vscode.Event<void> = changedEmitter.event;
export const onDidReceiveTelemetry: vscode.Event<Telemetry> = telemetryEmitter.event;
export const onDidReceiveDevices: vscode.Event<I2cDevice[]> = devicesEmitter.event;
/** Fires when three failures within a minute locked the console; the argument is the transport
 *  they happened over, so a wireless link that does not work can give the board back to USB. */
export const onDidLockConsole: vscode.Event<'usb' | 'bluetooth' | undefined> = lockEmitter.event;

export function consoleState(): ConsoleState { return service ? service.status().state : 'off'; }
export function consoleDetail(): string { return service ? service.status().detail : ''; }
export function consoleStatus(): ConsoleStatus { return service ? service.status() : { state: 'off', detail: '' }; }
/** How the running helper reaches the board ('bluetooth' = over the board's wireless link);
 *  undefined while the console is off or paused. */
export function consoleTransport(): 'usb' | 'bluetooth' | undefined { return service?.status().transport; }
export function consoleLive(): boolean { return service ? service.live() : false; }
/** When the current live link came up (for "connected 3 minutes ago"); undefined while not live. */
export function consoleSince(): Date | undefined { return service?.since(); }
export function latestTelemetry(): Telemetry | undefined { return service?.latestTelemetry(); }
export function latestDevices(): I2cDevice[] | undefined { return service?.latestDevices(); }
export function latestSerial(): SerialPortStatus[] | undefined { return service?.latestSerial(); }
export const onDidReceiveSerial: vscode.Event<SerialPortStatus[]> = serialEmitter.event;
/** Every line of the "EVN Console" panel as it is written: the console view mirrors it. */
export const onDidWriteConsoleLine: vscode.Event<string> = lineEmitter.event;
/** The command history (most recent first), as the command-line QuickPick shows it. */
export function consoleHistory(): string[] { return service ? service.historyLines() : []; }

/** Run one line of Python on the board as the "Send a command" QuickPick would: echoed, answered
 *  and remembered. Rejects only when the console is not live. */
export function consoleRunLine(code: string): Promise<{ ok: boolean; out: string; last: string }> {
    if (!service || !service.live()) { return Promise.reject(new Error('the live console is not connected')); }
    return service.runCode(code);
}

/** Send a command and wait for its answer event. Rejects when the console is not live. */
export function consoleRequest(cmd: object, timeoutMs?: number): Promise<any> {
    if (!service) { return Promise.reject(new Error('the live console is not connected')); }
    return service.request(cmd, timeoutMs);
}

/** Free the port: quit the helper, wait for the exit, and stay away until resumeConsole(). */
export async function pauseConsole(reason: string): Promise<void> {
    if (!service) { return; }
    await service.stop(reason, true);
}

/** Let the console come back (debounced ~1 s). */
export function resumeConsole(): void { service?.resume(); }

export function registerConsole(ctx: vscode.ExtensionContext): void {
    if (service) { return; }
    const svc = new ConsoleService(ctx);
    service = svc;
    ctx.subscriptions.push(svc);
    ctx.subscriptions.push({ dispose: () => { if (service === svc) { service = undefined; } } });
    void vscode.commands.executeCommand('setContext', 'evn.console.state', 'off');

    const reg = (id: string, fn: (...a: any[]) => any) =>
        ctx.subscriptions.push(vscode.commands.registerCommand(id, async (...a: any[]) => {
            try { await fn(...a); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));

    reg('evn.console.connect', () => svc.connect());
    reg('evn.console.pause', () => svc.pauseByUser());
    reg('evn.console.send', () => svc.sendCommand());
    reg('evn.console.stopProgram', () => svc.stopProgram());
    reg('evn.console.showOutput', () => { svc.channel.show(true); });
    ctx.subscriptions.push(serialEmitter, lineEmitter, lockEmitter);

    ctx.subscriptions.push(onDidChangeBoardState(() => svc.onBoardState()));
    ctx.subscriptions.push(onDidChangeTerminal(() => svc.onTerminal()));
    ctx.subscriptions.push(vscode.workspace.onDidChangeConfiguration((e) => {
        if (e.affectsConfiguration('evn.console.enabled')) { svc.onConfigChange(); }
        else if (e.affectsConfiguration('evn.port')) { svc.onPortSettingChange(); }
    }));

    svc.scheduleStart(1500);        // let the extension (and the port listing) settle first
}
