export const DOCS_URL = 'https://evn.coresg.tech';

/** The online documentation root (the evn.docsUrl setting, without a trailing slash). */
export function docsUrl(): string {
    const u = vscode.workspace.getConfiguration('evn').get<string>('docsUrl', DOCS_URL).trim();
    return (u || DOCS_URL).replace(/\/+$/, '');
}

/**
 * The user's pairing of one board with the Windows "Standard Serial over Bluetooth link (COMxx)"
 * port of the EVN Bluetooth module on it. A Bluetooth port carries no USB descriptor, so this is
 * the only thing that says which board answers there.
 */
export interface BluetoothLink {
    /** the COM port of the module, as the port listing names it */
    device: string;
    /** what the OS calls that port, for the tooltips */
    description: string;
    /** when the link was remembered (Date.now()) */
    at: number;
    /** the module's Bluetooth address ("98:D3:41:F7:18:02") when the OS gave one: the link
     *  follows the address, so Windows renumbering the COM port does not break it */
    address?: string;
}

/** `COM11 (98:D3:41:F7:18:02)`, or just the COM port where the OS names no address. */
export function linkLabel(link: BluetoothLink | undefined): string {
    if (!link) { return ''; }
    return link.address ? `${link.device} (${link.address})` : link.device;
}

/** What the status bar knows about the board: refreshed every 4 s by listing ports (never by talking to the board). */
export interface BoardState {
    hasMpremote: boolean;
    /** the port in use this session: always a device name (COM7, /dev/ttyACM0), never a serial number */
    port: string | undefined;
    /** the port is present on USB right now */
    present: boolean;
    /** how many EVN ALPHA boards are on USB */
    boards: number;
    /** USB serial number of the board on `port` (the RP2040 unique id), when the port listing gave one */
    serial?: string;
    /** the name the user gave this board (evn.nameBoard), if any */
    name?: string;
    /** root of the RPI-RP2 drive when a board is in UF2 (BOOTSEL) mode, e.g. "E:\\" */
    bootsel?: string;
    /** how `port` reaches the board; set only when present */
    transport?: 'usb' | 'bluetooth';
    /** the remembered wireless link of the board with `serial`, whatever transport is in use */
    link?: BluetoothLink;
    /** the user asked for the wireless link even though USB is there ("Switch to Bluetooth now") */
    preferred?: boolean;
}
const boardStateEmitter = new vscode.EventEmitter<BoardState>();
export const onDidChangeBoardState = boardStateEmitter.event;
let lastBoardState: BoardState = { hasMpremote: false, port: undefined, present: false, boards: 0 };
export function boardState(): BoardState { return lastBoardState; }
/** Refresh the port listing now (what the 4 s timer does). */
export function refreshBoardState(): Promise<void> { return refreshStatus(); }

const terminalEmitter = new vscode.EventEmitter<vscode.Terminal | undefined>();
/** Fires when the EVN terminal (the one process allowed to hold the port) opens or closes. */
export const onDidChangeTerminal = terminalEmitter.event;
/** The EVN terminal holds the port (a program is running or the REPL is open), so nothing else may talk to the board. */
export function portBusy(): boolean { return terminal !== undefined; }
export function evnTerminal(): vscode.Terminal | undefined { return terminal; }

const TERMINAL_NAME = 'EVN ALPHA';
const PYPI_INSTALL_HINT = 'pip install mpremote';
/** how often the port listing is refreshed (it spawns a short-lived Python, so a poll is skipped while one runs) */
const POLL_MS = 4000;
/** globalState key of the board names: { "E46320165B5F2A36": "Kenneth's robot" } */
const BOARD_NAMES_KEY = 'evn.boardNames';
/** globalState key of the wireless links: { "E46320165B5F2A36": { device: "COM11", ... } } */
const BLUETOOTH_LINKS_KEY = 'evn.bluetoothLinks';
/** globalState key: the serial of the last board that was here over USB (the auto-detect failover) */
const LAST_BOARD_KEY = 'evn.lastBoard';

let ctx: vscode.ExtensionContext;
let statusItem: vscode.StatusBarItem;
let replItem: vscode.StatusBarItem;
let terminal: vscode.Terminal | undefined;
let selectedPort: string | undefined;       // the port in use this session (setting or auto-detected)
let refreshTimer: NodeJS.Timeout | undefined;
let refreshing = false;
let blocks: BlocksEditorProvider;

export async function activate(context: vscode.ExtensionContext): Promise<void> {
    ctx = context;
    await host().activate(context);
    void vscode.commands.executeCommand('setContext', 'evn.hasPython', host().hasPython);
    void vscode.commands.executeCommand('setContext', 'evn.hasFileExplorer', host().hasFileExplorer);
    statusItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 50);
    statusItem.name = 'EVN ALPHA board';
    statusItem.command = 'evn.selectPort';
    statusItem.text = '$(circuit-board) EVN: ...';
    statusItem.tooltip = 'EVN ALPHA: click to choose the board port';
    statusItem.show();
    // a REPL button next to the port: the prompt is the quickest way to try a call, and with
    // Display.mirror(True) it is what puts the REPL on the OLED (owner request 2026-09-17)
    replItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 49);
    replItem.name = 'EVN ALPHA REPL';
    replItem.command = 'evn.openRepl';
    replItem.text = '$(terminal) REPL';
    replItem.tooltip = 'EVN ALPHA: open the MicroPython REPL in a terminal (Ctrl+] to leave)';
    replItem.show();
    context.subscriptions.push(statusItem, replItem);

    const reg = (id: string, fn: (...a: any[]) => any) =>
        context.subscriptions.push(vscode.commands.registerCommand(id, async (...a: any[]) => {
            try { await fn(...a); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`, 'Show log').then((c) => { if (c) { output.show(); } });
            } finally {
                if (!terminal) { resumeConsole(); }
            }
        }));

    reg('evn.selectPort', selectPort);
    reg('evn.bluetooth.usePort', useBluetoothPort);
    reg('evn.bluetooth.preferWireless', preferWireless);
    reg('evn.bluetooth.preferUsb', preferUsb);
    reg('evn.nameBoard', nameBoard);
    reg('evn.runFile', runFile);
    reg('evn.uploadMain', uploadMain);
    reg('evn.openRepl', openRepl);
    reg('evn.stopMotors', stopMotors);
    reg('evn.listFiles', listFiles);
    reg('evn.removeMain', removeMain);
    reg('evn.resetBoard', resetBoard);
    reg('evn.flashFirmware', flashFirmware);
    reg('evn.diagnostics', diagnostics);
    reg('evn.newProject', newProject);
    reg('evn.openApiReference', () => openDoc('API.md'));
    reg('evn.openGettingStarted', () => openDoc('GETTING_STARTED.md'));
    reg('evn.openBlocksReference', () => openDoc('BLOCKS.md'));
    reg('evn.installMpremote', installMpremote);
    reg('evn.openDocumentation', () => vscode.env.openExternal(vscode.Uri.parse(docsUrl())));

    blocks = BlocksEditorProvider.register(context, {
        runPython: (file) => runFile(file),
        uploadMain: (file) => uploadMain(file),
        stopMotors,
    });
    reg('evn.newBlocksFile', () => newBlocksFile(context));
    reg('evn.runBlocks', () => blocks.run());
    reg('evn.uploadBlocksMain', () => blocks.upload());
    reg('evn.exportBlocksPython', () => blocks.exportPython());

    // the sidebar: Start / My projects / Examples. The projects folder exists from the first activation on.
    try { await ensureProjectsFolder(context); }
    catch (e: any) { log(`ERROR projects folder: ${e?.stack ?? e}`); }
    registerProjectsView(context, { runFile, uploadMain, blocks });
    registerExamples(context, { runFile, blocks });
    registerBoardView(context, { flashFirmware, selectPort });
    registerRunStatus(context, { stopMotors });
    registerWalkthrough(context);
    registerDocsLinks(context);
    registerConsole(context);
    registerConsoleView(context);
    registerBatteryStatus(context);

    // Three failures in a minute over the air mean the link is not there: keeping USB ignored
    // would leave the user with a board they can see and cannot reach, so the choice ends here.
    context.subscriptions.push(onDidLockConsole((transport) => {
        if (transport !== 'bluetooth' || !wirelessPreferredFlag) { return; }
        setWirelessPreferred(false);
        log('the console locked over Bluetooth: back to USB');
        vscode.window.showInformationMessage(
            'EVN: the wireless link failed three times, so the board is back on USB. '
            + 'Press "Switch the board to Bluetooth now" to try the air again.');
        void refreshStatus();
    }));

    context.subscriptions.push(statusItem, output);
    context.subscriptions.push(vscode.window.onDidCloseTerminal((t) => { if (t === terminal) { terminal = undefined; terminalEmitter.fire(undefined); } }));
    context.subscriptions.push(vscode.workspace.onDidChangeConfiguration((e) => {
        if (e.affectsConfiguration('evn.pythonPath')) { forgetPython(); }
        if (e.affectsConfiguration('evn')) { void refreshStatus(); }
    }));

    // A board that is unplugged, re-plugged or re-enumerated should show up within a couple of
    // seconds; the listing skips a poll while the previous one is still running, so a slow machine
    // simply polls less often. Coming back to the window polls at once: that is when the user has
    // just plugged the board in or pressed BOOTSEL.
    void refreshStatus();
    refreshTimer = setInterval(() => { void refreshStatus(); }, POLL_MS);
    context.subscriptions.push(vscode.window.onDidChangeWindowState((s) => { if (s.focused) { void refreshStatus(); } }));
    context.subscriptions.push({ dispose: () => { if (refreshTimer) { clearInterval(refreshTimer); } } });
    log(`extension ${context.extension.packageJSON.version} activated`);
}

export function deactivate(): void {
    if (refreshTimer) { clearInterval(refreshTimer); }
}

/* ---- status bar / port ----------------------------------------------------------------- */

/**
 * The `evn.port` setting holds either a USB serial number (an EVN ALPHA chosen in the picker: the
 * board is then found wherever Windows puts it today) or a device name such as COM7 or /dev/ttyACM0
 * (a Bluetooth port, or a board that reports no serial number). Empty = auto-detect.
 */
function configuredPort(): string {
    return vscode.workspace.getConfiguration('evn').get<string>('port', '').trim();
}

/** COM7, /dev/ttyACM0, \\.\COM12 and the browser's "Web Serial 1" are device names; anything else
 *  in evn.port is a USB serial number. */
function looksLikeDevice(value: string): boolean {
    return /^(com\d+|\/dev\/|\\\\|tty|web serial \d+$)/i.test(value);
}

/* ---- board names ------------------------------------------------------------------------ */

function storedNames(): { [serial: string]: string } {
    return ctx?.globalState.get<{ [serial: string]: string }>(BOARD_NAMES_KEY, {}) ?? {};
}

/** The name the user gave the board with this USB serial number, if any. */
export function boardName(serial: string | undefined): string | undefined {
    if (!serial) { return undefined; }
    const n = storedNames()[serial];
    return n && n.trim() ? n.trim() : undefined;
}

/** Name a board (an empty name forgets it). Names are per user (globalState), not per workspace. */
export async function setBoardName(serial: string, name: string): Promise<void> {
    const all = { ...storedNames() };
    if (name.trim()) { all[serial] = name.trim(); } else { delete all[serial]; }
    await ctx.globalState.update(BOARD_NAMES_KEY, all);
    log(name.trim() ? `board ${serial} named "${name.trim()}"` : `board ${serial} name cleared`);
}

/* ---- wireless links ---------------------------------------------------------------------- */

/*
 * A board is remembered by its USB serial number, but a Bluetooth COM port has no descriptor at
 * all: pairing one with the other is something only the user can do, and it is what lets the
 * board keep its name, its port configuration and its watches when the cable comes out. The link
 * is per user (globalState), like the names.
 */

function storedLinks(): { [serial: string]: BluetoothLink } {
    return ctx?.globalState.get<{ [serial: string]: BluetoothLink }>(BLUETOOTH_LINKS_KEY, {}) ?? {};
}

/** The wireless link of the board with this USB serial number, if the user paired one. */
export function bluetoothLinkFor(serial: string | undefined): BluetoothLink | undefined {
    if (!serial) { return undefined; }
    const link = storedLinks()[serial];
    return link && link.device ? link : undefined;
}

/** Remember that this Bluetooth COM port reaches the board with this serial number. */
export async function rememberBluetoothLink(serial: string, port: BoardPort): Promise<void> {
    const all = { ...storedLinks() };
    all[serial] = { device: port.device, description: describePort(port), at: Date.now(), address: port.address };
    await ctx.globalState.update(BLUETOOTH_LINKS_KEY, all);
    log(`board ${serial} wireless link: ${port.device}${port.address ? ` (${port.address})` : ''}`);
    await refreshStatus();
}

/** Serials whose link is being written back right now, so one move is logged and stored once. */
const movingLinks = new Set<string>();

/** Windows gave the module another COM number: follow it, quietly, and keep the address. */
async function moveBluetoothLink(serial: string, port: BoardPort): Promise<void> {
    if (movingLinks.has(serial)) { return; }
    movingLinks.add(serial);
    try {
        const all = { ...storedLinks() };
        const link = all[serial];
        if (!link || link.device.toLowerCase() === port.device.toLowerCase()) { return; }
        log(`wireless link of ${serial} moved ${link.device} -> ${port.device}`);
        all[serial] = { ...link, device: port.device, description: describePort(port), address: port.address ?? link.address };
        await ctx.globalState.update(BLUETOOTH_LINKS_KEY, all);
    } finally {
        movingLinks.delete(serial);
    }
}

export async function forgetBluetoothLink(serial: string): Promise<void> {
    const all = { ...storedLinks() };
    if (!(serial in all)) { return; }
    delete all[serial];
    await ctx.globalState.update(BLUETOOTH_LINKS_KEY, all);
    log(`board ${serial} wireless link forgotten`);
    await refreshStatus();
}

/** Which board answers on this Bluetooth COM port, from the links the user made. */
function linkedSerialOf(device: string): string | undefined {
    const all = storedLinks();
    for (const serial of Object.keys(all)) {
        if (all[serial]?.device?.toLowerCase() === device.toLowerCase()) { return serial; }
    }
    return undefined;
}

/** The last board that was here over USB: what auto-detect falls back to when the cable is out. */
function lastBoardSerial(): string | undefined {
    const s = ctx?.globalState.get<string>(LAST_BOARD_KEY, '');
    return s ? s : undefined;
}

/**
 * The port a remembered link points at, when that COM port is listed right now.
 *
 * The module's Bluetooth address is what does not change: Windows renumbers a "Standard Serial
 * over Bluetooth link" whenever the pairing is redone or another adapter is used, and the COM
 * number in the link would then point at nothing (or, worse, at another module). So the address
 * is matched first and the stored number is quietly written back when it moved; a link made on a
 * system that reports no address (Linux, macOS) still matches by device name.
 */
function linkPort(ports: BoardPort[], serial: string | undefined): BoardPort | undefined {
    const link = bluetoothLinkFor(serial);
    if (!link) { return undefined; }
    if (link.address && serial) {
        const byAddress = ports.find((p) => p.address === link.address);
        if (byAddress) {
            if (byAddress.device.toLowerCase() !== link.device.toLowerCase()) { void moveBluetoothLink(serial, byAddress); }
            return byAddress;
        }
    }
    return ports.find((p) => p.device.toLowerCase() === link.device.toLowerCase());
}

/* ---- the wireless link by choice ---------------------------------------------------------- */

/*
 * "Switch the board to Bluetooth now": the resolver prefers USB at every poll (the standing rule
 * is that the board comes back to the wire by itself), so testing the failover would mean pulling
 * the cable. This flag suspends that preference for the session only — it is deliberately NOT
 * persisted, so a restart puts the board back on USB whatever was tried last.
 */
let wirelessPreferredFlag = false;

/** The user asked for the wireless link even though USB is available (this session only). */
export function wirelessPreferred(): boolean { return wirelessPreferredFlag; }

function setWirelessPreferred(on: boolean): void {
    if (wirelessPreferredFlag === on) { return; }
    wirelessPreferredFlag = on;
    void vscode.commands.executeCommand('setContext', 'evn.wirelessPreferred', on);
}

/** the last value pushed into `evn.bluetooth.linked` (setContext only when it changes) */
let linkedContext: boolean | undefined;
function setLinkedContext(on: boolean): void {
    if (linkedContext === on) { return; }
    linkedContext = on;
    void vscode.commands.executeCommand('setContext', 'evn.bluetooth.linked', on);
}

/* ---- status bar ------------------------------------------------------------------------- */

async function refreshStatus(): Promise<void> {
    if (refreshing) { return; }
    refreshing = true;
    try {
        const bootsel = host().findBootselDrive();
        const py = await findPython();
        if (!py) {
            // Flashing needs no Python at all, so a board sitting in BOOTSEL is still offered the flash.
            if (bootsel) {
                showBootselStatus(bootsel, 'Python with mpremote was not found, but flashing the firmware does not need it.');
            } else {
                const why = host().noToolchainStatus();
                statusItem.command = 'evn.selectPort';
                statusItem.text = why.text;
                statusItem.tooltip = why.tooltip;
                statusItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
            }
            // On the desktop there is no point polling ports every few seconds without a tool to do
            // it with. In the browser this is the ordinary first-run state (no port granted yet) and
            // the poll is free - nothing is spawned, navigator.serial.getPorts() is a local call -
            // so it keeps running and the status comes back by itself the moment a port is granted.
            if (host().hasPython && refreshTimer) { clearInterval(refreshTimer); refreshTimer = undefined; }
            publishBoardState({ hasMpremote: false, port: undefined, present: false, boards: 0, bootsel });
            return;
        }
        if (!refreshTimer) { refreshTimer = setInterval(() => { void refreshStatus(); }, POLL_MS); }
        const ports = await listPorts(py);
        const evn = ports.filter(isEvnPort);
        const cfg = configuredPort();

        // Resolve the setting to a port that is here now: by serial number first (the board keeps
        // its identity when Windows re-enumerates it on another COM number), then by device name.
        // USB is preferred at every poll, so a board that has the cable back in comes back to the
        // wire by itself; the wireless link is only what is left when the cable is out.
        let chosen: BoardPort | undefined;
        let transport: 'usb' | 'bluetooth' | undefined;
        let linked: string | undefined;     // the board serial behind a Bluetooth port
        let missing: string | undefined;    // the configured board/port, when it is not here
        if (cfg && !looksLikeDevice(cfg)) {
            chosen = ports.find((p) => portSerial(p) === cfg);
            if (chosen) {
                transport = 'usb';
            } else {
                const bt = linkPort(ports, cfg);
                if (bt) { chosen = bt; transport = 'bluetooth'; linked = cfg; }
            }
            if (!chosen) {
                missing = cfg;
                // Do not hold the user hostage to a board they cannot plug in: if exactly one EVN ALPHA
                // is here, use it and say so in the tooltip.
                if (evn.length === 1) { chosen = evn[0]; transport = 'usb'; }
            }
        } else if (cfg) {
            chosen = ports.find((p) => p.device.toLowerCase() === cfg.toLowerCase());
            if (chosen) {
                // a Bluetooth port the user set by hand: a link tells us whose board it is, so the
                // Board view keys its configuration, watches and last values by that board
                transport = isBluetoothPort(chosen) ? 'bluetooth' : 'usb';
                if (transport === 'bluetooth') { linked = linkedSerialOf(chosen.device); }
            } else {
                missing = cfg;
                if (evn.length === 1) { chosen = evn[0]; transport = 'usb'; }
            }
        } else if (evn.length) {
            chosen = evn.find((p) => p.device === selectedPort) ?? evn[0];
            transport = 'usb';
        } else {
            // auto-detect with no board on the wire: the last board that was, over its link
            const last = lastBoardSerial();
            const bt = linkPort(ports, last);
            if (bt) { chosen = bt; transport = 'bluetooth'; linked = last; }
        }

        // "Switch the board to Bluetooth now": every case above prefers USB, so the only place the
        // choice can be honoured is here, once the board is known. It undoes itself the moment the
        // module stops being listed (unpaired, out of range, powered off), which is the one case
        // where staying off the wire would leave the user with no board at all.
        if (wirelessPreferredFlag) {
            const who = (chosen ? portSerial(chosen) ?? linked : undefined) ?? lastBoardSerial();
            const bt = linkPort(ports, who);
            if (bt) {
                chosen = bt;
                transport = 'bluetooth';
                linked = who;
                missing = undefined;
            } else {
                setWirelessPreferred(false);
                log('the wireless link is not listed any more: back to USB');
                vscode.window.showInformationMessage(
                    'EVN: the wireless link is not listed any more (module off, out of range or unpaired), so the board is back on USB.');
            }
        }

        const serial = chosen ? (portSerial(chosen) ?? linked) : undefined;
        const name = boardName(serial);
        const present = chosen !== undefined;
        const link = bluetoothLinkFor(serial);
        // the failover only knows where to go because a board was here over USB once
        if (transport === 'usb' && serial && chosen && isEvnPort(chosen) && lastBoardSerial() !== serial) {
            void ctx.globalState.update(LAST_BOARD_KEY, serial);
        }
        // never hand mpremote a serial number: the port is a device name or nothing
        selectedPort = chosen ? chosen.device : (missing && looksLikeDevice(missing) ? missing : undefined);

        if (chosen && transport === 'bluetooth') {
            statusItem.command = 'evn.selectPort';
            statusItem.backgroundColor = undefined;
            statusItem.text = `$(broadcast) EVN: ${name ?? chosen.device} (Bluetooth${wirelessPreferredFlag ? ', USB ignored' : ''})`;
            // name the module's address where the link in use is the remembered one: that is what
            // the picker showed, and it is what stays the same when Windows renumbers the port
            const where = link && link.device.toLowerCase() === chosen.device.toLowerCase() ? linkLabel(link) : chosen.device;
            const lines = [name
                ? `${name} is reached over its wireless link on ${where}`
                : `The board is reached over its wireless link on ${where}`];
            if (serial) { lines.push(`serial ${serial}`); }
            if (wirelessPreferredFlag) {
                lines.push('You asked for the wireless link ("Switch the board to Bluetooth now"), so USB is ignored');
                lines.push('even while the cable is in — this is the failover exactly as it behaves without a cable.');
                lines.push('Press "Switch the board back to USB" on the Bluetooth row (or restart VS Code) to end it.');
            } else {
                lines.push('The USB cable can stay out: everything works over the air, a little slower.');
                lines.push('Plug the cable back in and the board moves back to USB by itself.');
            }
            lines.push('Click to choose another board.');
            statusItem.tooltip = lines.join('\n');
        } else if (chosen) {
            statusItem.command = 'evn.selectPort';
            statusItem.backgroundColor = undefined;
            statusItem.text = name ? `$(circuit-board) EVN: ${name} (${chosen.device})` : `$(circuit-board) EVN: ${chosen.device}`;
            const what = isEvnPort(chosen) ? 'EVN ALPHA' : isBluetoothPort(chosen) ? 'Board over Bluetooth' : 'Board';
            const lines = [name ? `${name} — ${what} on ${chosen.device}` : `${what} on ${chosen.device}`];
            if (serial) { lines.push(`serial ${serial}`); }
            if (missing) { lines.push(`The board set in the settings (${boardName(missing) ? `"${boardName(missing)}", ` : ''}${looksLikeDevice(missing) ? missing : `serial ${missing}`}) is not connected; this is the one board that is.`); }
            if (evn.length > 1) { lines.push(`${evn.length} boards connected — click to choose`); }
            lines.push('Click to choose another board; "EVN: Name this board" gives it a name.');
            statusItem.tooltip = lines.join('\n');
        } else if (bootsel) {
            showBootselStatus(bootsel);
        } else if (selectedPort || missing) {
            const what = missing && !looksLikeDevice(missing) ? (boardName(missing) ?? `serial ${missing}`) : (selectedPort ?? missing ?? '');
            statusItem.command = 'evn.selectPort';
            statusItem.backgroundColor = undefined;
            statusItem.text = `$(circuit-board) EVN: ${what} (not connected)`;
            statusItem.tooltip = `The board set in the settings (${missing}) is not on USB right now. Click to choose another.`;
        } else {
            statusItem.command = 'evn.selectPort';
            statusItem.backgroundColor = undefined;
            statusItem.text = '$(circuit-board) EVN: no board';
            statusItem.tooltip = 'No EVN ALPHA found on USB. Plug the board in (or hold BOOTSEL while plugging in to flash it).';
        }
        // the button rows ask "is there a link to switch to?" about the board in hand, and about the
        // last board over USB when the cable is out and nothing resolved
        setLinkedContext(!!(link ?? bluetoothLinkFor(lastBoardSerial())));
        publishBoardState({
            hasMpremote: true, port: selectedPort, present, boards: evn.length, serial, name, bootsel,
            transport: present ? transport : undefined, link,
            preferred: wirelessPreferredFlag ? true : undefined,
        });
    } finally {
        refreshing = false;
    }
}

/** A board in UF2 (BOOTSEL) mode has no COM port at all: the only thing to do with it is flash it. */
function showBootselStatus(drive: string, extra?: string): void {
    statusItem.command = 'evn.flashFirmware';
    statusItem.text = '$(circuit-board) EVN: BOOTSEL mode — click to flash';
    statusItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
    statusItem.tooltip = [
        `A board is in UF2 (BOOTSEL) mode: it is the drive ${drive} and has no COM port until it is flashed.`,
        extra ?? '',
        'Click to flash the bundled MicroPython firmware.',
    ].filter(Boolean).join('\n');
}

function publishBoardState(next: BoardState): void {
    const prev = lastBoardState;
    lastBoardState = next;
    if (prev.hasMpremote !== next.hasMpremote) { void vscode.commands.executeCommand('setContext', 'evn.hasMpremote', next.hasMpremote); }
    if (prev.present !== next.present) { void vscode.commands.executeCommand('setContext', 'evn.boardConnected', next.present); }
    if (!!prev.bootsel !== !!next.bootsel) { void vscode.commands.executeCommand('setContext', 'evn.bootsel', !!next.bootsel); }
    if (prev.hasMpremote !== next.hasMpremote || prev.port !== next.port || prev.present !== next.present
        || prev.boards !== next.boards || prev.serial !== next.serial || prev.name !== next.name || prev.bootsel !== next.bootsel
        || prev.transport !== next.transport || prev.link?.device !== next.link?.device
        || prev.preferred !== next.preferred) {
        boardStateEmitter.fire(next);
    }
}

/* ---- the port picker -------------------------------------------------------------------- */

interface PortItem extends vscode.QuickPickItem {
    /** what goes into the evn.port setting: a serial number, a device name, or '' for auto-detect */
    value?: string;
    port?: BoardPort;
    refresh?: boolean;
}

const NAME_BUTTON: vscode.QuickInputButton = { iconPath: new vscode.ThemeIcon('tag'), tooltip: 'Name this board' };

/** The line under a port in a picker; a Bluetooth port names the module it dials. */
function portDetail(p: BoardPort): string {
    return p.address ? `${describePort(p)} · ${p.address}` : describePort(p);
}

/** What a picker offers: the incoming port Windows makes per adapter reaches no module, ever. */
function pickablePorts(ports: BoardPort[]): BoardPort[] {
    return ports.filter((p) => !isIncomingBluetoothPort(p));
}

function portItems(ports: BoardPort[]): PortItem[] {
    const items: PortItem[] = ports.map((p) => {
        const evn = isEvnPort(p);
        const serial = portSerial(p);
        const name = evn ? boardName(serial) : undefined;
        const icon = evn ? '$(circuit-board) ' : isBluetoothPort(p) ? '$(broadcast) ' : '';
        return {
            label: `${icon}${p.device}${name ? ` — ${name}` : ''}`,
            description: evn ? `EVN ALPHA${serial ? ` · serial ${serial}` : ''}` : p.vidpid,
            detail: portDetail(p),
            // an EVN board is remembered by its serial number, so it is found again on any COM number
            value: evn && serial ? serial : p.device,
            port: p,
            buttons: evn && serial ? [NAME_BUTTON] : undefined,
        };
    });
    items.push({ label: '$(sync) Auto-detect (first EVN ALPHA found)', value: '' });
    items.push({ label: '$(refresh) Refresh the list', refresh: true });
    return items;
}

async function selectPort(): Promise<void> {
    // a browser hands out ports through its own chooser, one at a time: that is the whole picker
    if (host().requestPort) {
        const picked = await host().requestPort!();
        if (picked) {
            await vscode.workspace.getConfiguration('evn').update('port', picked.device, vscode.ConfigurationTarget.Global);
        }
        await refreshStatus();
        return;
    }
    const py = await requirePython();
    const qp = vscode.window.createQuickPick<PortItem>();
    qp.placeholder = 'Which EVN ALPHA? (a "Standard Serial over Bluetooth" port reaches a board whose Bluetooth module carries the REPL)';
    qp.ignoreFocusOut = true;
    qp.matchOnDetail = true;
    let picked: PortItem | undefined;

    const fill = async () => {
        qp.busy = true;
        try { qp.items = portItems(pickablePorts(await listPorts(py))); }
        finally { qp.busy = false; }
    };

    const done = new Promise<void>((resolve) => {
        qp.onDidHide(() => { qp.dispose(); resolve(); });
        qp.onDidAccept(() => {
            const item = qp.activeItems[0];
            if (!item) { return; }
            if (item.refresh) { void fill(); return; }
            picked = item;
            qp.hide();
        });
        // the tag button names the board without leaving the picker
        qp.onDidTriggerItemButton(async (e) => {
            if (!e.item.port) { return; }
            await promptForName(e.item.port);
            await fill();
            qp.show();          // the input box took the focus; come back to the list
            await refreshStatus();
        });
    });

    qp.show();
    await fill();
    await done;

    if (!picked) { return; }
    // Picking the Bluetooth port of a known board is not "use COM11", it is "COM11 is how this
    // board is reached without the cable": the setting stays the board's serial number, so USB
    // wins again the moment the cable is in.
    const board = picked.port && isBluetoothPort(picked.port) ? (boardState().serial ?? lastBoardSerial()) : undefined;
    if (picked.port && board) {
        await rememberBluetoothLink(board, picked.port);
        await vscode.workspace.getConfiguration('evn').update('port', board, vscode.ConfigurationTarget.Global);
        vscode.window.showInformationMessage(
            `EVN: ${picked.port.device} is the wireless link of ${boardName(board) ?? `the board ${board}`}: `
            + 'it is used whenever the board is not on USB, and the cable takes over again when it is in.');
        await refreshStatus();
        return;
    }
    await vscode.workspace.getConfiguration('evn').update('port', picked.value ?? '', vscode.ConfigurationTarget.Global);
    await refreshStatus();
}

/* ---- the wireless link ------------------------------------------------------------------- */

/**
 * "Use the Bluetooth COM port for the board": the Bluetooth ports only, so the user does not have
 * to tell a board's USB port from a module's link in the full picker. It pairs the port with the
 * board, and it changes evn.port only when that setting is a device name (a serial number already
 * means "this board, wherever it is").
 */
async function useBluetoothPort(): Promise<void> {
    const py = await requirePython();
    const st = boardState();
    const board = st.serial ?? lastBoardSerial();
    if (!board) {
        vscode.window.showWarningMessage(
            'EVN: connect the board over USB once first. The wireless link is remembered per board, '
            + 'and a Bluetooth port carries no serial number of its own.');
        return;
    }
    const who = boardName(board) ?? `the board ${board}`;
    interface Item extends vscode.QuickPickItem { port?: BoardPort; refresh?: boolean; forget?: boolean; }
    const fill = async (): Promise<Item[]> => {
        const bt = pickablePorts(await listPorts(py)).filter(isBluetoothPort);
        const link = bluetoothLinkFor(board);
        const isLinked = (p: BoardPort) => !!link
            && ((!!link.address && link.address === p.address) || link.device.toLowerCase() === p.device.toLowerCase());
        const items: Item[] = bt.map((p) => ({
            label: `$(broadcast) ${p.device}`,
            description: isLinked(p) ? `the wireless link of ${who}` : '',
            detail: portDetail(p),
            port: p,
        }));
        if (!items.length) {
            items.push({ label: '$(warning) No Bluetooth COM port', detail: 'Pair the module in Windows first (the link button on the serial row).' });
        }
        if (link) { items.push({ label: `$(trash) Forget the wireless link (${linkLabel(link)})`, forget: true }); }
        items.push({ label: '$(refresh) Refresh the list', refresh: true });
        return items;
    };

    const qp = vscode.window.createQuickPick<Item>();
    qp.title = `The wireless link of ${who}`;
    qp.placeholder = 'Which "Standard Serial over Bluetooth link (COMxx)" reaches this board?';
    qp.ignoreFocusOut = true;
    qp.matchOnDetail = true;
    let picked: Item | undefined;
    const done = new Promise<void>((resolve) => {
        qp.onDidHide(() => { qp.dispose(); resolve(); });
        qp.onDidAccept(() => {
            const item = qp.activeItems[0];
            if (!item) { return; }
            if (item.refresh) { void (async () => { qp.busy = true; qp.items = await fill(); qp.busy = false; })(); return; }
            if (!item.port && !item.forget) { return; }
            picked = item;
            qp.hide();
        });
    });
    qp.show();
    qp.busy = true;
    qp.items = await fill();
    qp.busy = false;
    await done;
    if (!picked) { return; }

    if (picked.forget) {
        await forgetBluetoothLink(board);
        vscode.window.showInformationMessage(`EVN: ${who} has no wireless link any more; it is reached over USB only.`);
        return;
    }
    await rememberBluetoothLink(board, picked.port as BoardPort);
    // a device name in the setting would pin the console to that one COM port: make it the board
    const cfg = configuredPort();
    if (cfg && looksLikeDevice(cfg)) {
        await vscode.workspace.getConfiguration('evn').update('port', board, vscode.ConfigurationTarget.Global);
    }
    vscode.window.showInformationMessage(
        `EVN: ${(picked.port as BoardPort).device} is the wireless link of ${who}: it is used whenever the board is not on USB.`);
    await refreshStatus();
}

/**
 * "Switch the board to Bluetooth now": try the failover with the cable still in. Everything the
 * board does over the air (the console, the telemetry rate, the Board view) then behaves exactly
 * as it will when the cable comes out, which is the only way to test it at a desk. USB comes back
 * with the other button, when the module stops being listed, when three console failures over the
 * air lock the link, or at the next start of VS Code (the choice is not persisted).
 */
async function preferWireless(): Promise<void> {
    const board = boardState().serial ?? lastBoardSerial();
    const link = bluetoothLinkFor(board);
    if (!board || !link) {
        vscode.window.showWarningMessage(
            'EVN: pick the module\'s COM port first (the plug button on the Bluetooth row).');
        return;
    }
    const py = await requirePython();
    const port = linkPort(await listPorts(py), board);
    if (!port) {
        vscode.window.showWarningMessage(`EVN: ${link.device} is not listed: is the module paired and powered?`);
        return;
    }
    setWirelessPreferred(true);
    await refreshStatus();       // the console follows the board state, so it moves with this
    const who = boardName(board) ?? `the board ${board}`;
    vscode.window.showInformationMessage(
        `EVN: ${who} is on its wireless link ${port.device}; USB is ignored until you press Back to USB (or restart VS Code).`);
}

/** "Switch the board back to USB": the standing rule (USB wherever the cable is in) applies again. */
async function preferUsb(): Promise<void> {
    if (!wirelessPreferredFlag) {
        vscode.window.showInformationMessage('EVN: the board already uses USB whenever the cable is in.');
        return;
    }
    setWirelessPreferred(false);
    await refreshStatus();
    vscode.window.showInformationMessage(
        'EVN: back to USB. The wireless link takes over by itself again whenever the board is not on the wire.');
}

/* ---- naming a board --------------------------------------------------------------------- */

/** Ask for a name for one board and store it. Returns false when the user cancelled. */
async function promptForName(p: BoardPort): Promise<boolean> {
    const serial = portSerial(p);
    if (!serial) {
        vscode.window.showWarningMessage(`EVN: the port ${p.device} reports no USB serial number, so there is nothing to remember a name by.`);
        return false;
    }
    const current = boardName(serial) ?? '';
    const short = serial.length > 4 ? `${serial.slice(0, 4)}…` : serial;
    const name = await vscode.window.showInputBox({
        title: 'Name this board',
        prompt: `Name for the board on ${p.device} (serial ${short}). Leave empty to clear the name.`,
        value: current,
        placeHolder: "Kenneth's robot",
        ignoreFocusOut: true,
        validateInput: (v) => (v.length > 40 ? 'Keep the name under 40 characters' : undefined),
    });
    if (name === undefined) { return false; }
    await setBoardName(serial, name);
    vscode.window.setStatusBarMessage(name.trim() ? `$(tag) EVN: ${p.device} is now "${name.trim()}"` : `$(tag) EVN: the name of ${p.device} was cleared`, 4000);
    return true;
}

async function nameBoard(): Promise<void> {
    const py = await requirePython();
    const boards = (await listPorts(py)).filter((p) => isEvnPort(p) && portSerial(p));
    if (!boards.length) {
        const c = await vscode.window.showWarningMessage('EVN: no board with a USB serial number is connected, so there is nothing to name yet.', 'Choose port');
        if (c === 'Choose port') { await selectPort(); }
        return;
    }
    let target = boards[0];
    if (boards.length > 1) {
        // more than one board on USB: say which one is being named
        const pick = await vscode.window.showQuickPick(boards.map((p) => ({
            label: `$(circuit-board) ${p.device}${boardName(portSerial(p)) ? ` — ${boardName(portSerial(p))}` : ''}`,
            description: `serial ${portSerial(p)}`,
            detail: describePort(p),
            port: p,
        })), { placeHolder: 'Which board do you want to name?' });
        if (!pick) { return; }
        target = pick.port;
    }
    await promptForName(target);
    await refreshStatus();
}

async function requirePython(): Promise<PyCmd> {
    const py = await findPython();
    if (py) { return py; }
    if (!host().hasPython) {
        vscode.window.showWarningMessage(
            'EVN: this browser cannot reach a serial port (Web Serial needs Chrome, Edge or Opera, over https or on localhost).');
        throw new Error('this browser has no Web Serial');
    }
    const choice = await vscode.window.showWarningMessage(
        'EVN: mpremote (the Python tool used to talk to the board) was not found.',
        'Install mpremote', 'Set Python path');
    if (choice === 'Install mpremote') { await installMpremote(); }
    else if (choice === 'Set Python path') { await vscode.commands.executeCommand('workbench.action.openSettings', 'evn.pythonPath'); }
    throw new Error('mpremote is not available');
}

async function requirePort(): Promise<{ py: PyCmd; port: string }> {
    const py = await requirePython();
    await refreshStatus();
    if (!selectedPort) {
        // A board in UF2 mode has no COM port: flashing is the way out, so it is offered first.
        const c = lastBoardState.bootsel
            ? await vscode.window.showWarningMessage(
                `EVN: the board is in BOOTSEL (UF2) mode — it is the drive ${lastBoardState.bootsel} and has no COM port until the firmware is flashed.`,
                'Flash firmware', 'Choose port')
            : await vscode.window.showWarningMessage('EVN: no board found on USB. Is it plugged in and running the MicroPython firmware?', 'Choose port', 'Flash firmware');
        if (c === 'Choose port') { await selectPort(); }
        if (c === 'Flash firmware') { await flashFirmware(); }
        if (!selectedPort) { throw new Error('no board port selected'); }
    }
    return { py, port: selectedPort };
}

/* ---- the one terminal that may hold the port ------------------------------------------- */

async function releasePort(): Promise<void> {
    // the live console holds the port whenever nothing else does: it steps aside first
    await pauseConsole('the port is needed');
    if (terminal) {
        log('closing the EVN terminal to free the port');
        terminal.dispose();
        terminal = undefined;
        await sleep(600);   // let the OS release the COM port
    }
}

/** Take the terminal the host just made as the one that holds the port. */
function setTerminal(t: vscode.Terminal): vscode.Terminal {
    terminal = t;
    terminal.show(true);
    terminalEmitter.fire(terminal);
    return terminal;
}

/* ---- commands -------------------------------------------------------------------------- */

async function currentPythonFile(): Promise<vscode.Uri> {
    const ed = vscode.window.activeTextEditor;
    if (!ed || ed.document.languageId !== 'python') {
        throw new Error('open a Python file first');
    }
    if (ed.document.isUntitled) {
        throw new Error('save the file first');
    }
    // an example is never saved: it runs from a scratch copy of what is on screen
    if (ed.document.uri.scheme === EXAMPLE_SCHEME) { return scratchCopy(ed.document); }
    if (ed.document.isDirty) { await ed.document.save(); }
    return ed.document.uri;
}

async function runFile(file?: vscode.Uri): Promise<void> {
    file = file ?? await currentPythonFile();
    const { py, port } = await requirePort();
    await releasePort();
    const repl = vscode.workspace.getConfiguration('evn').get<boolean>('replAfterRun', true);
    // The launcher reports what the program is doing through a small state; wipe the last run's
    // one first so the status bar never shows a stale "finished" or "error" (see runStatus.ts).
    clearRunState();
    setTerminal(host().runProgram(ctx, py, port, file, repl));
}

async function uploadMain(file?: vscode.Uri): Promise<void> {
    file = file ?? await currentPythonFile();
    const { py, port } = await requirePort();
    const choice = await vscode.window.showQuickPick([
        { label: 'Upload and run now', description: 'copies to main.py and resets the board; the program starts immediately', run: true },
        { label: 'Upload only', description: 'copies to main.py; it runs at the next power-on or reset', run: false },
    ], { placeHolder: `Upload ${path.posix.basename(file.path)} as main.py on ${port}` });
    if (!choice) { return; }
    await releasePort();
    await vscode.window.withProgress({ location: vscode.ProgressLocation.Notification, title: 'EVN: uploading main.py' }, async () => {
        await host().uploadMain(ctx, py, port, file as vscode.Uri, choice.run);
    });
    if (choice.run) {
        vscode.window.showInformationMessage(`EVN: main.py uploaded, board reset, program running. "EVN: Stop all motors" interrupts it; hold the user button while powering on to skip it.`);
    } else {
        vscode.window.showInformationMessage('EVN: main.py uploaded. It runs at the next power-on or "EVN: Reset the board".');
    }
}

async function openRepl(): Promise<void> {
    const { py, port } = await requirePort();
    await releasePort();
    setTerminal(host().openRepl(ctx, py, port));
}

async function stopMotors(): Promise<void> {
    const { py, port } = await requirePort();
    await releasePort();
    // Connecting sends Ctrl-C (interrupts a running program, motors coast) and soft-resets; stop_all() is belt and braces.
    const r = await mpremote(py, ['connect', port, 'exec', 'import evn; evn.stop_all()'], 15000);
    if (r.code !== 0) { throw new Error(`could not reach the board on ${port}: ${(r.stderr || r.stdout).trim()}`); }
    vscode.window.setStatusBarMessage('$(debug-stop) EVN: motors coasted, program interrupted', 4000);
}

async function listFiles(): Promise<void> {
    const { py, port } = await requirePort();
    await releasePort();
    const r = await mpremote(py, ['connect', port, 'ls']);
    if (r.code !== 0) { throw new Error(`could not list files: ${(r.stderr || r.stdout).trim()}`); }
    output.show(true);
}

async function removeMain(): Promise<void> {
    const { py, port } = await requirePort();
    const ok = await vscode.window.showWarningMessage(`Remove main.py from the board on ${port}?`, { modal: true }, 'Remove');
    if (ok !== 'Remove') { return; }
    await releasePort();
    const r = await mpremote(py, ['connect', port, 'rm', ':main.py']);
    if (r.code !== 0) { throw new Error(`could not remove main.py: ${(r.stderr || r.stdout).trim()}`); }
    vscode.window.showInformationMessage('EVN: main.py removed; nothing runs at power-on now.');
}

async function resetBoard(): Promise<void> {
    const { py, port } = await requirePort();
    await releasePort();
    await mpremote(py, ['connect', port, 'exec', '--no-follow', 'import evn; evn.reset()'], 15000);
    vscode.window.setStatusBarMessage('$(debug-restart) EVN: board reset', 4000);
}

async function flashFirmware(): Promise<void> {
    await host().flashFirmware(ctx, {
        selectedPort: () => selectedPort,
        refreshStatus,
        releasePort,
        boardLabel: () => boardName(lastBoardState.serial) ?? selectedPort ?? 'the board',
    });
}

async function diagnostics(): Promise<void> {
    const { py, port } = await requirePort();
    await releasePort();
    const script = [
        'import evn, os, gc, sys',
        "print('firmware', evn.version, os.uname().version, os.uname().machine)",
        "print('reset_cause', evn.reset_cause())",
        "print('core1 (ticks, period_min_us, period_max_us, exec_max_us, missed)', evn.core1_status())",
        "print('battery_mV', evn.battery.voltage(), 'cells', evn.battery.cells(), 'age_ms', evn.battery.age())",
        "print('mem_free', gc.mem_free())",
        "print('files', os.listdir('/'))",
        "print('fs', os.statvfs('/'))",
    ].join('\n');
    const r = await mpremote(py, ['connect', port, 'exec', script], 20000);
    const buildFile = vscode.Uri.joinPath(ctx.extensionUri, 'firmware', 'BUILD.txt');
    let build = '(no BUILD.txt)';
    try { build = new TextDecoder().decode(await vscode.workspace.fs.readFile(buildFile)).trim(); } catch { /* not bundled */ }
    const text = [
        '# EVN ALPHA diagnostics',
        `date: ${new Date().toISOString()}`,
        `extension: evn-alpha-micropython ${ctx.extension.packageJSON.version}`,
        `vscode: ${vscode.version} on ${host().label} (${vscode.env.appHost})`,
        `transport: ${py.cmd} ${py.args.join(' ')}`,
        `port: ${port}`,
        '',
        '## bundled firmware', build,
        '',
        '## board', (r.stdout || '').trim(), (r.stderr || '').trim(),
        r.code !== 0 ? `(mpremote exit code ${r.code})` : '',
        '',
        'Paste this into your bug report together with the program that misbehaved and what the motors did.',
    ].join('\n');
    const doc = await vscode.workspace.openTextDocument({ content: text, language: 'markdown' });
    await vscode.window.showTextDocument(doc);
}

async function installMpremote(): Promise<void> {
    await host().installMpremote();
    if (!host().hasPython) { return; }
    // Re-check after a while so the status bar recovers without a reload.
    setTimeout(async () => {
        forgetPython();
        await refreshStatus();
        if (!refreshTimer) { refreshTimer = setInterval(() => { void refreshStatus(); }, POLL_MS); }
    }, 30000);
}

async function openDoc(name: string): Promise<void> {
    const uri = vscode.Uri.joinPath(ctx.extensionUri, 'docs', name);
    await vscode.commands.executeCommand('markdown.showPreview', uri);
}

/* ---- project scaffold ------------------------------------------------------------------ */

async function newProject(): Promise<void> {
    const picked = await vscode.window.showOpenDialog({ canSelectFolders: true, canSelectFiles: false, canSelectMany: false, openLabel: 'Create EVN project here' });
    if (!picked || !picked.length) { return; }
    const root = picked[0];
    await scaffoldPythonSupport(ctx, root);
    await copyDirNoOverwrite(vscode.Uri.joinPath(ctx.extensionUri, 'examples'), vscode.Uri.joinPath(root, 'examples'));
    const mainPy = vscode.Uri.joinPath(root, 'main.py');
    if (!await exists(mainPy)) {
        const first = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(ctx.extensionUri, 'examples', '01_first_moves.py'));
        await vscode.workspace.fs.writeFile(mainPy, first);
    }
    const readme = vscode.Uri.joinPath(root, 'README.md');
    if (!await exists(readme)) {
        await vscode.workspace.fs.writeFile(readme, new TextEncoder().encode([
            '# EVN ALPHA project',
            '',
            '1. Plug the board in. The status bar shows `EVN: COMx`.',
            '2. Open `main.py` (or anything in `examples/`) and press **Ctrl+F5** (EVN: Run current file on the board).',
            '3. **Ctrl+Shift+F5** (EVN: Stop all motors) interrupts the program and coasts every motor.',
            '4. "EVN: Upload current file as main.py" makes a program start at power-on.',
            '5. Prefer blocks? Open `examples/blocks/first_moves.evnblocks` (or "EVN: New blocks program") and press **Run on board**.',
            '',
            '`typings/` holds the autocomplete stubs for `evn` (Pylance picks them up automatically); `examples/blocks/` holds the block-editor examples.',
            'Command palette: type `EVN:` for everything else (REPL, flash firmware, diagnostics, API reference).',
            '',
        ].join('\n')));
    }
    const where = root.scheme === 'file' ? root.fsPath : root.toString();
    const open = await vscode.window.showInformationMessage(`EVN project created in ${where}.`, 'Open folder', 'Open in new window');
    if (open === 'Open folder') { await vscode.commands.executeCommand('vscode.openFolder', root, { forceNewWindow: false }); }
    if (open === 'Open in new window') { await vscode.commands.executeCommand('vscode.openFolder', root, { forceNewWindow: true }); }
}
