/* The user's projects folder: where the sidebar's "My projects" programs live.
 *
 * On the desktop that is "EVN Projects" under Documents (or under the home folder when there is no
 * Documents), overridable with the evn.projectsFolder setting, created at activation and given
 * Pylance support (typings/ with the evn stubs, .vscode/settings.json) so that opening it as the
 * workspace gives autocomplete for `import evn`.
 *
 * In the browser it is a folder of its own under the scheme `evn-projects`, kept in that browser's
 * IndexedDB. Everything above this file works on the Uri and does not care which it is.
 */
import * as vscode from 'vscode';
import { host } from './platform/host';

export const PROJECTS_FOLDER_NAME = 'EVN Projects';

/** The configured or default projects folder (it may not exist yet). */
export function projectsFolder(): vscode.Uri {
    return host().projectsFolder();
}

/** Create the projects folder if missing and make sure it has autocomplete support. */
export function ensureProjectsFolder(ctx: vscode.ExtensionContext): Promise<vscode.Uri> {
    return host().ensureProjectsFolder(ctx);
}

/** Give a folder Pylance support for `evn`: stubs in typings/, .vscode/settings.json, the project marker. */
export function scaffoldPythonSupport(ctx: vscode.ExtensionContext, root: vscode.Uri): Promise<void> {
    return host().scaffoldPythonSupport(ctx, root);
}

/** Copy a folder of the extension's own into a target folder, never overwriting a user's file. */
export async function copyDirNoOverwrite(src: vscode.Uri, dst: vscode.Uri): Promise<void> {
    await vscode.workspace.fs.createDirectory(dst);
    let entries: [string, vscode.FileType][];
    try { entries = await vscode.workspace.fs.readDirectory(src); } catch { return; }
    for (const [name, type] of entries) {
        const s = vscode.Uri.joinPath(src, name);
        const d = vscode.Uri.joinPath(dst, name);
        if (type === vscode.FileType.Directory) {
            await copyDirNoOverwrite(s, d);
        } else {
            if (await exists(d)) { continue; }
            await vscode.workspace.fs.writeFile(d, await vscode.workspace.fs.readFile(s));
        }
    }
}

export async function exists(uri: vscode.Uri): Promise<boolean> {
    try { await vscode.workspace.fs.stat(uri); return true; } catch { return false; }
}

/** Validation message for a program name the user typed (for showInputBox), undefined when it is fine. */
export function validateProjectName(name: string): string | undefined {
    const n = name.trim();
    if (!n) { return 'Type a name'; }
    // eslint-disable-next-line no-control-regex
    if (/[<>:"/\\|?*\x00-\x1f]/.test(n)) { return 'A name cannot contain < > : " / \\ | ? *'; }
    if (/^(con|prn|aux|nul|com\d|lpt\d)$/i.test(n.replace(/\.[^.]*$/, ''))) { return 'That name is reserved by Windows'; }
    if (n.endsWith('.') || n.endsWith(' ')) { return 'A name cannot end with a dot or a space'; }
    return undefined;
}
