/* The "Examples" tree and the evn-example: file system that keeps the bundled examples from being
 * overwritten (a save becomes a new program in the projects folder).
 *
 * The examples are served from the extension's examples/ folder under the evn-example: scheme, so a
 * tab is labelled with the file name and the document is editable: only the save is redirected.
 * Running an example never saves it either: the text goes to a scratch copy the host provides.
 *
 * The extension's own files are read through vscode.workspace.fs from context.extensionUri, so the
 * same code serves them from a folder on disk (desktop) and from the extension's files as the
 * browser's extension host sees them.
 */
import * as vscode from 'vscode';
import * as path from './platform/paths';
import { host } from './platform/host';
import { log, sleep } from './util';
import { BlocksEditorProvider, BLOCKS_EDITOR_ID, BLOCKS_EXT } from './blocksEditor';
import { ensureProjectsFolder, exists, validateProjectName } from './projectsFolder';

export const EXAMPLE_SCHEME = 'evn-example';

const EXAMPLE_TOOLTIP = 'Example: edits are saved as a new program in your projects folder';
const SAVE_PROMPT = 'Examples cannot be overwritten. Save your changes as a new program in your projects folder:';

export interface ExamplesDeps {
    runFile(file: vscode.Uri): Promise<void>;
    blocks: BlocksEditorProvider;
}

/* ---- scratch copies (running an example must never save it) ---------------------------- */

/** A writable place for `name` outside the examples: the host says where. */
export function scratchFile(name: string): vscode.Uri {
    return host().scratchFile(name);
}

/** Write a document's current text (dirty or not) to the scratch folder and return that uri. */
export async function scratchCopy(doc: vscode.TextDocument): Promise<vscode.Uri> {
    const out = scratchFile(path.posix.basename(doc.uri.path));
    await vscode.workspace.fs.writeFile(out, new TextEncoder().encode(doc.getText()));
    log(`example: scratch copy ${out.toString()}`);
    return out;
}

/* ---- the examples folder ---------------------------------------------------------------- */

let root: vscode.Uri;          // the extension's examples/ folder

/** Only .py and .evnblocks are part of an example set; the generated *.evnblocks.py are not. */
function visible(name: string): boolean {
    if (name.endsWith(BLOCKS_EXT)) { return true; }
    return name.endsWith('.py') && !name.endsWith(BLOCKS_EXT + '.py');
}

function exampleUri(rel: string): vscode.Uri {
    return vscode.Uri.from({ scheme: EXAMPLE_SCHEME, path: '/' + rel.split('\\').join('/') });
}

/** The real file behind an evn-example: uri; refuses anything that escapes the examples folder. */
function realUri(uri: vscode.Uri): vscode.Uri {
    const rel = uri.path.replace(/^\/+/, '').replace(/\/+$/, '');
    if (!rel) { return root; }                       // "evn-example:/" is the examples folder itself
    if (rel.split('/').some((p) => p === '..' || p === '.')) { throw vscode.FileSystemError.NoPermissions(uri); }
    return vscode.Uri.joinPath(root, ...rel.split('/'));
}

/*
 * The listing comes out of examples/index.json, which scripts/build.js writes.
 *
 * A browser cannot list a folder: in VS Code for the Web the extension's own files are served over
 * http, where readFile and stat work and readDirectory does not. So the listing is written down at
 * build time and both hosts read the same file.
 */
let index: Promise<string[]> | undefined;

function exampleIndex(): Promise<string[]> {
    if (index) { return index; }
    index = (async () => {
        try {
            const raw = await readText(vscode.Uri.joinPath(root, 'index.json'));
            const doc = JSON.parse(raw) as { files?: unknown };
            const files = Array.isArray(doc.files) ? doc.files.filter((f): f is string => typeof f === 'string') : [];
            if (files.length) { return files; }
        } catch (e) { log(`examples: no index.json (${e}); listing the folder instead`); }
        // the folder itself, where it can be listed (the desktop, and running from sources)
        const out: string[] = [];
        const walk = async (sub: string): Promise<void> => {
            const dir = sub ? vscode.Uri.joinPath(root, ...sub.split('/')) : root;
            let entries: [string, vscode.FileType][];
            try { entries = await vscode.workspace.fs.readDirectory(dir); } catch { return; }
            for (const [name, type] of entries) {
                const rel = sub ? `${sub}/${name}` : name;
                if (type === vscode.FileType.Directory) { await walk(rel); }
                else if (visible(name)) { out.push(rel); }
            }
        };
        await walk('');
        return out.sort((a, b) => a.localeCompare(b));
    })();
    return index;
}

/** The example file names directly inside `rel` ('' = the examples root). */
async function listing(rel: string): Promise<string[]> {
    const all = await exampleIndex();
    const prefix = rel ? rel.replace(/\/+$/, '') + '/' : '';
    return all
        .filter((f) => f.startsWith(prefix) && !f.slice(prefix.length).includes('/'))
        .map((f) => f.slice(prefix.length))
        .sort((a, b) => a.localeCompare(b));
}

/** The sub-folders directly inside `rel`. */
async function subFolders(rel: string): Promise<string[]> {
    const all = await exampleIndex();
    const prefix = rel ? rel.replace(/\/+$/, '') + '/' : '';
    const out = new Set<string>();
    for (const f of all) {
        if (!f.startsWith(prefix)) { continue; }
        const tail = f.slice(prefix.length);
        const i = tail.indexOf('/');
        if (i > 0) { out.add(tail.slice(0, i)); }
    }
    return [...out].sort();
}

async function readText(uri: vscode.Uri): Promise<string> {
    return new TextDecoder().decode(await vscode.workspace.fs.readFile(uri));
}

/** What the tree says about an example: the headline of its docstring and the hardware it needs. */
interface ExampleMeta {
    /** the first docstring / comment line */
    headline?: string;
    /** the `Needs:` line of the docstring (Python) or the `needs` key of the file (blocks) */
    needs?: string;
}

/** The headline of an example: its docstring or first comment line, trimmed for the tree. */
function headline(text: string): string | undefined {
    for (const raw of text.split(/\r?\n/, 20)) {
        const line = raw.trim();
        if (!line) { continue; }
        const m = /^(?:"""|''')\s*(.+)$/.exec(line) ?? /^#\s*(.+)$/.exec(line);
        if (!m) { return undefined; }           // code on the first line: nothing worth showing
        const s = m[1].replace(/("""|''')\s*$/, '').trim();
        if (!s) { return undefined; }
        return s.length > 60 ? s.slice(0, 57).trimEnd() + '...' : s;
    }
    return undefined;
}

/** The hardware line of a Python example: the last line of its docstring, `Needs: ...`. */
function needsLine(text: string): string | undefined {
    for (const raw of text.split(/\r?\n/, 40)) {
        const m = /^\s*Needs:\s*(.+?)\s*$/.exec(raw);
        if (m) {
            const s = m[1].replace(/("""|''')\s*$/, '').trim();
            if (s) { return s; }
        }
    }
    return undefined;
}

/** Headline and hardware line of an example (`.py` or `.evnblocks`). */
async function exampleMeta(file: vscode.Uri): Promise<ExampleMeta> {
    let text: string;
    try { text = await readText(file); } catch { return {}; }
    if (file.path.endsWith(BLOCKS_EXT)) {
        try {
            const doc = JSON.parse(text) as { needs?: unknown };
            return { needs: typeof doc.needs === 'string' && doc.needs.trim() ? doc.needs.trim() : undefined };
        } catch { return {}; }
    }
    return { headline: headline(text), needs: needsLine(text) };
}

const DESCRIPTION_MAX = 70;     // beyond this the tree truncates anyway: the needs line moves to the tooltip

/** The grey text next to the file name: the headline, and the needs line too while both are short. */
function describe(meta: ExampleMeta): string | undefined {
    const needs = meta.needs ? `Needs: ${meta.needs}` : undefined;
    if (meta.headline && needs) {
        const both = `${meta.headline} — ${needs}`;
        return both.length <= DESCRIPTION_MAX ? both : meta.headline;
    }
    if (meta.headline) { return meta.headline; }
    return needs && needs.length <= DESCRIPTION_MAX ? needs : undefined;
}

function escapeMd(s: string): string { return s.replace(/[\\`*_{}[\]()#+\-.!|<>]/g, '\\$&'); }

/** The hover: the headline in bold, what the example needs on the bench, and what a save does. */
function exampleTooltip(meta: ExampleMeta): vscode.MarkdownString {
    const md = new vscode.MarkdownString();
    if (meta.headline) { md.appendMarkdown(`**${escapeMd(meta.headline)}**\n\n`); }
    if (meta.needs) { md.appendMarkdown(`Needs: ${escapeMd(meta.needs)}\n\n`); }
    md.appendMarkdown(`_${escapeMd(EXAMPLE_TOOLTIP)}_`);
    return md;
}

/* ---- the tree --------------------------------------------------------------------------- */

class ExamplesTree implements vscode.TreeDataProvider<vscode.TreeItem> {
    getTreeItem(item: vscode.TreeItem): vscode.TreeItem { return item; }

    async getChildren(item?: vscode.TreeItem): Promise<vscode.TreeItem[]> {
        if (!item) {
            const names = await listing('');
            const items = await Promise.all(names.map((n) => fileItem(n, n)));
            if ((await listing('blocks')).length) { items.push(blocksFolderItem()); }
            return items;
        }
        if (item.contextValue === 'evnExamplesFolder') {
            const names = await listing('blocks');
            return Promise.all(names.map((n) => fileItem(n, 'blocks/' + n)));
        }
        return [];
    }
}

function blocksFolderItem(): vscode.TreeItem {
    const item = new vscode.TreeItem('Blocks', vscode.TreeItemCollapsibleState.Collapsed);
    item.contextValue = 'evnExamplesFolder';
    item.iconPath = vscode.ThemeIcon.Folder;
    item.description = 'block programs';
    item.tooltip = 'Block examples: open one, change it, and save it as a program of your own';
    return item;
}

async function fileItem(name: string, rel: string): Promise<vscode.TreeItem> {
    const uri = exampleUri(rel);
    const blocks = name.endsWith(BLOCKS_EXT);
    const item = new vscode.TreeItem(name, vscode.TreeItemCollapsibleState.None);
    item.resourceUri = uri;
    item.contextValue = blocks ? 'evnExampleBlocks' : 'evnExampleFile';
    const meta = await exampleMeta(vscode.Uri.joinPath(root, ...rel.split('/')));
    item.tooltip = exampleTooltip(meta);
    item.description = describe(meta);
    item.command = blocks
        ? { command: 'vscode.openWith', title: 'Open the blocks example', arguments: [uri, BLOCKS_EDITOR_ID] }
        : { command: 'vscode.open', title: 'Open the example', arguments: [uri] };
    return item;
}

/* ---- the evn-example: file system --------------------------------------------------------- */

class ExampleFs implements vscode.FileSystemProvider {
    private readonly changed = new vscode.EventEmitter<vscode.FileChangeEvent[]>();
    readonly onDidChangeFile = this.changed.event;    // the bundled examples never change

    watch(): vscode.Disposable { return new vscode.Disposable(() => { /* nothing to watch */ }); }

    async stat(uri: vscode.Uri): Promise<vscode.FileStat> {
        const rel = uri.path.replace(/^\/+/, '').replace(/\/+$/, '');
        // a folder of the index: a browser cannot stat one of the extension's folders either
        if (!rel || (await subFolders(path.posix.dirname(rel) === '.' ? '' : path.posix.dirname(rel))).includes(path.posix.basename(rel))) {
            return { type: vscode.FileType.Directory, ctime: 0, mtime: 0, size: 0 };
        }
        const file = realUri(uri);
        if (!visible(path.posix.basename(file.path))) { throw vscode.FileSystemError.FileNotFound(uri); }
        let s: vscode.FileStat;
        try { s = await vscode.workspace.fs.stat(file); } catch { throw vscode.FileSystemError.FileNotFound(uri); }
        return s;
    }

    async readDirectory(uri: vscode.Uri): Promise<[string, vscode.FileType][]> {
        const rel = uri.path.replace(/^\/+/, '').replace(/\/+$/, '');
        const files = await listing(rel);
        const folders = await subFolders(rel);
        if (!files.length && !folders.length) { throw vscode.FileSystemError.FileNotFound(uri); }
        return [
            ...folders.map((n): [string, vscode.FileType] => [n, vscode.FileType.Directory]),
            ...files.map((n): [string, vscode.FileType] => [n, vscode.FileType.File]),
        ];
    }

    async readFile(uri: vscode.Uri): Promise<Uint8Array> {
        const file = realUri(uri);
        if (!visible(path.posix.basename(file.path))) { throw vscode.FileSystemError.FileNotFound(uri); }
        try { return await vscode.workspace.fs.readFile(file); } catch { throw vscode.FileSystemError.FileNotFound(uri); }
    }

    /* The whole point: a save of an example becomes a new program in the projects folder. */
    async writeFile(uri: vscode.Uri, content: Uint8Array): Promise<void> {
        const target = await askNewProgram(uri);
        if (!target) {
            // VS Code reports the failed save and the document stays dirty, which is what we want
            throw vscode.FileSystemError.NoPermissions('Examples are read-only: save your changes as a new program instead');
        }
        await vscode.workspace.fs.writeFile(target, content);
        log(`example: ${uri.toString()} saved as ${target.toString()}`);
        await openProgram(target);
        vscode.window.showInformationMessage(`EVN: Saved as ${path.posix.basename(target.path)} in your projects folder`);
        // the example's own tab goes once this save has resolved (a dirty tab would ask to be saved)
        setTimeout(() => { void closeTab(uri); }, 0);
    }

    createDirectory(uri: vscode.Uri): void { throw vscode.FileSystemError.NoPermissions(uri); }
    delete(uri: vscode.Uri): void { throw vscode.FileSystemError.NoPermissions(uri); }
    rename(_old: vscode.Uri, target: vscode.Uri): void { throw vscode.FileSystemError.NoPermissions(target); }
}

/* ---- saving an example as a program of the user's own ------------------------------------ */

/** Ask for a name and return the free uri in the projects folder to write, or undefined when cancelled. */
async function askNewProgram(uri: vscode.Uri): Promise<vscode.Uri | undefined> {
    const ext = uri.path.endsWith(BLOCKS_EXT) ? BLOCKS_EXT : path.posix.extname(uri.path);
    const stem = path.posix.basename(uri.path, ext);
    let value = 'my_' + stem.replace(/^\d+[_-]?/, '');
    for (;;) {
        const name = await vscode.window.showInputBox({
            title: 'Save as a new program',
            prompt: SAVE_PROMPT,
            value,
            validateInput: (v) => validateProjectName(v),
            ignoreFocusOut: true,
        });
        if (name === undefined) { return undefined; }
        value = name.trim().replace(new RegExp(escapeRe(ext) + '$', 'i'), '');
        const target = vscode.Uri.joinPath(await ensureProjectsFolder(ctx), value + ext);
        if (!await exists(target)) { return target; }
        vscode.window.showWarningMessage(`EVN: ${value + ext} already exists in your projects folder. Choose another name.`);
    }
}

function escapeRe(s: string): string { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/** Open a program of the user's own in the editor it belongs in. */
async function openProgram(uri: vscode.Uri): Promise<void> {
    if (uri.path.endsWith(BLOCKS_EXT)) {
        await vscode.commands.executeCommand('vscode.openWith', uri, BLOCKS_EDITOR_ID, { preview: false });
    } else {
        await vscode.commands.executeCommand('vscode.open', uri, { preview: false });
    }
}

/** Close the tab (text or blocks editor) that holds an example. */
async function closeTab(uri: vscode.Uri): Promise<void> {
    const key = uri.toString();
    for (const group of vscode.window.tabGroups.all) {
        for (const tab of group.tabs) {
            const input = tab.input as { uri?: vscode.Uri } | undefined;
            if (input?.uri?.toString() === key) {
                try { await vscode.window.tabGroups.close(tab, true); }
                catch (e) { log(`example: could not close ${key}: ${e}`); }
            }
        }
    }
}

/* ---- commands ----------------------------------------------------------------------------- */

/** The example a tree item (or a uri) points at. */
function itemUri(item: unknown): vscode.Uri {
    if (item instanceof vscode.Uri) { return item; }
    const uri = (item as vscode.TreeItem | undefined)?.resourceUri;
    if (!uri) { throw new Error('choose an example in the Examples view first'); }
    return uri;
}

/** The text of an example as it is right now: the open document's if there is one, else the file's. */
async function currentText(uri: vscode.Uri): Promise<string> {
    const key = uri.toString();
    const open = vscode.workspace.textDocuments.find((d) => d.uri.toString() === key);
    if (open) { return open.getText(); }
    return readText(realUri(uri));
}

async function runExample(item: unknown): Promise<void> {
    const uri = itemUri(item);
    if (!uri.path.endsWith(BLOCKS_EXT)) {
        const file = scratchFile(path.posix.basename(uri.path));
        await vscode.workspace.fs.writeFile(file, new TextEncoder().encode(await currentText(uri)));
        log(`example: running ${file.toString()}`);
        await deps.runFile(file);
        return;
    }
    // blocks: the webview is what generates the program, so open it and wait for the first code
    await vscode.commands.executeCommand('vscode.openWith', uri, BLOCKS_EDITOR_ID, { preview: false });
    const key = uri.toString();
    const deadline = Date.now() + 4000;
    for (;;) {
        const session = deps.blocks.activeSession();
        if (session?.document.uri.toString() === key) {
            const python = await deps.blocks.currentPython();
            if (python && python.trim()) { break; }
        }
        if (Date.now() > deadline) { throw new Error('the blocks example did not finish loading; press Run on board in the editor'); }
        await sleep(150);
    }
    await deps.blocks.run();
}

async function saveExampleAsProject(item: unknown): Promise<void> {
    const uri = itemUri(item);
    const target = await askNewProgram(uri);
    if (!target) { return; }
    await vscode.workspace.fs.writeFile(target, new TextEncoder().encode(await currentText(uri)));
    log(`example: copied ${uri.toString()} to ${target.toString()}`);
    await openProgram(target);
    vscode.window.showInformationMessage(`EVN: Saved as ${path.posix.basename(target.path)} in your projects folder`);
}

/* ---- registration --------------------------------------------------------------------------- */

let ctx: vscode.ExtensionContext;
let deps: ExamplesDeps;

export function registerExamples(context: vscode.ExtensionContext, d: ExamplesDeps): void {
    ctx = context;
    deps = d;
    root = vscode.Uri.joinPath(context.extensionUri, 'examples');

    context.subscriptions.push(vscode.workspace.registerFileSystemProvider(EXAMPLE_SCHEME, new ExampleFs(), { isCaseSensitive: false }));
    context.subscriptions.push(vscode.window.registerTreeDataProvider('evn.examples', new ExamplesTree()));

    const reg = (id: string, fn: (...a: any[]) => any) =>
        context.subscriptions.push(vscode.commands.registerCommand(id, async (...a: any[]) => {
            try { await fn(...a); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));
    reg('evn.runExample', runExample);
    reg('evn.saveExampleAsProject', saveExampleAsProject);
}
