/* The live console helper, in TypeScript over a serial byte stream.
 *
 * This is scripts/evn_console.py's `Helper` class ported line for line: the same probe, the same
 * raw-REPL entry and soft reset, the same agent (generated into agent.ts from the very same Python
 * source), the same heartbeat, the same busy / gone / error states, the same Bluetooth patience.
 * It emits exactly the JSON events of docs/CONSOLE_PROTOCOL.md and takes exactly its commands, so
 * console.ts, boardView.ts, consoleView.ts and batteryStatus.ts do not know which host they have.
 *
 * Timing is the helper's, not the browser's: heartbeat 1/rate, rate 4 over USB and
 * evn.console.bluetoothRate over Bluetooth, the agent's own period a hair shorter (_TELE_MS).
 * Nothing extra runs on the board and nothing extra is polled.
 */
import type { HelperProcess } from '../host';
import { Bytes, ByteStream, StreamGone, Wire, clean, concat, decode, delay, indexOf } from './stream';
import { RawRepl, ReplError } from './rawrepl';
import { agentSource } from './agent';

export const RATE = 4;                 // telemetry updates a second; Bluetooth lowers it
const TELE_MARGIN_MS = 10;             // the agent's period is a hair under the heartbeat
const PROBE_MS = 300;                  // how long to wait for a prompt when deciding idle vs busy
const PROBE_BT_MS = 1000;              // the same over Bluetooth, where a round trip takes much longer
const BT_PATIENCE = 3.0;               // every connect timeout is that many times longer over Bluetooth

export interface HelperOptions {
    /** the device name the extension knows this port by (COM7, "Web Serial") */
    port: string;
    /** the port is an EVN Bluetooth module carrying the REPL: longer timeouts, no USB serial number */
    bluetooth: boolean;
    /** the USB serial number, when the platform knows one (never over Web Serial) */
    serialNumber: string;
    /** telemetry updates a second */
    rate: number;
}

type State = 'connecting' | 'live' | 'busy' | 'error' | 'gone';

/** The helper's exit reason, mapped onto the child process's exit code the extension expects. */
const EXIT_OK = 0;
const EXIT_FAIL = 1;

export class SerialHelper implements HelperProcess {
    private wire: Wire | undefined;
    private repl: RawRepl | undefined;
    private state: State = 'connecting';
    private buf: Bytes = new Uint8Array(0);
    private queue: string[] = [];
    private lineCb: ((line: string) => void) | undefined;
    private errCb: ((line: string) => void) | undefined;
    private exitCbs: ((code: number | null) => void)[] = [];
    private done = false;
    private quitting = false;
    private expectReset = false;
    private resetAt = 0;
    private lastTick = 0;
    private silent = false;
    private readonly tick: number;
    private readonly teleMs: number;

    constructor(private readonly open: () => Promise<ByteStream>, private readonly opts: HelperOptions) {
        // the heartbeat is what wakes the agent's blocking readline, so it sets the telemetry rate;
        // the agent's own period is a hair shorter so a tick is never one heartbeat late
        this.tick = 1000 / opts.rate;
        this.teleMs = Math.round(1000 / opts.rate) - TELE_MARGIN_MS;
    }

    /* ---- the HelperProcess face ------------------------------------------------------ */

    get exited(): boolean { return this.done; }
    onLine(cb: (line: string) => void): void { this.lineCb = cb; }
    onStderr(cb: (line: string) => void): void { this.errCb = cb; }
    onExit(cb: (code: number | null) => void): void {
        if (this.done) { cb(EXIT_OK); return; }
        this.exitCbs.push(cb);
    }
    write(line: string): void {
        if (this.done) { throw new Error('the live console is not connected'); }
        this.queue.push(line.trim());
    }
    kill(): void { this.quitting = true; void this.shutdown(EXIT_FAIL, true); }

    /* ---- what the helper prints ------------------------------------------------------ */

    private emit(obj: unknown): void { this.lineCb?.(JSON.stringify(obj)); }
    private log(msg: string): void { this.errCb?.(msg); }

    private transport(): 'usb' | 'bluetooth' { return this.opts.bluetooth ? 'bluetooth' : 'usb'; }

    /** Why the board did not give a prompt back (three readings over the air; see the protocol doc). */
    private busyDetail(): string {
        if (this.opts.bluetooth && this.silent) {
            return 'no answer over Bluetooth: the board is running its program, its REPL is not on'
                + ' this module, or another console already has the board';
        }
        return 'the board is running a program of its own';
    }

    /* ---- the session ------------------------------------------------------------------ */

    /** Start the session; it runs until quit, a fatal error or the port going away. */
    start(): void { void this.loop(); }

    private async loop(): Promise<void> {
        this.emit({ ev: 'state', state: 'connecting' });
        try {
            const stream = await this.open();
            this.wire = new Wire(stream, this.opts.bluetooth ? BT_PATIENCE : 1.0);
            this.repl = new RawRepl(this.wire);
            if (this.opts.bluetooth) { this.log(`${this.opts.port} is a Bluetooth link: longer timeouts, no USB serial number`); }
            const where = await this.probe();
            if (where === 'busy') {
                this.state = 'busy';
                this.emit({ ev: 'state', state: 'busy', detail: this.busyDetail() });
            } else {
                await this.connect(where === 'raw');
            }
            await this.pumpForever();
        } catch (e: any) {
            if (this.done) { return; }
            if (e instanceof StreamGone) {
                this.state = 'gone';
                this.emit({ ev: 'state', state: 'gone', detail: this.opts.bluetooth ? 'the Bluetooth link dropped' : 'the board is no longer on USB' });
                await this.shutdown(EXIT_FAIL, true);
                return;
            }
            this.emit({ ev: 'state', state: 'error', detail: String(e?.message ?? e) });
            await this.shutdown(EXIT_FAIL, true);
        }
    }

    /** Idle or busy? Write \r\n and look at what comes back (never interrupts anything). */
    private async probe(): Promise<'idle' | 'raw' | 'busy'> {
        const wire = this.wire as Wire;
        wire.resetInput();
        await wire.write('\r\n');
        const end = Date.now() + (this.opts.bluetooth ? PROBE_BT_MS : PROBE_MS);
        let data: Bytes = new Uint8Array(0);
        while (Date.now() < end) {
            await wire.pump(Math.min(50, Math.max(5, end - Date.now())));
            data = concat(data, wire.takeAll());
        }
        const text = decode(data);
        this.silent = !text.trim();
        if (text.includes('>>> ')) { return 'idle'; }
        if (text.trim().endsWith('>')) { return 'raw'; }
        return 'busy';                                 // a program of the board's own is running
    }

    /** Ctrl-C, raw REPL, soft reset (main.py skipped), upload the agent, relay. */
    private async connect(fromRaw = false): Promise<void> {
        const repl = this.repl as RawRepl;
        if (this.state !== 'connecting') { this.emit({ ev: 'state', state: 'connecting' }); }
        this.state = 'connecting';
        this.buf = new Uint8Array(0);
        await repl.enter(!fromRaw);
        await repl.softReset();
        const source = agentSource(this.opts.serialNumber, this.transport(), this.opts.port, this.opts.rate, this.teleMs);
        const blob = new TextEncoder().encode(source);
        const rest = await repl.paste(blob);
        this.buf = rest;                               // the agent's first bytes may already be here
        this.state = 'live';
        this.lastTick = Date.now();
        this.log(`agent running on ${this.opts.port} (${blob.length} bytes)`);
        this.flushLines();                             // the live event may already be in there
    }

    /* ---- the main loop ---------------------------------------------------------------- */

    private async pumpForever(): Promise<void> {
        const wire = this.wire as Wire;
        for (;;) {
            if (this.done) { return; }
            // commands first, exactly as the Python helper drains its queue every turn
            while (this.queue.length) {
                const item = this.queue.shift() as string;
                await this.handleCommand(item);
                if (this.done) { return; }
            }
            const now = Date.now();
            if (this.state === 'live' && now - this.lastTick >= this.tick) {
                this.lastTick = now;
                await wire.write('\n');                // heartbeat: wakes the agent's readline
            }
            if (this.expectReset && now - this.resetAt > 3000) {
                this.state = 'gone';
                this.emit({ ev: 'state', state: 'gone', detail: 'the board was reset' });
                await this.shutdown(EXIT_OK, true);
                return;
            }
            await wire.pump(20);
            const data = wire.takeAll();
            if (data.length) { await this.feed(data); }
        }
    }

    /* ---- board -> extension ------------------------------------------------------------ */

    private async feed(data: Bytes): Promise<void> {
        this.buf = concat(this.buf, data);
        if (this.state === 'live' && indexOf(this.buf, new Uint8Array([0x04])) >= 0) {
            // only the raw REPL prints 0x04: the agent has stopped and the board is back at the
            // prompt. Collect the traceback that follows it, relay it, and end the session.
            const wire = this.wire as Wire;
            const end = Date.now() + 300;
            while (Date.now() < end) {
                await wire.pump(50);
                this.buf = concat(this.buf, wire.takeAll());
            }
            this.state = 'error';
            const rest = decode(this.buf).split('').join('\n');
            this.buf = new Uint8Array(0);
            let last = '';
            for (const part of rest.split('\n')) {
                const line = clean(part).trim();
                if (line && line.replace(/[>. ]/g, '')) {
                    this.emit({ ev: 'out', text: line });
                    last = line;
                }
            }
            this.emit({ ev: 'state', state: 'error', detail: 'the board agent stopped' + (last ? ': ' + last : '') });
            await this.shutdown(EXIT_FAIL, true);
            return;
        }
        this.flushLines();
        if (this.state === 'busy') {
            const text = decode(this.buf);
            if (text.endsWith('>>> ')) {               // the board's program ended: connect now
                const head = clean(text.slice(0, -4)).trim();
                this.buf = new Uint8Array(0);
                if (head) { this.emit({ ev: 'out', text: head }); }
                await this.connect();
            } else if (this.buf.length > 2048) {       // a program that prints without newlines
                this.buf = new Uint8Array(0);
                const all = clean(text);
                if (all.trim()) { this.emit({ ev: 'out', text: all }); }
            }
        }
    }

    private flushLines(): void {
        for (;;) {
            const i = indexOf(this.buf, new Uint8Array([0x0a]));
            if (i < 0) { return; }
            const line = this.buf.slice(0, i);
            this.buf = this.buf.slice(i + 1);
            this.handleLine(line);
        }
    }

    private handleLine(raw: Bytes): void {
        const text = clean(raw).trim();
        if (!text) { return; }
        if (this.state !== 'live' && !text.replace(/[>. ]/g, '')) { return; }  // a bare REPL prompt
        if (this.state === 'live' && text[0] === '{') {
            let obj: unknown;
            try { obj = JSON.parse(text); } catch { obj = undefined; }
            if (obj && typeof obj === 'object') {
                this.lineCb?.(text);                   // the agent's JSON goes out verbatim
                return;
            }
        }
        this.emit({ ev: 'out', text });
    }

    /* ---- extension -> board ------------------------------------------------------------- */

    private async handleCommand(raw: string): Promise<void> {
        if (!raw) { return; }
        let cmd: any;
        try { cmd = JSON.parse(raw); } catch {
            this.log(`ignored a line that is not JSON: ${raw.slice(0, 200)}`);
            return;
        }
        if (!cmd || typeof cmd !== 'object') { this.log('ignored a command that is not an object'); return; }
        const name = cmd.cmd;
        if (name === 'quit') { await this.shutdown(EXIT_OK, false); return; }
        if (name === 'stop') {
            if (this.state === 'busy') {
                this.log('stop: interrupting the board\'s program');
                await (this.wire as Wire).write('\r\x03');
                await delay(200);
                this.buf = new Uint8Array(0);
                await this.connect();
            } else {
                this.log('stop ignored: the board is not running a program of its own');
            }
            return;
        }
        if (this.state === 'busy') { this.refuse(name, cmd); return; }
        if (this.state !== 'live') { this.log(`${name} ignored: the link is ${this.state}`); return; }
        if (name === 'reset') {
            this.expectReset = true;
            this.resetAt = Date.now();
        }
        await (this.wire as Wire).write(JSON.stringify(cmd) + '\n');
    }

    private refuse(name: string, cmd: any): void {
        const why = 'the board is running a program of its own; send stop first';
        if (name === 'exec') { this.emit({ ev: 'result', id: cmd.id, ok: false, err: why }); }
        else if (name === 'call') { this.emit({ ev: 'done', cmd: 'call', id: cmd.id, ok: false, err: why }); }
        else if (name === 'watch') { this.emit({ ev: 'done', cmd: 'watch', port: cmd.port, ok: false, err: why }); }
        else if (name === 'rm' || name === 'configure') { this.emit({ ev: 'done', cmd: name, ok: false, err: why }); }
        else { this.log(`${name} ignored while busy`); }
    }

    /* ---- lifecycle ---------------------------------------------------------------------- */

    /** Stop the agent, hand the friendly REPL back, close the port. Always under a second. */
    private async leave(): Promise<void> {
        const wire = this.wire;
        if (!wire) { return; }
        try {
            if (this.state !== 'busy' && !wire.gone) {  // never write to the board's own program
                await wire.write('\r\x03');             // stop the agent
                await delay(150);
                wire.resetInput();
                await wire.write('\r\x02');             // back to the friendly REPL for the next session
                await delay(150);
            }
        } catch (e: any) {
            this.log(`while closing: ${e?.message ?? e}`);
        }
        try { await wire.close(); } catch (e: any) { this.log(`while closing: ${e?.message ?? e}`); }
        this.wire = undefined;
    }

    private async shutdown(code: number, hard: boolean): Promise<void> {
        if (this.done) { return; }
        this.done = true;
        if (hard) {
            try { await this.wire?.close(); } catch { /* already gone */ }
            this.wire = undefined;
        } else {
            await this.leave();
        }
        const cbs = this.exitCbs;
        this.exitCbs = [];
        for (const cb of cbs) { cb(code); }
    }
}

export { ReplError };
