/* Web Serial as the extension's port listing.
 *
 * A browser never enumerates serial ports by itself: it hands out the ones the user picked in the
 * browser's own chooser, and `navigator.serial.getPorts()` returns those (and only those) for ever
 * after. VS Code for the Web opens that chooser from the workbench, not from the extension host, so
 * "Select board port" is the `workbench.experimental.requestSerialPort` command followed by a fresh
 * getPorts().
 *
 * What a granted port tells us is `usbVendorId` / `usbProductId` and nothing else: no device name,
 * no USB serial number. So the listing here makes a stable name per granted port in the order the
 * browser returns them ("Web Serial 1"), and the board's identity comes from the link itself.
 * A Bluetooth link is a plain serial port to the browser, so it appears as one of these too.
 */
import * as vscode from 'vscode';
import { BoardPort } from '../host';
import { ByteStream, WebSerialStream } from './stream';
import { log } from '../../util';

export const EVN_VENDOR_ID = 0x2e8a;
export const EVN_PRODUCT_ID = 0x000a;

/** The device names this host makes up; extension.ts recognises them as device names, not serials. */
export const WEB_DEVICE_PREFIX = 'Web Serial ';

interface Granted {
    device: string;
    port: any;              // a Web Serial SerialPort
    vidpid: string;
}

let granted: Granted[] = [];

/** Does this browser have Web Serial at all (Chrome, Edge and Opera do; Firefox and Safari do not)? */
export function webSerialAvailable(): boolean {
    return typeof navigator !== 'undefined' && !!(navigator as any).serial;
}

export const NO_WEB_SERIAL =
    'This browser has no Web Serial, so the board cannot be reached from here. '
    + 'Chrome, Edge and Opera have it (over https or on localhost); everything that does not need '
    + 'the board - the examples, the blocks editor, your programs - works in any browser.';

function serialApi(): any {
    const s = (navigator as any)?.serial;
    if (!s) { throw new Error(NO_WEB_SERIAL); }
    return s;
}

function vidpidOf(port: any): string {
    const info = typeof port.getInfo === 'function' ? port.getInfo() : {};
    const v = typeof info.usbVendorId === 'number' ? info.usbVendorId : 0;
    const p = typeof info.usbProductId === 'number' ? info.usbProductId : 0;
    return `${v.toString(16).padStart(4, '0')}:${p.toString(16).padStart(4, '0')}`;
}

/** The ports the user has granted, as the extension's BoardPort list. */
export async function listGrantedPorts(): Promise<BoardPort[]> {
    if (!webSerialAvailable()) { return []; }
    let ports: any[];
    try { ports = await serialApi().getPorts(); } catch (e) { log(`web serial: getPorts failed: ${e}`); return []; }
    // keep the names the previous listing gave out, so "Web Serial 1" stays the same port
    const next: Granted[] = [];
    for (const p of ports) {
        const known = granted.find((g) => g.port === p);
        next.push(known ?? { device: '', port: p, vidpid: vidpidOf(p) });
    }
    let n = 0;
    for (const g of next) {
        n++;
        if (!g.device) { g.device = WEB_DEVICE_PREFIX + n; }
    }
    // a port the user revoked in the browser drops out of getPorts(); renumber nothing else
    granted = next;
    return granted.map((g): BoardPort => ({
        device: g.device,
        serial: '',                  // Web Serial never gives one out
        vidpid: g.vidpid,
        description: describe(g.vidpid),
        hwid: '',
    }));
}

function describe(vidpid: string): string {
    if (vidpid === '2e8a:000a') { return 'EVN ALPHA over Web Serial'; }
    if (vidpid === '0000:0000') { return 'Serial port granted in this browser (a Bluetooth link looks like this)'; }
    return `Serial port ${vidpid} granted in this browser`;
}

/** The SerialPort object behind a device name from the listing above. */
function find(device: string): any | undefined {
    return granted.find((g) => g.device.toLowerCase() === device.toLowerCase())?.port;
}

/** Is this port one the user granted in this session? */
export function isGranted(device: string): boolean { return find(device) !== undefined; }

/**
 * Open a granted port as a byte stream.
 *
 * Only one thing may hold the port at a time; the extension already guarantees that (the live
 * console steps aside before a program or the REPL opens), so a second open of the same port is a
 * bug and says so rather than silently sharing.
 */
export async function openPort(device: string, baud = 115200): Promise<ByteStream> {
    const port = find(device);
    if (!port) { throw new Error(`${device} is not a port this browser has granted; use "EVN: Select board port".`); }
    const stream = new WebSerialStream(port, baud);
    await stream.open();
    return stream;
}

/* ---- asking the browser for a port -------------------------------------------------------- */

/*
 * VS Code 1.82 added `workbench.experimental.requestSerialPort` for web extensions (with
 * requestUsbDevice and requestHidDevice): the workbench calls navigator.serial.requestPort() in the
 * window, where the user gesture is, and the granted port then shows up in the extension host's
 * getPorts(). The command takes the SerialPortRequestOptions object. Older or stripped builds may
 * not have it, so a direct requestPort() is tried as well and the failure is explained.
 */
const REQUEST_COMMAND = 'workbench.experimental.requestSerialPort';

export interface PortRequest {
    label: string;
    detail: string;
    filters?: { usbVendorId: number; usbProductId?: number }[];
}

export const PORT_REQUESTS: PortRequest[] = [
    {
        label: '$(circuit-board) An EVN ALPHA on USB',
        detail: 'Only boards are offered (USB 2E8A:000A)',
        filters: [{ usbVendorId: EVN_VENDOR_ID, usbProductId: EVN_PRODUCT_ID }],
    },
    {
        label: '$(plug) Any serial port',
        detail: 'Use this for a Bluetooth link: the browser shows it as a plain serial port',
    },
];

/** Ask the browser for a port; returns the new listing entry, or undefined when nothing was picked. */
export async function requestPort(request: PortRequest): Promise<BoardPort | undefined> {
    if (!webSerialAvailable()) { throw new Error(NO_WEB_SERIAL); }
    const before = (await listGrantedPorts()).map((p) => p.device);
    // the command takes one SerialPortRequestOptions object; `filters` is optional
    const options = request.filters ? { filters: request.filters } : {};
    let asked = false;
    try {
        // it answers with the granted port's { usbVendorId, usbProductId }, or undefined on cancel
        const granted = await vscode.commands.executeCommand<{ usbVendorId?: number; usbProductId?: number } | undefined>(
            REQUEST_COMMAND, options);
        asked = true;
        if (granted === undefined) { log('web serial: the chooser was dismissed'); return undefined; }
        log(`web serial: the chooser granted ${JSON.stringify(granted)}`);
    } catch (e) {
        log(`web serial: ${REQUEST_COMMAND} failed (${e}); trying navigator.serial.requestPort`);
    }
    if (!asked) {
        try { await serialApi().requestPort(options); }
        catch (e: any) {
            // "No port selected by the user" is a cancel, not a failure
            if (/no port selected|cancel/i.test(String(e?.message ?? e))) { return undefined; }
            throw new Error(`the browser did not offer a serial port: ${e?.message ?? e}`);
        }
    }
    const after = await listGrantedPorts();
    const fresh = after.find((p) => !before.includes(p.device));
    if (fresh) { log(`web serial: granted ${fresh.device} (${fresh.vidpid})`); }
    return fresh ?? after.find((p) => p.vidpid === '2e8a:000a') ?? after[after.length - 1];
}

/** Forget the cached names (a window reload starts over anyway). */
export function resetPorts(): void { granted = []; }
