/* The handful of `path` functions the shared code uses, written out so that no shared module has
 * to import Node's `path` (the web bundle has no Node builtins at all).
 *
 * Both separators are understood, so the same code works on a Windows path and on the `/` paths of
 * a vscode.Uri. `posix` is the `/`-only variant for uri.path, exactly as `path.posix` is.
 */

const SEP_RE = /[\\/]/;

function isSep(ch: string): boolean { return ch === '/' || ch === '\\'; }

function strip(p: string): string {
    // trailing separators do not belong to the name ("a/b/" is the name "b"), but a bare root stays
    let end = p.length;
    while (end > 1 && isSep(p[end - 1])) { end--; }
    return p.slice(0, end);
}

export function basename(p: string, ext?: string): string {
    const s = strip(p);
    let i = s.length - 1;
    while (i >= 0 && !isSep(s[i])) { i--; }
    const name = s.slice(i + 1);
    if (ext && name !== ext && name.toLowerCase().endsWith(ext.toLowerCase())) {
        return name.slice(0, name.length - ext.length);
    }
    return name;
}

export function dirname(p: string): string {
    const s = strip(p);
    let i = s.length - 1;
    while (i >= 0 && !isSep(s[i])) { i--; }
    if (i < 0) { return '.'; }
    if (i === 0) { return s[0]; }
    // "C:\x" -> "C:\", so a drive root keeps its separator
    if (i === 2 && /^[a-zA-Z]:$/.test(s.slice(0, 2))) { return s.slice(0, 3); }
    return s.slice(0, i);
}

export function extname(p: string): string {
    const name = basename(p);
    const i = name.lastIndexOf('.');
    return i <= 0 ? '' : name.slice(i);
}

/** Join with `/`; empty parts are skipped and doubled separators collapse. */
export function join(...parts: string[]): string {
    const out: string[] = [];
    for (const raw of parts) {
        if (!raw) { continue; }
        out.push(out.length ? raw.replace(/^[\\/]+/, '') : raw);
    }
    const joined = out.join('/');
    return joined ? joined.replace(/([^:])[\\/]{2,}/g, '$1/') : '.';
}

export function isAbsolute(p: string): boolean {
    return /^([a-zA-Z]:[\\/]|[\\/])/.test(p);
}

/** The parts of a path, without the empty ones. */
export function split(p: string): string[] {
    return p.split(SEP_RE).filter((s) => s.length > 0);
}

/** `/`-only variants, for vscode.Uri.path. */
export const posix = {
    basename(p: string, ext?: string): string {
        const s = p.replace(/\/+$/, '');
        const name = s.slice(s.lastIndexOf('/') + 1);
        if (ext && name !== ext && name.toLowerCase().endsWith(ext.toLowerCase())) {
            return name.slice(0, name.length - ext.length);
        }
        return name;
    },
    dirname(p: string): string {
        const s = p.replace(/\/+$/, '');
        const i = s.lastIndexOf('/');
        if (i < 0) { return '.'; }
        return i === 0 ? '/' : s.slice(0, i);
    },
    extname(p: string): string {
        const name = posix.basename(p);
        const i = name.lastIndexOf('.');
        return i <= 0 ? '' : name.slice(i);
    },
    join(...parts: string[]): string {
        const out = parts.filter(Boolean).map((s, i) => (i ? s.replace(/^\/+/, '') : s));
        return out.join('/').replace(/([^:])\/{2,}/g, '$1/');
    },
};
