/* The browser host: everything the extension needs from a machine, done with what a browser has.
 *
 *   Python with mpremote  ->  Web Serial and the raw REPL, spoken here in TypeScript
 *   a port listing        ->  the ports the user granted in this browser (ports.ts)
 *   Documents/EVN Projects->  an IndexedDB folder under the scheme evn-projects (projectsFs.ts)
 *   a shell terminal      ->  a vscode.Pseudoterminal that drives the port (terminal.ts)
 *   a temp file           ->  an in-memory value (the run state) or an evn-projects file
 *   an RPI-RP2 drive      ->  nothing: a browser cannot write to a mass-storage device, so
 *                             "Flash firmware" explains and offers the download instead
 */
import * as vscode from 'vscode';
import { BoardPort, FlashDeps, HelperProcess, Host, PyCmd, RunResult, RunState } from '../host';
import { log } from '../../util';
import * as paths from '../paths';
import { listGrantedPorts, openPort, requestPort, webSerialAvailable, NO_WEB_SERIAL, PORT_REQUESTS, WEB_DEVICE_PREFIX } from './ports';
import { PROJECTS_ROOT, registerProjectsFileSystem } from './projectsFs';
import { boardExec, boardExecNoFollow, boardLs, boardRm, boardUpload, createBoardTerminal, clearWebRunState, webRunState } from './terminal';
import { SerialHelper } from './serialHelper';

/** The marker "interpreter": there is no Python here, but the shared code asks for one. */
const WEB_PY: PyCmd = { cmd: 'web-serial', args: [] };

const FIRMWARE_URL = 'https://evn.coresg.tech/firmware/EVN_ALPHA_MicroPython.uf2';

const NO_PYTHON_HERE =
    'In the browser the extension talks to the board over Web Serial, so there is no Python and no '
    + 'mpremote to install. Everything that needs them on the desktop is done here directly over the port.';

export class WebHost implements Host {
    readonly web = true;
    readonly label = 'browser (Web Serial)';
    readonly hasFileExplorer = false;
    readonly hasPython = false;

    private scratch: vscode.Uri | undefined;

    async activate(ctx: vscode.ExtensionContext): Promise<void> {
        registerProjectsFileSystem(ctx);
        void vscode.commands.executeCommand('setContext', 'evn.web', true);
        void vscode.commands.executeCommand('setContext', 'evn.webSerial', webSerialAvailable());
        if (!webSerialAvailable()) { log(`web: ${NO_WEB_SERIAL}`); }
    }

    /* ---- the toolchain ----------------------------------------------------------------- */

    /*
     * "Is there a way to reach a board?" - which in a browser means two separate things: does this
     * browser have Web Serial at all, and has the user let this page use a port yet. Both answers
     * matter to the user, and the second is the ordinary first-run state, so a browser without a
     * granted port answers "no" here: the status bar and the Board view then say what to do.
     */
    async findPython(): Promise<PyCmd | undefined> {
        if (!webSerialAvailable()) { return undefined; }
        return (await listGrantedPorts()).length ? WEB_PY : undefined;
    }
    pythonWithoutMpremote(): PyCmd | undefined { return undefined; }
    forgetPython(): void { /* nothing is cached */ }

    noToolchainStatus(): { text: string; tooltip: string } {
        if (!webSerialAvailable()) {
            return {
                text: '$(circuit-board) EVN: no Web Serial',
                tooltip: 'EVN ALPHA: this browser cannot reach a serial port.\n'
                    + 'Chrome, Edge and Opera can, over https or on localhost.\n'
                    + 'Everything that does not need the board works here anyway.',
            };
        }
        return {
            text: '$(circuit-board) EVN: choose the board port',
            tooltip: 'EVN ALPHA: no serial port has been granted to this page yet.\n'
                + 'Click to choose the board; the browser asks which device this page may use\n'
                + 'and remembers it. Pick "Any serial port" for a Bluetooth link.',
        };
    }

    listPorts(_py: PyCmd): Promise<BoardPort[]> { return listGrantedPorts(); }

    async mpremote(_py: PyCmd, args: string[], timeoutMs = 30000): Promise<RunResult> {
        const seconds = Math.max(5, Math.round(timeoutMs / 1000));
        const ok = (stdout: string): RunResult => ({ code: 0, stdout, stderr: '', timedOut: false });
        const fail = (stderr: string): RunResult => ({ code: 1, stdout: '', stderr, timedOut: false });
        if (args[0] !== 'connect' || args.length < 3) { return fail(`the browser host does not know "mpremote ${args.join(' ')}"`); }
        const port = args[1];
        const verb = args[2];
        log(`web serial: ${args.join(' ')}`);
        try {
            if (verb === 'exec') {
                if (args[3] === '--no-follow') {
                    await boardExecNoFollow(port, args.slice(4).join(' '));
                    return ok('');
                }
                const r = await boardExec(port, args.slice(3).join(' '), seconds);
                return r.err ? { code: 1, stdout: r.out, stderr: r.err, timedOut: false } : ok(r.out);
            }
            if (verb === 'ls') { return ok(await boardLs(port)); }
            if (verb === 'rm') { await boardRm(port, args[3] ?? ''); return ok(''); }
            return fail(`the browser host does not know "mpremote ${args.join(' ')}"`);
        } catch (e: any) {
            return fail(String(e?.message ?? e));
        }
    }

    runProgram(_ctx: vscode.ExtensionContext, _py: PyCmd, port: string, file: vscode.Uri, repl: boolean): vscode.Terminal {
        return createBoardTerminal({ kind: 'run', port, file, repl });
    }

    openRepl(_ctx: vscode.ExtensionContext, _py: PyCmd, port: string): vscode.Terminal {
        return createBoardTerminal({ kind: 'repl', port });
    }

    async uploadMain(_ctx: vscode.ExtensionContext, _py: PyCmd, port: string, file: vscode.Uri, run: boolean): Promise<void> {
        await boardUpload(port, file, 'main.py');
        if (run) { await boardExecNoFollow(port, 'import evn; evn.reset()'); }
    }

    async startHelper(_ctx: vscode.ExtensionContext, _py: PyCmd, port: string, rate?: number): Promise<HelperProcess> {
        const bluetooth = !port.startsWith(WEB_DEVICE_PREFIX)
            ? false
            : (await listGrantedPorts()).find((p) => p.device === port)?.vidpid === '0000:0000';
        const helper = new SerialHelper(() => openPort(port), {
            port,
            // a Bluetooth link is a plain serial port to the browser: no USB ids at all is the sign
            bluetooth,
            serialNumber: '',       // Web Serial never hands one out
            rate: rate ?? 4,
        });
        helper.start();
        return helper;
    }

    async installMpremote(): Promise<void> {
        await vscode.window.showInformationMessage(`EVN: ${NO_PYTHON_HERE}`);
    }

    /** "Select board port" in the browser: ask for an EVN ALPHA, or for any serial port. */
    async requestPort(): Promise<BoardPort | undefined> {
        return this.pickPort();
    }

    private async pickPort(): Promise<BoardPort | undefined> {
        if (!webSerialAvailable()) {
            await vscode.window.showWarningMessage(`EVN: ${NO_WEB_SERIAL}`);
            return undefined;
        }
        const pick = await vscode.window.showQuickPick(
            PORT_REQUESTS.map((r) => ({ label: r.label, detail: r.detail, request: r })),
            { placeHolder: 'Which port may this page use? The browser asks you to choose the device next.', matchOnDetail: true });
        if (!pick) { return undefined; }
        return requestPort(pick.request);
    }

    /* ---- firmware -------------------------------------------------------------------- */

    findBootselDrive(): string | undefined { return undefined; }

    async flashFirmware(_ctx: vscode.ExtensionContext, deps: FlashDeps): Promise<void> {
        const port = deps.selectedPort();
        const actions = ['Download the firmware'];
        if (port) { actions.unshift('Put the board in BOOTSEL mode'); }
        const choice = await vscode.window.showInformationMessage(
            'EVN: a browser cannot write to the RPI-RP2 drive, so flashing is a two-step job here: '
            + 'put the board in BOOTSEL mode, download the firmware, and drag the .uf2 onto the RPI-RP2 drive '
            + 'that appears. The desktop extension does it in one click.',
            { modal: true }, ...actions);
        if (choice === 'Put the board in BOOTSEL mode') {
            await deps.releasePort();
            await boardExecNoFollow(port as string, 'import evn; evn.bootloader()');
            vscode.window.showInformationMessage(
                'EVN: the board is in BOOTSEL mode; the drive RPI-RP2 should appear. '
                + 'Drag EVN_ALPHA_MicroPython.uf2 onto it, and the board comes back by itself.');
            await vscode.env.openExternal(vscode.Uri.parse(FIRMWARE_URL));
            return;
        }
        if (choice === 'Download the firmware') {
            await vscode.env.openExternal(vscode.Uri.parse(FIRMWARE_URL));
        }
    }

    /* ---- the projects folder ---------------------------------------------------------- */

    projectsFolder(): vscode.Uri { return PROJECTS_ROOT; }

    async ensureProjectsFolder(ctx: vscode.ExtensionContext): Promise<vscode.Uri> {
        await vscode.workspace.fs.createDirectory(PROJECTS_ROOT);
        await this.scaffoldPythonSupport(ctx, PROJECTS_ROOT);
        return PROJECTS_ROOT;
    }

    async scaffoldPythonSupport(ctx: vscode.ExtensionContext, root: vscode.Uri): Promise<void> {
        // Pylance does not run in the browser, so there is nothing to point at stubs; the marker
        // still goes in, because it is what "this is an EVN project" means to the extension.
        const marker = vscode.Uri.joinPath(root, 'evn_project.json');
        try { await vscode.workspace.fs.stat(marker); return; } catch { /* make it */ }
        const text = JSON.stringify({
            created: new Date().toISOString(),
            extension: ctx.extension.packageJSON.version,
            note: 'Marker for the EVN ALPHA MicroPython extension. main.py is what "Upload as main.py" puts on the board.',
        }, null, 4);
        await vscode.workspace.fs.writeFile(marker, new TextEncoder().encode(text));
    }

    /** Somewhere writable for a copy that must not be saved: a hidden folder of the projects store. */
    scratchFile(name: string): vscode.Uri {
        if (!this.scratch) { this.scratch = vscode.Uri.joinPath(PROJECTS_ROOT, '.scratch'); }
        return vscode.Uri.joinPath(this.scratch, paths.posix.basename(name));
    }

    /* ---- what the program in the terminal is doing ------------------------------------- */

    runStateRef(): string { return ''; }
    readRunState(): RunState | undefined { return webRunState(); }
    clearRunState(): void { clearWebRunState(); }
}
