/* What the editor shows while a program is running: the status bar indicator, the Stop button and
   clickable tracebacks in the terminal.

   On the desktop the program runs in a real VS Code terminal whose shell is scripts/evn_run.py, and
   that stays so on purpose: mpremote's REPL reads the console directly and does not work through a
   pipe on Windows, so the extension cannot capture the output and re-print it. Instead the launcher
   tells us what is happening through a small JSON file in the temp folder, which we poll while the
   terminal is open:

       {"phase": "running"|"finished"|"error"|"interrupted"|"repl"|"closed",
        "rc": <exit code or null>, "file": <the .py that ran>, "port": "COM7", "t": <epoch seconds>}

   Every write by the launcher is atomic, so a half-written file is never read. In the browser there
   is no launcher and no temp folder: the pseudoterminal reports the very same phases in memory and
   the host hands them over here, so everything below is unchanged. */
import * as vscode from 'vscode';
import * as path from './platform/paths';
import { host, RunState } from './platform/host';
import { onDidChangeTerminal, evnTerminal, portBusy } from './extension';

export interface RunStatusDeps {
    stopMotors(): Promise<void>;
}

const TERMINAL_NAME = 'EVN ALPHA';
const POLL_MS = 500;
const CLEAR_AFTER_MS = 8000;    // how long "finished" and "stopped" stay on screen

/** The reference scripts/evn_run.py is given for its progress file (a path on the desktop). */
export function runStateFile(): string {
    return host().runStateRef();
}

/** Forget the last run, so an old "finished" or "error" is not shown for a program just started. */
export function clearRunState(): void {
    last = undefined;
    host().clearRunState();
}

function readRunState(): RunState | undefined {
    return host().readRunState();
}

let last: RunState | undefined;         // the newest state we have seen (also used by the links)

/** The name a state's `file` shows: it is a path on the desktop, a uri in the browser. */
function fileLabel(file: string): string {
    if (!file) { return 'the program'; }
    try {
        if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(file) && !/^[a-zA-Z]:[\\/]/.test(file)) {
            return path.posix.basename(vscode.Uri.parse(file).path) || file;
        }
    } catch { /* not a uri after all */ }
    return path.basename(file);
}

/** The uri of a state's `file`, whichever form it took. */
function fileUri(file: string): vscode.Uri | undefined {
    if (!file) { return undefined; }
    try {
        if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(file) && !/^[a-zA-Z]:[\\/]/.test(file)) { return vscode.Uri.parse(file); }
        return vscode.Uri.file(file);
    } catch { return undefined; }
}

export function registerRunStatus(ctx: vscode.ExtensionContext, deps: RunStatusDeps): void {
    void deps;   // stopping is the evn.stopMotors command, which the Stop button below calls

    /* ---- the two status bar items ------------------------------------------------------ */

    const runItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 48);
    runItem.command = 'evn.showProgramTerminal';
    const stopItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 47);
    stopItem.text = '$(debug-stop) Stop';
    stopItem.command = 'evn.stopMotors';
    stopItem.tooltip = 'Stop the program and coast every motor (Ctrl+Shift+F5)';
    stopItem.backgroundColor = new vscode.ThemeColor('statusBarItem.errorBackground');
    ctx.subscriptions.push(runItem, stopItem);

    let hideTimer: any;
    let pollTimer: any;
    let shownKey = '';                  // phase + timestamp of what the run item is showing
    let errored = false;                // this run ended with an error (kept while the REPL is up)

    function hideLater(ms: number): void {
        hideTimer = setTimeout(() => { runItem.hide(); hideTimer = undefined; }, ms);
    }

    function show(state: RunState): void {
        const name = fileLabel(state.file);
        runItem.backgroundColor = undefined;
        runItem.tooltip = 'click to show the program terminal';
        if (state.phase === 'running') { errored = false; }
        if (state.phase === 'error') { errored = true; }
        // the REPL opens after a failed run too: keep the error on screen, it is the news
        const phase = state.phase === 'repl' && errored ? 'error' : state.phase;
        switch (phase) {
            case 'running':
                runItem.text = `$(sync~spin) Running ${name}`;
                runItem.show();
                break;
            case 'finished':
                runItem.text = `$(check) ${name} finished`;
                runItem.show();
                hideLater(CLEAR_AFTER_MS);
                break;
            case 'error':
                runItem.text = `$(error) ${name}: error`;
                runItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
                runItem.tooltip = 'the program stopped with an error - click to show the terminal';
                runItem.show();     // stays until the terminal closes
                break;
            case 'interrupted':
                runItem.text = '$(debug-stop) stopped';
                runItem.show();
                hideLater(CLEAR_AFTER_MS);
                break;
            case 'repl':
                // the port item and the REPL button already say where the REPL is: nothing to add
                runItem.hide();
                break;
            default:                // "closed", or anything we do not know
                runItem.hide();
                break;
        }
    }

    function poll(): void {
        const state = readRunState();
        if (!state) { return; }
        const key = `${state.phase}@${state.t}`;
        if (key === shownKey) { return; }
        shownKey = key;
        last = state;
        if (hideTimer) { clearTimeout(hideTimer); hideTimer = undefined; }
        show(state);
    }

    function stopPolling(): void {
        if (pollTimer) { clearInterval(pollTimer); pollTimer = undefined; }
    }

    /* The terminal is the whole life of a run: while it exists we watch the state file and offer
       Stop; when it closes everything goes away. */
    function terminalChanged(t: vscode.Terminal | undefined): void {
        if (t || portBusy()) {
            stopItem.show();
            if (!pollTimer) { pollTimer = setInterval(poll, POLL_MS); }
            poll();
        } else {
            stopPolling();
            stopItem.hide();
            if (hideTimer) { clearTimeout(hideTimer); hideTimer = undefined; }
            runItem.hide();
            shownKey = '';
            errored = false;
        }
    }
    ctx.subscriptions.push(onDidChangeTerminal(terminalChanged));
    ctx.subscriptions.push(new vscode.Disposable(stopPolling));
    terminalChanged(evnTerminal());     // in case a terminal is already open on a window reload

    /* ---- showing the terminal again ---------------------------------------------------- */

    ctx.subscriptions.push(vscode.commands.registerCommand('evn.showProgramTerminal', () => {
        const t = evnTerminal();
        if (t) { t.show(false); } else {
            vscode.window.showInformationMessage('EVN: no program terminal is open. Run a program with Ctrl+F5.');
        }
    }));

    /* ---- clickable tracebacks ---------------------------------------------------------- */

    /* A MicroPython traceback names the file that failed. The program is fed to the board through
       the REPL, so the program itself is always called "<stdin>"; that one means the file the run
       state says we ran. Any other name (an imported module) is looked for next to it. */
    const TRACEBACK = /File "([^"]+)", line (\d+)/g;

    interface EvnLink extends vscode.TerminalLink { target: string; line: number }

    function resolve(name: string): vscode.Uri | undefined {
        const ran = last?.file || readRunState()?.file;
        if (name === '<stdin>') { return ran ? fileUri(ran) : undefined; }
        if (path.isAbsolute(name)) { return vscode.Uri.file(name); }
        const base = ran ? fileUri(ran) : undefined;
        if (!base) { return undefined; }
        return vscode.Uri.joinPath(base.with({ path: path.posix.dirname(base.path) }), name);
    }

    ctx.subscriptions.push(vscode.window.registerTerminalLinkProvider({
        provideTerminalLinks(context: vscode.TerminalLinkContext): EvnLink[] {
            if (context.terminal.name !== TERMINAL_NAME) { return []; }
            const links: EvnLink[] = [];
            TRACEBACK.lastIndex = 0;
            let m: RegExpExecArray | null;
            while ((m = TRACEBACK.exec(context.line)) !== null) {
                const target = resolve(m[1]);
                const line = parseInt(m[2], 10);
                if (!target || !line) { continue; }
                links.push({
                    startIndex: m.index,
                    length: m[0].length,
                    target: target.toString(),
                    line,
                    tooltip: `Open ${path.posix.basename(target.path)} at line ${line}`,
                });
            }
            return links;
        },
        async handleTerminalLink(link: EvnLink): Promise<void> {
            const uri = vscode.Uri.parse(link.target);
            try {
                const doc = await vscode.workspace.openTextDocument(uri);
                const at = new vscode.Range(link.line - 1, 0, link.line - 1, 0);
                await vscode.window.showTextDocument(doc, { selection: at });
            } catch {
                vscode.window.showInformationMessage(`EVN: could not open ${path.posix.basename(uri.path)}.`);
            }
        },
    }));
}
