/* Host-side helpers: the log channel, what a port is, and the thin delegations to the platform
 * host (a Python with mpremote on the desktop, Web Serial in the browser).
 *
 * Everything in here is shared by both bundles, so it imports no Node builtin: the machine-specific
 * half lives in src/platform/node and src/platform/web behind the Host interface, and the call
 * sites (extension.ts, boardView.ts, console.ts) are unchanged. */
import * as vscode from 'vscode';
import { host } from './platform/host';
import { BoardPort, PyCmd, RunResult } from './platform/host';

export type { BoardPort, PyCmd, RunResult } from './platform/host';

export const EVN_USB_VID = '2e8a';   // Raspberry Pi; the EVN ALPHA enumerates as 2e8a:000a

export const output = vscode.window.createOutputChannel('EVN ALPHA');

export function log(line: string): void {
    const t = new Date().toLocaleTimeString();
    output.appendLine(`[${t}] ${line}`);
}

/* ---- the toolchain (the platform host does the work) ------------------------------ */

export function forgetPython(): void { host().forgetPython(); }

/** The Python that has mpremote, or undefined (then `pythonWithoutMpremote()` may say which Python exists). */
export function findPython(): Promise<PyCmd | undefined> { return host().findPython(); }

export function pythonWithoutMpremote(): PyCmd | undefined { return host().pythonWithoutMpremote(); }

/** Run an mpremote command line (arguments after `mpremote`). */
export function mpremote(py: PyCmd, args: string[], timeoutMs = 30000): Promise<RunResult> {
    return host().mpremote(py, args, timeoutMs);
}

export function listPorts(py: PyCmd): Promise<BoardPort[]> { return host().listPorts(py); }

/* ---- Ports ------------------------------------------------------------------------ */

export function isEvnPort(p: BoardPort): boolean {
    return p.vidpid.startsWith(EVN_USB_VID + ':');
}

/** A port is a board only when it has a USB serial number: that is what a board is remembered by. */
export function portSerial(p: BoardPort): string | undefined {
    return p.serial ? p.serial : undefined;
}

export function isBluetoothPort(p: BoardPort): boolean {
    return /bluetooth/i.test(p.description);
}

/*
 * A Bluetooth COM port carries no USB descriptor, but on Windows its hardware id does name the
 * remote module:
 *
 *   BTHENUM\{00001101-...}_LOCALMFG&0046\9&28A1A762&0&98D341F71802_C00000000
 *                                                   ^^^^^^^^^^^^ the module's address
 *
 * The digits after `&0&` are the address of the module the port dials, which is the one thing
 * that survives Windows renumbering the port. All zeros is not a module at all: it is the
 * INCOMING port Windows makes once per adapter, which can never reach anything, so those are
 * kept out of the pickers. Linux and macOS have no such id (the hwid is then something else or
 * empty): the address is optional everywhere and the link falls back to the device name.
 */

/** The remote module's Bluetooth address in a BTHENUM hardware id, or undefined (incoming ports included). */
export function bluetoothAddressOf(hwid: string): string | undefined {
    if (!hwid || !/^BTHENUM/i.test(hwid.trim())) { return undefined; }
    const m = hwid.match(/&0&([0-9a-fA-F]{12})/);
    if (!m) { return undefined; }
    const hex = m[1].toUpperCase();
    if (/^0{12}$/.test(hex)) { return undefined; }      // the adapter's own incoming port
    return (hex.match(/../g) as string[]).join(':');
}

/** The Windows INCOMING Bluetooth port (one per adapter, address all zeros): it reaches no module. */
export function isIncomingBluetoothPort(p: BoardPort): boolean {
    if (!isBluetoothPort(p)) { return false; }
    if (!/^BTHENUM/i.test(p.hwid.trim())) { return false; }
    return /&0&0{12}/.test(p.hwid);
}

/** The line shown under a port in the picker. */
export function describePort(p: BoardPort): string {
    return p.description || (isEvnPort(p) ? 'USB serial device' : p.vidpid);
}

export function sleep(ms: number): Promise<void> {
    return new Promise((r) => setTimeout(r, ms));
}
