/* The getting-started walkthrough and the global-autocomplete offer.
 *
 * Three things live here:
 *   1. evn.openWalkthrough - opens the "Get started with the EVN ALPHA" walkthrough contributed in
 *      package.json (its steps tick themselves off from the evn.hasMpremote / evn.boardConnected
 *      context keys and from the commands the user runs).
 *   2. First run: the walkthrough opens by itself once, and only when no board is connected - a user
 *      who already has a flashed board plugged in has been here before.
 *   3. evn.enableGlobalAutocomplete plus a one-time offer of it: `import evn` completes inside the
 *      projects folder because that folder carries typings/evn.pyi, but only when it is the open
 *      workspace. This points Pylance at those stubs globally, for every Python file.
 */
import * as vscode from 'vscode';
import * as path from './platform/paths';
import { host } from './platform/host';
import { log } from './util';
import { boardState, onDidChangeBoardState } from './extension';
import { ensureProjectsFolder, exists, projectsFolder } from './projectsFolder';

const WALKTHROUGH_ID = 'evn-alpha.evn-alpha-micropython#evn.gettingStarted';
const PYLANCE_ID = 'ms-python.vscode-pylance';

/** globalState keys (versioned: a new version of the extension may ask again by bumping them). */
const KEY_FIRST_RUN = 'evn.walkthrough.shown.v1';        // boolean: the first-run decision was made
const KEY_OFFER = 'evn.autocomplete.offer.v1';           // 'done' | 'never'
const KEY_OFFER_SNOOZE = 'evn.autocomplete.offer.snoozeUntil.v1';   // ms epoch, for "Not now"

const SNOOZE_MS = 7 * 24 * 60 * 60 * 1000;      // "Not now" = ask again in a week
const FIRST_RUN_GRACE_MS = 3000;                // how long to wait for the first board-state event

const IMPORTS_EVN = /^[ \t]*(from[ \t]+evn\b|import[ \t]+evn\b)/m;

export function registerWalkthrough(ctx: vscode.ExtensionContext): void {
    const reg = (id: string, fn: () => Promise<void> | void) =>
        ctx.subscriptions.push(vscode.commands.registerCommand(id, async () => {
            try { await fn(); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));

    reg('evn.openWalkthrough', openWalkthrough);
    reg('evn.enableGlobalAutocomplete', () => enableGlobalAutocomplete(ctx, true));

    openOnFirstRun(ctx);
    hookAutocompleteOffer(ctx);
}

/* ---- the walkthrough ------------------------------------------------------------------- */

async function openWalkthrough(): Promise<void> {
    await vscode.commands.executeCommand('workbench.action.openWalkthrough', WALKTHROUGH_ID, false);
}

/** On the very first activation, open the walkthrough - unless a board is already connected. */
function openOnFirstRun(ctx: vscode.ExtensionContext): void {
    if (ctx.globalState.get<boolean>(KEY_FIRST_RUN, false)) { return; }
    let decided = false;
    let timer: NodeJS.Timeout | undefined;
    // The board state is only known after the first port listing (a second or two), so wait for the
    // first event - or give up after the grace period, which is the usual case: with no mpremote and
    // no board nothing changes, so no event is ever fired.
    const sub = onDidChangeBoardState(() => decide());
    function decide(): void {
        if (decided) { return; }
        decided = true;
        if (timer) { clearTimeout(timer); timer = undefined; }
        sub.dispose();
        void ctx.globalState.update(KEY_FIRST_RUN, true);
        if (boardState().present) {
            log('first run: a board is already connected, not opening the walkthrough');
            return;
        }
        log('first run: opening the getting-started walkthrough');
        void openWalkthrough();
    }
    timer = setTimeout(decide, FIRST_RUN_GRACE_MS);
    ctx.subscriptions.push(sub, { dispose: () => { if (timer) { clearTimeout(timer); } } });
}

/* ---- autocomplete in every Python file -------------------------------------------------- */

/** The stubs folder inside the user's projects folder (where ensureProjectsFolder puts evn.pyi). */
function stubsFolder(): string {
    const root = projectsFolder();
    return root.scheme === 'file' ? path.join(root.fsPath, 'typings') : path.posix.join(root.path, 'typings');
}

/** Two settings paths pointing at the same folder; the comparison is case-insensitive on Windows. */
function samePath(a: string, b: string): boolean {
    const norm = (p: string) => p.replace(/[\\/]+$/, '').replace(/\\/g, '/');
    const windows = /^[a-zA-Z]:[\\/]/.test(a) || /^[a-zA-Z]:[\\/]/.test(b);
    return windows ? norm(a).toLowerCase() === norm(b).toLowerCase() : norm(a) === norm(b);
}

/** True when the global settings already point Pylance at our stubs. */
function globalAutocompleteOn(): boolean {
    const typings = stubsFolder();
    const cfg = vscode.workspace.getConfiguration();
    const stub = (cfg.inspect<string>('python.analysis.stubPath')?.globalValue ?? '').trim();
    if (stub && samePath(stub, typings)) { return true; }
    const extra = cfg.inspect<string[]>('python.analysis.extraPaths')?.globalValue ?? [];
    return extra.some((p) => typeof p === 'string' && samePath(p, typings));
}

/**
 * Point Pylance at the projects folder's stubs globally.
 *
 * python.analysis.stubPath is taken when it is free (unset, empty, or the Pylance default "typings",
 * which means nothing at the global level) or already ours; a stubPath the user chose is left alone
 * and the stubs are appended to python.analysis.extraPaths instead.
 */
async function enableGlobalAutocomplete(ctx: vscode.ExtensionContext, notify: boolean): Promise<void> {
    if (host().web) {
        // Pylance is a desktop language server: there is nothing to point at stubs in a browser
        if (notify) {
            vscode.window.showInformationMessage(
                'EVN: autocomplete for evn comes from Pylance, which does not run in a browser. '
                + 'The desktop extension sets it up; here the examples and the blocks editor are the guide.');
        }
        return;
    }
    const rootUri = await ensureProjectsFolder(ctx);     // makes sure typings/evn.pyi exists
    const root = rootUri.fsPath;
    const typings = path.join(root, 'typings');
    const cfg = vscode.workspace.getConfiguration();
    const G = vscode.ConfigurationTarget.Global;

    const stub = (cfg.inspect<string>('python.analysis.stubPath')?.globalValue ?? '').trim();
    const stubFree = stub === '' || stub === 'typings' || samePath(stub, typings);
    let note = '';
    if (stubFree) {
        await cfg.update('python.analysis.stubPath', typings, G);
    } else {
        const extra = [...(cfg.inspect<string[]>('python.analysis.extraPaths')?.globalValue ?? [])];
        if (!extra.some((p) => typeof p === 'string' && samePath(p, typings))) {
            extra.push(typings);
            await cfg.update('python.analysis.extraPaths', extra, G);
        }
        note = ` Your own python.analysis.stubPath (${stub}) was left alone, so the stubs went into python.analysis.extraPaths instead.`;
    }

    const overrides = { ...(cfg.inspect<Record<string, unknown>>('python.analysis.diagnosticSeverityOverrides')?.globalValue ?? {}) };
    if (overrides['reportMissingModuleSource'] !== 'none') {
        overrides['reportMissingModuleSource'] = 'none';
        await cfg.update('python.analysis.diagnosticSeverityOverrides', overrides, G);
    }

    await ctx.globalState.update(KEY_OFFER, 'done');
    log(`global autocomplete on: ${stubFree ? 'stubPath' : 'extraPaths'} -> ${typings}`);
    if (!notify) { return; }

    const base = 'EVN: autocomplete for evn is on in every Python file. Pylance needs a moment to notice.';
    if (!vscode.extensions.getExtension(PYLANCE_ID)) {
        const c = await vscode.window.showWarningMessage(
            `${base}${note} Pylance is not installed yet, so nothing will complete until it is.`,
            'Install Pylance', 'Later');
        if (c === 'Install Pylance') {
            await vscode.commands.executeCommand('workbench.extensions.installExtension', PYLANCE_ID);
        }
        return;
    }
    vscode.window.showInformationMessage(`${base}${note}`);
}

/* ---- the one-time offer ----------------------------------------------------------------- */

const stubDirCache = new Map<string, boolean>();

async function folderHasStubs(dir: vscode.Uri): Promise<boolean> {
    const key = dir.toString();
    const hit = stubDirCache.get(key);
    if (hit !== undefined) { return hit; }
    const has = await exists(vscode.Uri.joinPath(dir, 'typings', 'evn.pyi'));
    stubDirCache.set(key, has);
    return has;
}

/** Is this file already covered by a typings/evn.pyi - in its folder, four levels up, or a workspace folder? */
async function coveredLocally(file: vscode.Uri): Promise<boolean> {
    let dir = file.with({ path: path.posix.dirname(file.path) });
    for (let i = 0; i <= 4; i++) {
        if (await folderHasStubs(dir)) { return true; }
        const up = path.posix.dirname(dir.path);
        if (up === dir.path) { break; }
        dir = dir.with({ path: up });
    }
    for (const f of vscode.workspace.workspaceFolders ?? []) {
        if (f.uri.scheme === 'file' && await folderHasStubs(f.uri)) { return true; }
    }
    return false;
}

function hookAutocompleteOffer(ctx: vscode.ExtensionContext): void {
    if (host().web) { return; }     // nothing to offer where Pylance cannot run
    const look = (doc: vscode.TextDocument | undefined) => { void maybeOffer(ctx, doc); };
    ctx.subscriptions.push(
        vscode.workspace.onDidOpenTextDocument((d) => look(d)),
        vscode.window.onDidChangeActiveTextEditor((e) => look(e?.document)),
    );
    look(vscode.window.activeTextEditor?.document);
}

let offering = false;

async function maybeOffer(ctx: vscode.ExtensionContext, doc: vscode.TextDocument | undefined): Promise<void> {
    try {
        if (offering || !doc) { return; }
        if (doc.languageId !== 'python' || doc.uri.scheme !== 'file') { return; }
        const state = ctx.globalState.get<string>(KEY_OFFER, '');
        if (state === 'done' || state === 'never') { return; }
        const snooze = ctx.globalState.get<number>(KEY_OFFER_SNOOZE, 0);
        if (snooze && Date.now() < snooze) { return; }
        if (!IMPORTS_EVN.test(doc.getText())) { return; }
        if (await coveredLocally(doc.uri)) { return; }
        if (globalAutocompleteOn()) { await ctx.globalState.update(KEY_OFFER, 'done'); return; }

        offering = true;
        const c = await vscode.window.showInformationMessage(
            'EVN: want autocomplete for evn in every Python file, not only inside a project folder?',
            'Turn it on', 'Not now', 'Never');
        if (c === 'Turn it on') {
            await enableGlobalAutocomplete(ctx, true);
        } else if (c === 'Never') {
            await ctx.globalState.update(KEY_OFFER, 'never');
        } else {
            // "Not now" and a dismissed notification: ask again in a week
            await ctx.globalState.update(KEY_OFFER_SNOOZE, Date.now() + SNOOZE_MS);
        }
    } catch (e: any) {
        log(`autocomplete offer skipped: ${e?.message ?? e}`);
    } finally {
        offering = false;
    }
}
