/* The Console view (a webview) under the Board tree in the secondary side bar: a prompt and a
 * transcript on top of the live console's exec.
 *
 * A real terminal cannot live in a side bar, and the board's REPL would want the port the live
 * console already holds, so this view is a prompt on top of that console instead: every line goes
 * through consoleRunLine(), i.e. the agent's namespace on the board, and variables persist between
 * lines exactly as they do for the "Send a command" QuickPick.
 *
 * The transcript is kept here, in the extension host, not in the webview: the view is cheap to
 * throw away (retainContextWhenHidden is off), and mirroring starts when the extension starts, so
 * a line written while the view was collapsed is still there when it comes back.
 *
 * The strip charts of the live device reads are kept the same way: the rings live here and ride
 * on the telemetry the console already receives (nothing new is asked of the board, and there is
 * no timer), and a sample is posted to the page only while the view is on screen - a hidden view
 * costs nothing and redraws its whole history from the rings when it comes back.
 */
import * as vscode from 'vscode';
import {
    consoleHistory, consoleLive, consoleRunLine, consoleStatus,
    onDidChangeConsole, onDidWriteConsoleLine, onDidReceiveTelemetry, ConsoleStatus, Telemetry,
} from './console';
import { log } from './util';

/** How many lines the transcript keeps, here and in the webview's DOM. */
const MAX_LINES = 400;
/** How many recent lines the Up/Down arrows walk. */
const MAX_HISTORY = 50;
/** How many samples one watched port keeps: a minute at four telemetry events a second. */
const MAX_SAMPLES = 240;
/** How many numbers one watched value may draw: the page has four series colours. */
const MAX_SERIES = 4;

const HINT = 'Python runs on the board. m1..m4 motors, s1..s4 servos, d5 the device on I2C port 5, evn imported.';

type LineKind = 'out' | 'cmd' | 'err' | 'state';

interface TranscriptLine {
    kind: LineKind;
    text: string;
}

/** One point of a watched port's chart: the board's own clock and the numbers it read. */
interface ChartSample {
    /** board milliseconds */
    t: number;
    values: number[];
}

/** The history of one watched port. */
interface ChartRing {
    /** the watched method, for the header (`lux`, `hsv`, `distance`) */
    m: string;
    /** the exception of the latest read, when it raised: the header goes red, the line stays */
    e?: string;
    /** oldest first, at most MAX_SAMPLES */
    samples: ChartSample[];
}

/** What a watched value contributes to a chart: one number, or up to four of them. Anything else
 *  - a dict (`hsv` reads as one), a string, a longer list - has no chart at all, which is how a
 *  reading that is not a curve stays a row and does not become a flat line. */
function seriesOf(v: any): number[] | undefined {
    if (typeof v === 'number') { return isFinite(v) ? [v] : undefined; }
    if (Array.isArray(v) && v.length >= 1 && v.length <= MAX_SERIES
        && v.every((x) => typeof x === 'number' && isFinite(x))) {
        return v.slice();
    }
    return undefined;
}

/** A line that is a Python failure: a traceback, one of its frames, or the exception line that
 *  ends it ("ValueError: ..."). `! ...` is the console service's own failure text. */
const ERROR_RE = /^(?:Traceback\b|  File |! )|^[A-Za-z_][\w.]*(?:Error|Exception|Interrupt|Exit)\b/;

/** Which class a line of the "EVN Console" channel gets. Decided here so the webview never has to
 *  parse board text. */
function classify(text: string): LineKind {
    if (text.startsWith('>>> ')) { return 'cmd'; }
    if (text.startsWith('[') && text.includes('console:')) { return 'state'; }
    if (text.startsWith('---')) { return 'state'; }
    if (ERROR_RE.test(text)) { return 'err'; }
    return 'out';
}

/** Why the prompt is disabled, in the words the Board tree uses. */
function whyNotLive(st: ConsoleStatus): string {
    switch (st.state) {
        case 'connecting': return 'connecting to the board...';
        case 'busy': return 'the board is running its own program (main.py)';
        case 'paused': return `paused: ${st.detail || 'a program is running'}`;
        case 'gone': return 'not connected: the board is no longer on USB';
        case 'error': return `not connected: ${st.detail || 'the console could not be started'}`;
        default: return `not connected: ${st.detail || 'no board on USB'}`;
    }
}

class ConsoleViewProvider implements vscode.WebviewViewProvider {
    static readonly viewId = 'evn.console';

    private view: vscode.WebviewView | undefined;
    /** the ring buffer of the last MAX_LINES lines */
    private readonly lines: TranscriptLine[] = [];
    /** the lines sent from this view, most recent first: the arrows walk these before the stored ones */
    private sent: string[] = [];
    private running = false;
    /** one ring per watched I2C port, keyed by the port number as the telemetry names it */
    private readonly rings = new Map<string, ChartRing>();

    constructor(private readonly ctx: vscode.ExtensionContext) { }

    /* ---- the transcript ------------------------------------------------------------------ */

    /** One channel line (it may itself hold newlines: a block sent to the board is echoed whole). */
    append(text: string): void {
        const parts = String(text).split(/\r?\n/);
        const first = classify(parts[0]);
        for (const [i, part] of parts.entries()) {
            // a block command echoes over several lines; its continuation lines are command text too
            const kind: LineKind = i > 0 && first === 'cmd' ? 'cmd' : classify(part);
            const line: TranscriptLine = { kind, text: part };
            this.lines.push(line);
            this.post({ type: 'line', kind: line.kind, text: line.text });
        }
        if (this.lines.length > MAX_LINES) { this.lines.splice(0, this.lines.length - MAX_LINES); }
    }

    clear(): void {
        this.lines.length = 0;
        // the charts are not transcript: clearing the text leaves the curves where they were
        this.post({ type: 'reset', lines: [], charts: this.chartsPayload() });
    }

    /* ---- the strip charts ---------------------------------------------------------------- */

    /** One telemetry event. The rings are kept whatever the view is doing (they are the history
     *  a reopened view draws from); the page hears about it only while it is on screen. */
    telemetry(t: Telemetry): void {
        const watch = t.watch ?? {};
        // a port that stopped being watched loses its chart, and the strip has to be rebuilt
        let structure = false;
        for (const port of [...this.rings.keys()]) {
            if (!(port in watch)) { this.rings.delete(port); structure = true; }
        }
        const updates: object[] = [];
        for (const [port, w] of Object.entries(watch)) {
            const values = seriesOf(w.v);
            let ring = this.rings.get(port);
            if (!ring) {
                // a port earns its chart with its first number: a read that only ever raises, or
                // one whose value is not a curve, never gets one
                if (!values) { continue; }
                ring = { m: w.m, samples: [] };
                this.rings.set(port, ring);
                structure = true;
            }
            // the row is watching something else now: the old curve means nothing
            if (ring.m !== w.m) { ring.m = w.m; ring.samples.length = 0; structure = true; }
            ring.e = w.e;
            if (values && !w.e) {
                ring.samples.push({ t: t.t, values });
                if (ring.samples.length > MAX_SAMPLES) {
                    ring.samples.splice(0, ring.samples.length - MAX_SAMPLES);
                }
            }
            updates.push({ type: 'sample', port, m: ring.m, t: t.t, values: values ?? [], e: ring.e });
        }
        if (!this.view?.visible) { return; }
        // a port came or went: one message with the whole strip, rather than a sample the page
        // would have to guess the shape of
        if (structure) { this.postCharts(); return; }
        for (const u of updates) { this.post(u); }
    }

    /** The rings as the page wants them: enough to redraw every chart from scratch. */
    private chartsPayload(): object[] {
        return [...this.rings.entries()].map(([port, r]) => ({
            port, m: r.m, e: r.e, samples: r.samples,
        }));
    }

    private postCharts(): void {
        this.post({ type: 'charts', charts: this.chartsPayload() });
    }

    /* ---- the view ------------------------------------------------------------------------ */

    resolveWebviewView(view: vscode.WebviewView): void {
        this.view = view;
        view.webview.options = {
            enableScripts: true,
            localResourceRoots: [vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'console')],
        };
        view.webview.html = this.html(view.webview);
        view.webview.onDidReceiveMessage((msg: any) => this.onMessage(msg));
        // with retainContextWhenHidden off the page reloads and asks for everything again ('ready'),
        // but a refresh here costs nothing and covers a webview that kept its context
        view.onDidChangeVisibility(() => { if (view.visible) { this.refresh(); } });
        view.onDidDispose(() => { if (this.view === view) { this.view = undefined; } });
        this.refresh();
    }

    /** Everything the page needs to draw itself from scratch. */
    private refresh(): void {
        this.post({ type: 'reset', lines: this.lines, charts: this.chartsPayload() });
        this.postState();
        this.postHistory();
        this.post({ type: 'busy', running: this.running });
    }

    postState(): void {
        const st = consoleStatus();
        const live = consoleLive();
        this.post({
            type: 'state',
            live,
            placeholder: live ? 'Python to run on the board' : whyNotLive(st),
            hint: live ? HINT : '',
        });
    }

    private postHistory(): void {
        const seen = new Set<string>();
        const items: string[] = [];
        for (const code of [...this.sent, ...consoleHistory()]) {
            if (seen.has(code)) { continue; }
            seen.add(code);
            items.push(code);
            if (items.length >= MAX_HISTORY) { break; }
        }
        this.post({ type: 'history', items });
    }

    private post(msg: object): void {
        void this.view?.webview.postMessage(msg);
    }

    /* ---- what the user does -------------------------------------------------------------- */

    private onMessage(msg: any): void {
        switch (msg?.type) {
            case 'ready': this.refresh(); break;
            case 'clear': this.clear(); break;
            case 'run': void this.run(String(msg.code ?? '')); break;
            default: log(`console view: unknown message ${JSON.stringify(msg).slice(0, 120)}`); break;
        }
    }

    /** Run one line (or block) on the board. Everything it prints arrives through the line event,
     *  so there is nothing to append here; only a console that is not live has to be reported. */
    private async run(code: string): Promise<void> {
        const trimmed = code.replace(/\s+$/, '');
        if (!trimmed.trim() || this.running) { return; }
        this.sent = [trimmed, ...this.sent.filter((s) => s !== trimmed)].slice(0, MAX_HISTORY);
        this.running = true;
        this.post({ type: 'busy', running: true });
        try {
            await consoleRunLine(trimmed);
        } catch (e: any) {
            // consoleRunLine rejects only when the console is not live; runCode() says the rest itself
            this.append(`! ${e?.message ?? e}`);
        } finally {
            this.running = false;
            this.post({ type: 'busy', running: false });
            this.postHistory();
        }
    }

    /* ---- the page ------------------------------------------------------------------------ */

    private html(webview: vscode.Webview): string {
        const media = (name: string) => webview.asWebviewUri(
            vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'console', name)).toString();
        const nonce = Array.from({ length: 24 },
            () => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[Math.floor(Math.random() * 62)]).join('');
        const csp = [
            `default-src 'none'`,
            `style-src ${webview.cspSource}`,
            `script-src 'nonce-${nonce}'`,
        ].join('; ');
        return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta http-equiv="Content-Security-Policy" content="${csp}">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="stylesheet" href="${media('console.css')}">
<title>EVN Console</title>
</head>
<body>
<div id="transcript" role="log" aria-live="polite" aria-label="Console transcript"></div>
<div id="charts" aria-label="Live device readings"></div>
<div id="prompt">
    <div id="hint"></div>
    <div id="entry">
        <span id="chevron" aria-hidden="true">&gt;&gt;&gt;</span>
        <textarea id="input" rows="1" spellcheck="false" autocomplete="off" autocapitalize="off"
                  aria-label="Python to run on the board"></textarea>
    </div>
</div>
<script nonce="${nonce}" src="${media('console.js')}"></script>
</body>
</html>`;
    }
}

export function registerConsoleView(ctx: vscode.ExtensionContext): void {
    const provider = new ConsoleViewProvider(ctx);
    ctx.subscriptions.push(vscode.window.registerWebviewViewProvider(
        ConsoleViewProvider.viewId, provider, { webviewOptions: { retainContextWhenHidden: false } }));

    // mirror from the moment the extension starts, not from the first resolve: the lines written
    // while the view was collapsed (or never opened) are in the buffer when it does open
    ctx.subscriptions.push(onDidWriteConsoleLine((line) => provider.append(line)));
    ctx.subscriptions.push(onDidChangeConsole(() => provider.postState()));
    // the charts ride on the telemetry the console already receives: no extra traffic, no timer
    ctx.subscriptions.push(onDidReceiveTelemetry((t: Telemetry) => provider.telemetry(t)));
    ctx.subscriptions.push(vscode.commands.registerCommand('evn.console.clear', () => provider.clear()));
}
