/* The byte stream the board protocol runs over, and the buffered wire on top of it.
 *
 * Everything that talks to the board in the browser (the raw REPL, the console helper, the run
 * terminal) is written against `ByteStream` only, so the very same code can run
 *   - in the browser over Web Serial (`WebSerialStream`),
 *   - under Node over scripts/serial_bridge.py, which is a COM port on stdin/stdout, and
 *   - against a scripted mock board in the tests.
 *
 * `Wire` is the buffered reader the Python helper has in pyserial: read_some / read_until /
 * read_exact / in_waiting, with the same meanings, so the port of `Helper` stays line for line.
 */

/* TypeScript 5.7 made the typed arrays generic in their buffer; a plain `Uint8Array` then means
 * `Uint8Array<ArrayBuffer>`, which `slice()` and the Web Serial reader do not give back. `Bytes` is
 * the shape every byte in this file actually has. */
export type Bytes = Uint8Array<ArrayBufferLike>;

export interface ByteStream {
    /** Bytes as they arrive; resolves empty when `timeoutMs` passed with nothing. */
    read(timeoutMs: number): Promise<Bytes>;
    write(bytes: Bytes): Promise<void>;
    close(): Promise<void>;
    /** Set once the other end is gone; a read then resolves empty for ever. */
    readonly closed: boolean;
}

export class StreamGone extends Error { }

/** A growable byte buffer with the few operations the protocol needs. */
export class Wire {
    private buf: Bytes = new Uint8Array(0);
    private dead = false;
    private deadWhy = '';

    constructor(private readonly stream: ByteStream, public patience = 1.0) { }

    get inWaiting(): number { return this.buf.length; }
    get gone(): boolean { return this.dead || this.stream.closed; }

    /** Everything buffered right now (and drop it). */
    takeAll(): Bytes {
        const out = this.buf;
        this.buf = new Uint8Array(0);
        return out;
    }

    /** Look at the buffer without consuming it. */
    peek(): Bytes { return this.buf; }

    drop(n: number): void { this.buf = this.buf.slice(n); }

    /** Put bytes back at the front of the buffer (what `readUntil` returned and the caller kept). */
    unread(bytes: Bytes): void {
        if (!bytes.length) { return; }
        const next = new Uint8Array(bytes.length + this.buf.length);
        next.set(bytes, 0);
        next.set(this.buf, bytes.length);
        this.buf = next;
    }

    resetInput(): void { this.buf = new Uint8Array(0); }

    private append(chunk: Bytes): void {
        if (!chunk.length) { return; }
        const next = new Uint8Array(this.buf.length + chunk.length);
        next.set(this.buf, 0);
        next.set(chunk, this.buf.length);
        this.buf = next;
    }

    /** One pull from the stream into the buffer; returns how many bytes arrived. */
    async pump(timeoutMs = 50): Promise<number> {
        if (this.dead) { throw new StreamGone(this.deadWhy); }
        let chunk: Bytes;
        try { chunk = await this.stream.read(timeoutMs); }
        catch (e: any) { this.dead = true; this.deadWhy = String(e?.message ?? e); throw new StreamGone(this.deadWhy); }
        if (this.stream.closed && !chunk.length) { this.dead = true; this.deadWhy = 'the port closed'; throw new StreamGone(this.deadWhy); }
        this.append(chunk);
        return chunk.length;
    }

    /** What is buffered, else one pull (pyserial's `read(in_waiting or 1)`). */
    async readSome(timeoutMs = 50): Promise<Bytes> {
        if (this.buf.length) { return this.takeAll(); }
        await this.pump(timeoutMs);
        return this.takeAll();
    }

    async write(bytes: Bytes | string): Promise<void> {
        const data = typeof bytes === 'string' ? encode(bytes) : bytes;
        try { await this.stream.write(data); }
        catch (e: any) { this.dead = true; this.deadWhy = String(e?.message ?? e); throw new StreamGone(this.deadWhy); }
    }

    /** Read until `needle` shows up; what followed it, or undefined on timeout. */
    async readUntil(needle: string | Bytes, timeoutSeconds: number): Promise<Bytes | undefined> {
        const want = typeof needle === 'string' ? encode(needle) : needle;
        const end = Date.now() + timeoutSeconds * 1000 * this.patience;
        for (;;) {
            const i = indexOf(this.buf, want);
            if (i >= 0) {
                const rest = this.buf.slice(i + want.length);
                this.buf = new Uint8Array(0);
                return rest;
            }
            if (Date.now() >= end) { return undefined; }
            await this.pump(Math.min(100, Math.max(5, end - Date.now())));
        }
    }

    /** Exactly n bytes, never more (the raw-paste protocol reads byte by byte). */
    async readExact(n: number, timeoutSeconds: number): Promise<Bytes> {
        const end = Date.now() + timeoutSeconds * 1000 * this.patience;
        while (this.buf.length < n && Date.now() < end) {
            await this.pump(Math.min(100, Math.max(5, end - Date.now())));
        }
        const take = Math.min(n, this.buf.length);
        const out = this.buf.slice(0, take);
        this.buf = this.buf.slice(take);
        return out;
    }

    close(): Promise<void> { return this.stream.close(); }
}

/* ---- helpers ------------------------------------------------------------------------- */

const ENC = new TextEncoder();
const DEC = new TextDecoder('utf-8', { fatal: false });

export function encode(s: string): Bytes { return ENC.encode(s); }
export function decode(b: Bytes): string { return DEC.decode(b); }

export function indexOf(haystack: Bytes, needle: Bytes, from = 0): number {
    if (!needle.length) { return from; }
    const last = haystack.length - needle.length;
    outer: for (let i = from; i <= last; i++) {
        for (let j = 0; j < needle.length; j++) {
            if (haystack[i + j] !== needle[j]) { continue outer; }
        }
        return i;
    }
    return -1;
}

export function concat(...parts: Bytes[]): Bytes {
    let n = 0;
    for (const p of parts) { n += p.length; }
    const out = new Uint8Array(n);
    let at = 0;
    for (const p of parts) { out.set(p, at); at += p.length; }
    return out;
}

/** A board line as text: no CR, no control characters (the raw REPL's 0x01..0x04). */
export function clean(raw: Bytes | string): string {
    const text = (typeof raw === 'string' ? raw : decode(raw)).replace(/\r/g, '');
    let out = '';
    for (const ch of text) {
        if (ch >= ' ' || ch === '\t' || ch === '\n') { out += ch; }
    }
    return out;
}

export function delay(ms: number): Promise<void> {
    return new Promise((r) => setTimeout(r, ms));
}

/* ---- Web Serial ---------------------------------------------------------------------- */

/**
 * A granted Web Serial port as a ByteStream.
 *
 * `open()` is what pyserial's Serial(...) is; the reader is kept for the life of the stream and
 * `read()` races it against a timer, so a timeout leaves the pending read in place (cancelling a
 * Web Serial reader ends the stream, which is not what a poll means).
 */
export class WebSerialStream implements ByteStream {
    private reader: ReadableStreamDefaultReader<Bytes> | undefined;
    private writer: WritableStreamDefaultWriter<Bytes> | undefined;
    private pending: Promise<ReadableStreamReadResult<Bytes>> | undefined;
    private dead = false;

    constructor(private readonly port: any, private readonly baud = 115200) { }

    get closed(): boolean { return this.dead; }

    async open(): Promise<void> {
        await this.port.open({ baudRate: this.baud, bufferSize: 65536 });
        this.reader = this.port.readable.getReader();
        this.writer = this.port.writable.getWriter();
    }

    async read(timeoutMs: number): Promise<Bytes> {
        if (!this.reader || this.dead) { return new Uint8Array(0); }
        if (!this.pending) { this.pending = this.reader.read(); }
        const timer = new Promise<'timeout'>((r) => setTimeout(() => r('timeout'), Math.max(1, timeoutMs)));
        const winner = await Promise.race([this.pending, timer]);
        if (winner === 'timeout') { return new Uint8Array(0); }
        this.pending = undefined;
        const res = winner as ReadableStreamReadResult<Bytes>;
        if (res.done) { this.dead = true; return new Uint8Array(0); }
        return res.value ?? new Uint8Array(0);
    }

    async write(bytes: Bytes): Promise<void> {
        if (!this.writer) { throw new Error('the port is not open'); }
        await this.writer.write(bytes);
    }

    async close(): Promise<void> {
        this.dead = true;
        try { await this.reader?.cancel(); } catch { /* already gone */ }
        try { this.reader?.releaseLock(); } catch { /* already gone */ }
        try { await this.writer?.close(); } catch { /* already gone */ }
        try { this.writer?.releaseLock(); } catch { /* already gone */ }
        try { await this.port.close(); } catch { /* already gone */ }
        this.reader = undefined;
        this.writer = undefined;
        this.pending = undefined;
    }
}
