/* The EVN ALPHA sidebar: the Start view (five one-line entries, so it takes a few rows, not the
 * screen) and the "My projects" tree over the user's projects folder.
 *
 * The tree shows the programs only - .py and .evnblocks files and the folders holding them.
 * Everything that supports them (typings/, .vscode/, evn_project.json, the <name>.evnblocks.py
 * a blocks run generates) stays hidden: a tester sees their programs, nothing else.
 *
 * Every file operation goes through vscode.workspace.fs on a Uri, so the same tree serves the
 * folder under Documents on the desktop and the browser's evn-projects: store on the web.
 */
import * as vscode from 'vscode';
import * as path from './platform/paths';
import { host } from './platform/host';
import { log, sleep } from './util';
import { BlocksEditorProvider, BLOCKS_EDITOR_ID, BLOCKS_EXT, EMPTY_DOCUMENT } from './blocksEditor';
import { projectsFolder, ensureProjectsFolder, exists, validateProjectName } from './projectsFolder';

export interface ProjectsDeps {
    runFile(file: vscode.Uri): Promise<void>;
    uploadMain(file: vscode.Uri): Promise<void>;
    blocks: BlocksEditorProvider;
}

/** Folders that are support, not programs. Dot-folders (.vscode, .git) are hidden by name. */
const HIDDEN_FOLDERS = new Set(['typings', '__pycache__']);
const PY_EXT = '.py';
const GENERATED_SUFFIX = BLOCKS_EXT + PY_EXT;   // my_blocks.evnblocks.py: rewritten at every run
const REFRESH_DEBOUNCE_MS = 200;
const BLOCKS_READY_MS = 4000;

/* ---- helpers -------------------------------------------------------------------------- */

function isBlocks(file: string): boolean {
    return file.toLowerCase().endsWith(BLOCKS_EXT);
}

/** True for the files the tree shows: a hand-written .py or a blocks file, never a generated one.
 *  evn_project.json and everything else that is not a program falls out here. */
function isProgram(name: string): boolean {
    const n = name.toLowerCase();
    if (n.startsWith('.') || n.endsWith(GENERATED_SUFFIX)) { return false; }
    return n.endsWith(PY_EXT) || n.endsWith(BLOCKS_EXT);
}

/** Two uris pointing at the same thing (the file system decides how strict that is). */
function same(a: vscode.Uri, b: vscode.Uri): boolean {
    const norm = (u: vscode.Uri) => u.with({ path: u.path.replace(/\/+$/, '') }).toString();
    const x = norm(a);
    const y = norm(b);
    return a.scheme === 'file' ? x.toLowerCase() === y.toLowerCase() : x === y;
}

/** True when `child` is the folder itself or sits under it. */
function inside(root: vscode.Uri, child: vscode.Uri): boolean {
    if (root.scheme !== child.scheme) { return false; }
    if (same(root, child)) { return true; }
    const r = root.path.replace(/\/+$/, '') + '/';
    return root.scheme === 'file'
        ? child.path.toLowerCase().startsWith(r.toLowerCase())
        : child.path.startsWith(r);
}

function byName(a: ProjectItem, b: ProjectItem): number {
    const an = path.posix.basename(a.uri.path).toLowerCase();
    const bn = path.posix.basename(b.uri.path).toLowerCase();
    return an < bn ? -1 : an > bn ? 1 : 0;
}

/** The starter program a new .py gets: one motor turn, so Ctrl+F5 does something visible. */
function pythonTemplate(fileName: string): string {
    return [
        '# ' + fileName + ': a program for the EVN ALPHA. Press Ctrl+F5 to run it on the board.',
        'from evn import Motor, wait',
        '',
        'motor_1 = Motor(1)',
        'motor_1.run_angle(500, 360)   # 500 deg/s, one turn',
        'wait(500)',
        'print("done:", motor_1.angle())',
        '',
    ].join('\n');
}

const enc = (s: string) => new TextEncoder().encode(s);

/* ---- the tree ------------------------------------------------------------------------- */

class ProjectItem extends vscode.TreeItem {
    constructor(public readonly uri: vscode.Uri, public readonly isFolder: boolean) {
        super(uri, isFolder ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None);
        // the resourceUri gives the icon theme's icon; the label stays the plain file name
        this.id = uri.toString();
        this.label = path.posix.basename(uri.path);
        this.tooltip = uri.scheme === 'file' ? uri.fsPath : uri.toString();
        this.contextValue = isFolder ? 'evnProjectFolder' : isBlocks(uri.path) ? 'evnProjectBlocks' : 'evnProjectFile';
        if (!isFolder) {
            this.command = isBlocks(uri.path)
                ? { command: 'vscode.openWith', title: 'Open', arguments: [uri, BLOCKS_EDITOR_ID] }
                : { command: 'vscode.open', title: 'Open', arguments: [uri] };
        }
    }
}

class ProjectsProvider implements vscode.TreeDataProvider<ProjectItem> {
    private readonly emitter = new vscode.EventEmitter<ProjectItem | undefined>();
    readonly onDidChangeTreeData = this.emitter.event;

    constructor(private readonly ctx: vscode.ExtensionContext) { }

    /** The projects folder, re-created when it went missing since the last refresh. */
    root(): vscode.Uri { return projectsFolder(); }

    async ensure(): Promise<vscode.Uri> {
        try { return await ensureProjectsFolder(this.ctx); }
        catch (e) { log(`ERROR projects folder: ${e}`); return this.root(); }
    }

    refresh(): void { this.emitter.fire(undefined); }

    getTreeItem(element: ProjectItem): vscode.TreeItem { return element; }

    async getChildren(element?: ProjectItem): Promise<ProjectItem[]> {
        const dir = element ? element.uri : this.root();
        let entries: [string, vscode.FileType][];
        try { entries = await vscode.workspace.fs.readDirectory(dir); }
        catch (e) {
            if (element) { log(`projects tree: cannot read ${dir.toString()}: ${e}`); return []; }
            // the folder went away (or has never been made): make it and try once more
            try { entries = await vscode.workspace.fs.readDirectory(await this.ensure()); }
            catch (e2) { log(`projects tree: cannot read ${dir.toString()}: ${e2}`); return []; }
        }
        const folders: ProjectItem[] = [];
        const files: ProjectItem[] = [];
        for (const [name, type] of entries) {
            const full = vscode.Uri.joinPath(dir, name);
            if (type === vscode.FileType.Directory) {
                if (name.startsWith('.') || HIDDEN_FOLDERS.has(name)) { continue; }
                folders.push(new ProjectItem(full, true));
            } else if (type === vscode.FileType.File && isProgram(name)) {
                files.push(new ProjectItem(full, false));
            }
        }
        return [...folders.sort(byName), ...files.sort(byName)];
    }

    /** Needed by treeView.reveal: the folder item above an item, undefined at the root. */
    getParent(element: ProjectItem): ProjectItem | undefined {
        const root = this.root();
        const dir = element.uri.with({ path: path.posix.dirname(element.uri.path) });
        if (same(dir, root) || !inside(root, dir)) { return undefined; }
        return new ProjectItem(dir, true);
    }
}

/** One row of the Start view: a label, an icon and the command it runs. */
interface StartEntry {
    label: string;
    icon: string;
    command: string;
    tooltip: string;
}

const START_ENTRIES: StartEntry[] = [
    { label: 'New Python program', icon: 'new-file', command: 'evn.newPythonProject', tooltip: 'A new Python program in your projects folder; Ctrl+F5 runs it on the board.' },
    { label: 'New blocks program', icon: 'symbol-misc', command: 'evn.newBlocksProject', tooltip: 'A new blocks program in your projects folder; the blocks become Python when it runs.' },
    { label: 'Board panel', icon: 'circuit-board', command: 'evn.board.focus', tooltip: 'The Board panel in the secondary side bar: the live console, the ports, the battery and the files on the board.' },
    { label: 'Documentation', icon: 'book', command: 'evn.openDocumentation', tooltip: 'The online documentation.' },
    { label: 'Getting started', icon: 'compass', command: 'evn.openWalkthrough', tooltip: 'The guided first steps: install mpremote, flash the firmware, run an example.' },
];

/** The Start view: a short list of entry points. It used to be a welcome page of paragraphs, which
 *  took most of the side bar; five rows leave the room to the projects and the examples. */
class StartProvider implements vscode.TreeDataProvider<StartEntry> {
    getTreeItem(entry: StartEntry): vscode.TreeItem {
        const item = new vscode.TreeItem(entry.label, vscode.TreeItemCollapsibleState.None);
        item.iconPath = new vscode.ThemeIcon(entry.icon);
        item.command = { command: entry.command, title: entry.label };
        item.tooltip = entry.tooltip;
        return item;
    }
    getChildren(): StartEntry[] {
        return START_ENTRIES;
    }
}

/* ---- registration --------------------------------------------------------------------- */

export function registerProjectsView(ctx: vscode.ExtensionContext, deps: ProjectsDeps): void {
    ctx.subscriptions.push(vscode.window.registerTreeDataProvider('evn.start', new StartProvider()));

    const provider = new ProjectsProvider(ctx);
    const treeView = vscode.window.createTreeView('evn.projects', { treeDataProvider: provider, showCollapseAll: true });
    ctx.subscriptions.push(treeView);

    /* the tree follows the folder: a debounced watcher, which works outside the workspace too */
    let watcher: vscode.FileSystemWatcher | undefined;
    let timer: any;
    const scheduleRefresh = () => {
        if (timer) { clearTimeout(timer); }
        timer = setTimeout(() => { timer = undefined; provider.refresh(); }, REFRESH_DEBOUNCE_MS);
    };
    const watchFolder = () => {
        watcher?.dispose();
        watcher = vscode.workspace.createFileSystemWatcher(new vscode.RelativePattern(provider.root(), '**/*'));
        watcher.onDidCreate(scheduleRefresh);
        watcher.onDidChange(scheduleRefresh);
        watcher.onDidDelete(scheduleRefresh);
        ctx.subscriptions.push(watcher);
    };
    // the path is worth saying only when it is not where the extension would have put it
    const updateMessage = () => {
        const configured = vscode.workspace.getConfiguration('evn').get<string>('projectsFolder', '').trim();
        const root = provider.root();
        treeView.message = configured ? (root.scheme === 'file' ? root.fsPath : root.toString()) : undefined;
    };
    watchFolder();
    updateMessage();
    ctx.subscriptions.push({ dispose: () => { if (timer) { clearTimeout(timer); } watcher?.dispose(); } });
    ctx.subscriptions.push(vscode.workspace.onDidChangeConfiguration((e) => {
        if (e.affectsConfiguration('evn.projectsFolder')) {
            watchFolder();
            updateMessage();
            provider.refresh();
        }
    }));

    const reg = (id: string, fn: (...a: any[]) => any) =>
        ctx.subscriptions.push(vscode.commands.registerCommand(id, async (...a: any[]) => {
            try { await fn(...a); }
            catch (e: any) {
                log(`ERROR ${id}: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));

    /* ---- opening and revealing --------------------------------------------------------- */

    const openProgram = async (uri: vscode.Uri): Promise<void> => {
        if (isBlocks(uri.path)) { await vscode.commands.executeCommand('vscode.openWith', uri, BLOCKS_EDITOR_ID); }
        else { await vscode.commands.executeCommand('vscode.open', uri); }
    };

    const revealUri = async (uri: vscode.Uri): Promise<void> => {
        try {
            let folder = false;
            try { folder = (await vscode.workspace.fs.stat(uri)).type === vscode.FileType.Directory; } catch { /* just made */ }
            await treeView.reveal(new ProjectItem(uri, folder), { select: true, focus: false });
        } catch (e) { log(`projects tree: reveal of ${uri.toString()} skipped: ${e}`); }   // the view may be hidden
    };

    /** The item a context-menu command acted on, or a clear error when there is none. */
    const requireItem = (item?: ProjectItem): ProjectItem => {
        if (!item || !(item.uri instanceof vscode.Uri)) {
            throw new Error('right-click a program in "My projects" first');
        }
        return item;
    };

    const requireProgram = (item?: ProjectItem): vscode.Uri => {
        const it = requireItem(item);
        if (it.isFolder) { throw new Error('that is a folder, not a program'); }
        return it.uri;
    };

    /** Drop the MicroPython a blocks file generated; it is rewritten at the next run. */
    const removeGenerated = async (blocksFile: vscode.Uri): Promise<void> => {
        const generated = blocksFile.with({ path: blocksFile.path + PY_EXT });
        if (!await exists(generated)) { return; }
        try { await vscode.workspace.fs.delete(generated, { useTrash: false }); }
        catch (e) { log(`projects tree: could not remove ${generated.toString()}: ${e}`); }
    };

    /* Open a blocks file and wait for its webview to report a program: the blocks editor runs what
     * the webview generated, and that arrives a moment after the panel opens. */
    const blocksReady = async (uri: vscode.Uri): Promise<void> => {
        await vscode.commands.executeCommand('vscode.openWith', uri, BLOCKS_EDITOR_ID);
        const key = uri.toString();
        const deadline = Date.now() + BLOCKS_READY_MS;
        do {
            const session = deps.blocks.activeSession();
            if (session && session.document.uri.toString() === key) {
                const python = await deps.blocks.currentPython();
                if (python && python.trim()) { return; }
            }
            await sleep(100);
        } while (Date.now() < deadline);
        throw new Error('the blocks program is empty');
    };

    /* ---- new programs ------------------------------------------------------------------ */

    const createProgram = async (blocks: boolean, item?: ProjectItem): Promise<void> => {
        const root = await provider.ensure();
        // the buttons sit in the view title, so the root is the target; a folder item aims inside it
        const dir = item && item.isFolder && inside(root, item.uri) ? item.uri : root;
        const ext = blocks ? BLOCKS_EXT : PY_EXT;
        const typed = await vscode.window.showInputBox({
            prompt: blocks ? 'Name of the new blocks program' : 'Name of the new Python program',
            value: blocks ? 'my_blocks' : 'my_program',
            validateInput: validateProjectName,
        });
        if (typed === undefined) { return; }
        let name = typed.trim();
        if (!name.toLowerCase().endsWith(ext)) { name += ext; }
        const file = vscode.Uri.joinPath(dir, name);
        if (await exists(file)) {
            const choice = await vscode.window.showWarningMessage(`EVN: ${name} already exists in ${dir.scheme === 'file' ? dir.fsPath : dir.toString()}.`, 'Open it');
            if (choice === 'Open it') { await openProgram(file); }
            return;
        }
        await vscode.workspace.fs.createDirectory(dir);
        await vscode.workspace.fs.writeFile(file, enc(blocks ? EMPTY_DOCUMENT : pythonTemplate(name)));
        log(`created ${file.toString()}`);
        await openProgram(file);
        provider.refresh();
        await revealUri(file);
    };

    reg('evn.newPythonProject', (item?: ProjectItem) => createProgram(false, item));
    reg('evn.newBlocksProject', (item?: ProjectItem) => createProgram(true, item));

    /* ---- running and uploading --------------------------------------------------------- */

    reg('evn.runProject', async (item?: ProjectItem) => {
        const file = requireProgram(item);
        if (isBlocks(file.path)) {
            await blocksReady(file);
            await deps.blocks.run();
        } else {
            await deps.runFile(file);
        }
    });

    reg('evn.uploadProjectMain', async (item?: ProjectItem) => {
        const file = requireProgram(item);
        if (isBlocks(file.path)) {
            await blocksReady(file);
            await deps.blocks.upload();
        } else {
            await deps.uploadMain(file);
        }
    });

    /* ---- file management --------------------------------------------------------------- */

    reg('evn.renameProject', async (item?: ProjectItem) => {
        const target = requireItem(item);
        const oldName = path.posix.basename(target.uri.path);
        const ext = target.isFolder ? '' : path.posix.extname(oldName);
        const typed = await vscode.window.showInputBox({
            prompt: `New name for ${oldName}`,
            value: oldName,
            validateInput: validateProjectName,
        });
        if (typed === undefined) { return; }
        let name = typed.trim();
        // a .py renamed to "x" stays a program: the extension is kept when the user drops it
        if (ext && !name.toLowerCase().endsWith(ext.toLowerCase())) { name += ext; }
        if (name === oldName) { return; }
        const dst = vscode.Uri.joinPath(target.uri.with({ path: path.posix.dirname(target.uri.path) }), name);
        if (await exists(dst)) { throw new Error(`${name} already exists here`); }
        // workspace.fs.rename so an editor open on the file follows it
        await vscode.workspace.fs.rename(target.uri, dst, { overwrite: false });
        if (isBlocks(target.uri.path)) { await removeGenerated(target.uri); }
        log(`renamed ${target.uri.toString()} to ${dst.toString()}`);
        provider.refresh();
        await revealUri(dst);
    });

    reg('evn.duplicateProject', async (item?: ProjectItem) => {
        const file = requireProgram(item);
        const dir = file.with({ path: path.posix.dirname(file.path) });
        const ext = path.posix.extname(file.path);
        const base = path.posix.basename(file.path, ext);
        let dst = vscode.Uri.joinPath(dir, `${base} copy${ext}`);
        for (let n = 2; await exists(dst); n++) { dst = vscode.Uri.joinPath(dir, `${base} copy ${n}${ext}`); }
        await vscode.workspace.fs.copy(file, dst, { overwrite: false });
        log(`duplicated ${file.toString()} as ${dst.toString()}`);
        provider.refresh();
        await openProgram(dst);
        await revealUri(dst);
    });

    reg('evn.deleteProject', async (item?: ProjectItem) => {
        const target = requireItem(item);
        const name = path.posix.basename(target.uri.path);
        // a browser has no Recycle Bin: there the delete is final and the question says so
        const trash = !host().web && target.uri.scheme === 'file';
        const ok = await vscode.window.showWarningMessage(
            trash ? `Delete ${name}? It goes to the Recycle Bin / Trash.`
                : `Delete ${name}? This cannot be undone: the browser's projects folder has no Recycle Bin.`,
            { modal: true }, 'Delete');
        if (ok !== 'Delete') { return; }
        await vscode.workspace.fs.delete(target.uri, { recursive: true, useTrash: trash });
        if (isBlocks(target.uri.path)) { await removeGenerated(target.uri); }
        log(`deleted ${target.uri.toString()}`);
        provider.refresh();
    });

    reg('evn.revealProject', async (item?: ProjectItem) => {
        const target = requireItem(item);
        await vscode.commands.executeCommand('revealFileInOS', target.uri);
    });

    /* ---- the folder itself ------------------------------------------------------------- */

    reg('evn.openProjectsFolder', async () => {
        const root = await provider.ensure();
        const where = root.scheme === 'file' ? root.fsPath : root.toString();
        const folders = vscode.workspace.workspaceFolders ?? [];
        if (folders.length === 1 && same(folders[0].uri, root)) {
            vscode.window.showInformationMessage(`EVN: your projects folder is already open (${where}).`);
            return;
        }
        const pick = await vscode.window.showQuickPick([
            { label: 'This window', description: 'replaces what is open here', newWindow: false },
            { label: 'New window', description: 'keeps this window as it is', newWindow: true },
        ], { placeHolder: `Open ${where} as the workspace` });
        if (!pick) { return; }
        await vscode.commands.executeCommand('vscode.openFolder', root, { forceNewWindow: pick.newWindow });
    });

    reg('evn.revealProjectsFolder', async () => {
        await vscode.commands.executeCommand('revealFileInOS', provider.root());
    });

    reg('evn.refreshProjects', () => { provider.refresh(); });
}
