/* Blocks editor: a custom text editor for .evnblocks files hosting a Blockly workspace.
 *
 * The document is JSON ({format:"evn-blocks", version:1, workspace:<Blockly state>}); the webview
 * (media/blocks/editor.js) keeps it in sync and generates the MicroPython program from the blocks.
 * Running writes the program to <name>.evnblocks.py next to the blocks file and hands it to the
 * same run / upload path a hand-written Python file takes.
 */
import * as vscode from 'vscode';
import * as path from './platform/paths';
import { log } from './util';
import { EXAMPLE_SCHEME, scratchFile } from './examples';
import { ensureProjectsFolder, exists } from './projectsFolder';

export const BLOCKS_EDITOR_ID = 'evn.blocksEditor';
export const BLOCKS_EXT = '.evnblocks';

export interface BoardActions {
    runPython(file: vscode.Uri): Promise<void>;
    uploadMain(file: vscode.Uri): Promise<void>;
    stopMotors(): Promise<void>;
}

interface Session {
    panel: vscode.WebviewPanel;
    document: vscode.TextDocument;
    python: string;
    lastText: string;                      // text last sent to / received from the webview
}

const GENERATED_HEADER = (name: string) =>
    `# Generated by EVN ALPHA Blocks from ${name}. Edit the blocks, not this file: it is rewritten at every run.\n\n`;

export const EMPTY_DOCUMENT = JSON.stringify({ format: 'evn-blocks', version: 1, workspace: {} }, null, 2) + '\n';

/* Toolbar icons (24-unit stroke glyphs, inline so the page needs no image requests). */
const icon = (body: string) =>
    `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
const ICONS = {
    play: icon('<path d="M6 4l14 8-14 8z" fill="currentColor" stroke="none"/>'),
    stop: icon('<rect x="6" y="6" width="12" height="12" rx="2" fill="currentColor" stroke="none"/>'),
    upload: icon('<path d="M12 16V4M6 10l6-6 6 6"/><path d="M4 20h16"/>'),
    file: icon('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M9 14h6M9 17h6"/>'),
    code: icon('<path d="M8 8l-4 4 4 4M16 8l4 4-4 4M14 5l-4 14"/>'),
    copy: icon('<rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V6a2 2 0 0 1 2-2h9"/>'),
    sun: icon('<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>'),
    moon: icon('<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/>'),
    auto: icon('<circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 1 0 18z" fill="currentColor" stroke="none"/>'),
    collapse: icon('<path d="M7 7l5 5-5 5M13 7l5 5-5 5"/>'),
};

export class BlocksEditorProvider implements vscode.CustomTextEditorProvider {
    private readonly sessions = new Map<string, Session>();
    private active: Session | undefined;

    constructor(private readonly ctx: vscode.ExtensionContext, private readonly board: BoardActions) { }

    static register(ctx: vscode.ExtensionContext, board: BoardActions): BlocksEditorProvider {
        const provider = new BlocksEditorProvider(ctx, board);
        ctx.subscriptions.push(vscode.window.registerCustomEditorProvider(BLOCKS_EDITOR_ID, provider, {
            webviewOptions: { retainContextWhenHidden: true },
            supportsMultipleEditorsPerDocument: false,
        }));
        return provider;
    }

    /** The session of the blocks editor that has focus (or the only one open). */
    activeSession(): Session | undefined {
        if (this.active && this.sessions.has(this.active.document.uri.toString())) { return this.active; }
        const all = [...this.sessions.values()];
        return all.length === 1 ? all[0] : undefined;
    }

    async resolveCustomTextEditor(document: vscode.TextDocument, panel: vscode.WebviewPanel): Promise<void> {
        const key = document.uri.toString();
        const session: Session = { panel, document, python: '', lastText: '' };
        this.sessions.set(key, session);
        this.active = session;

        panel.webview.options = {
            enableScripts: true,
            localResourceRoots: [vscode.Uri.joinPath(this.ctx.extensionUri, 'media')],
        };
        panel.webview.html = this.html(panel.webview);

        const send = (msg: unknown) => { void panel.webview.postMessage(msg); };
        const pushDocument = () => {
            session.lastText = document.getText();
            send({ type: 'load', text: session.lastText });
        };

        const subs: vscode.Disposable[] = [];
        subs.push(vscode.workspace.onDidChangeTextDocument((e) => {
            if (e.document.uri.toString() !== key) { return; }
            if (e.document.getText() !== session.lastText) { pushDocument(); }   // an edit from outside the webview (undo, git, another editor)
        }));
        subs.push(panel.onDidChangeViewState(() => { if (panel.active) { this.active = session; } }));
        subs.push(vscode.workspace.onDidChangeConfiguration((e) => {
            if (e.affectsConfiguration('evn.blocks.theme')) {
                send({ type: 'theme', value: vscode.workspace.getConfiguration('evn').get<string>('blocks.theme', 'auto') });
            }
        }));
        subs.push(panel.webview.onDidReceiveMessage(async (msg: any) => {
            try {
                switch (msg?.type) {
                    case 'ready':
                        pushDocument();
                        break;
                    case 'edit':
                        session.python = msg.python ?? '';
                        await this.applyEdit(document, session, msg.text ?? '');
                        break;
                    case 'code':
                        session.python = msg.python ?? '';
                        break;
                    case 'run':
                        session.python = msg.python ?? session.python;
                        await this.run(session);
                        break;
                    case 'stop':
                        await this.board.stopMotors();
                        break;
                    case 'upload':
                        session.python = msg.python ?? session.python;
                        await this.upload(session);
                        break;
                    case 'export':
                        session.python = msg.python ?? session.python;
                        await this.exportPython(session);
                        break;
                    case 'showCode':
                        await vscode.workspace.getConfiguration('evn').update('blocks.showCode', !!msg.value, vscode.ConfigurationTarget.Global);
                        break;
                    case 'codeWidth':
                        await this.ctx.globalState.update('blocks.codeWidth', typeof msg.value === 'number' ? msg.value : undefined);
                        break;
                    case 'theme':
                        if (['auto', 'light', 'dark'].includes(msg.value)) {
                            await vscode.workspace.getConfiguration('evn').update('blocks.theme', msg.value, vscode.ConfigurationTarget.Global);
                        }
                        break;
                }
            } catch (e: any) {
                log(`ERROR blocks editor: ${e?.stack ?? e}`);
                vscode.window.showErrorMessage(`EVN: ${e?.message ?? e}`);
            }
        }));
        panel.onDidDispose(() => {
            subs.forEach((d) => d.dispose());
            this.sessions.delete(key);
            if (this.active === session) { this.active = undefined; }
        });
    }

    private async applyEdit(document: vscode.TextDocument, session: Session, text: string): Promise<void> {
        if (text === document.getText()) { return; }
        session.lastText = text;
        const edit = new vscode.WorkspaceEdit();
        edit.replace(document.uri, new vscode.Range(0, 0, document.lineCount, 0), text);
        await vscode.workspace.applyEdit(edit);
    }

    /* ---- actions on the active blocks program ------------------------------------------- */

    private async requireProgram(session: Session): Promise<vscode.Uri> {
        if (session.document.isUntitled) { throw new Error('save the blocks file first'); }
        const example = session.document.uri.scheme === EXAMPLE_SCHEME;   // an example is never saved
        if (session.document.isDirty && !example) { await session.document.save(); }
        if (!session.python.trim()) {
            throw new Error('the blocks program is empty: drag blocks from the toolbox first');
        }
        const name = path.posix.basename(session.document.uri.path);
        const out = example ? scratchFile(name + '.py') : generatedPath(session.document.uri);
        await vscode.workspace.fs.writeFile(out, new TextEncoder().encode(GENERATED_HEADER(name) + session.python));
        log(`blocks: wrote ${out.toString()}`);
        return out;
    }

    async run(session = this.activeSession()): Promise<void> {
        if (!session) { throw new Error('open a blocks (.evnblocks) file first'); }
        const file = await this.requireProgram(session);
        await this.board.runPython(file);
    }

    async upload(session = this.activeSession()): Promise<void> {
        if (!session) { throw new Error('open a blocks (.evnblocks) file first'); }
        const file = await this.requireProgram(session);
        await this.board.uploadMain(file);
    }

    async exportPython(session = this.activeSession()): Promise<void> {
        if (!session) { throw new Error('open a blocks (.evnblocks) file first'); }
        if (!session.python.trim()) { throw new Error('the blocks program is empty'); }
        const example = session.document.uri.scheme === EXAMPLE_SCHEME;
        const name = path.posix.basename(session.document.uri.path);
        const suggested = session.document.isUntitled ? 'program.py' : path.posix.basename(name, BLOCKS_EXT) + '.py';
        // an example has nowhere of its own to export to, so it goes to the projects folder
        const dir = example ? await ensureProjectsFolder(this.ctx)
            : session.document.isUntitled ? (vscode.workspace.workspaceFolders?.[0]?.uri ?? await ensureProjectsFolder(this.ctx))
                : session.document.uri.with({ path: path.posix.dirname(session.document.uri.path) });
        const target = await vscode.window.showSaveDialog({
            defaultUri: vscode.Uri.joinPath(dir, suggested),
            filters: { 'Python': ['py'] },
            saveLabel: 'Export Python',
        });
        if (!target) { return; }
        await vscode.workspace.fs.writeFile(target, new TextEncoder().encode(`# Exported from EVN ALPHA Blocks (${name}).\n\n` + session.python));
        const doc = await vscode.workspace.openTextDocument(target);
        await vscode.window.showTextDocument(doc, vscode.ViewColumn.Beside);
    }

    /** Python of the active blocks program (asks the webview when it has not reported one yet). */
    async currentPython(): Promise<string | undefined> {
        const session = this.activeSession();
        if (!session) { return undefined; }
        if (session.python) { return session.python; }
        return new Promise<string>((resolve) => {
            const id = Date.now();
            const sub = session.panel.webview.onDidReceiveMessage((msg: any) => {
                if (msg?.type === 'code' && msg.id === id) { sub.dispose(); resolve(msg.python ?? ''); }
            });
            void session.panel.webview.postMessage({ type: 'getCode', id });
            setTimeout(() => { sub.dispose(); resolve(session.python); }, 3000);
        });
    }

    /* ---- webview page -------------------------------------------------------------------- */

    private html(webview: vscode.Webview): string {
        const media = (...p: string[]) => webview.asWebviewUri(vscode.Uri.joinPath(this.ctx.extensionUri, 'media', ...p)).toString();
        const nonce = Array.from({ length: 24 }, () => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[Math.floor(Math.random() * 62)]).join('');
        const cfg = vscode.workspace.getConfiguration('evn');
        const config = {
            mediaUri: media('blockly', 'media') + '/',
            renderer: cfg.get<string>('blocks.renderer', 'zelos'),
            showCode: cfg.get<boolean>('blocks.showCode', true),
            codeWidth: this.ctx.globalState.get<number>('blocks.codeWidth'),
            theme: cfg.get<string>('blocks.theme', 'auto'),
        };
        const csp = [
            `default-src 'none'`,
            `img-src ${webview.cspSource} data:`,
            `style-src ${webview.cspSource} 'unsafe-inline'`,
            `font-src ${webview.cspSource}`,
            `script-src 'nonce-${nonce}'`,
        ].join('; ');
        return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta http-equiv="Content-Security-Policy" content="${csp}">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="stylesheet" href="${media('blocks', 'editor.css')}">
<title>EVN ALPHA Blocks</title>
</head>
<body>
<div id="toolbar">
    <div id="brand" title="EVN ALPHA Blocks">
        <svg class="mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="8" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/><path d="M17 13v8M13 17h8"/></svg>
        <span class="title">EVN ALPHA <small>Blocks</small></span>
    </div>
    <button id="btnRun" class="btn primary" title="Run this program on the board (Ctrl+F5)">${ICONS.play} Run on board</button>
    <button id="btnStop" class="btn outline danger" title="Interrupt the program and coast every motor (Ctrl+Shift+F5)">${ICONS.stop} Stop motors</button>
    <span class="divider"></span>
    <button id="btnUpload" class="btn" title="Copy this program to the board as main.py so it starts at power-on">${ICONS.upload} Upload as main.py</button>
    <button id="btnExport" class="btn" title="Save the generated MicroPython as a .py file you can edit">${ICONS.file} Export Python</button>
    <span class="spacer"></span>
    <span id="status"></span>
    <span class="group">
        <button id="btnTheme" class="btn icon" title="Colour scheme"><span class="ico-auto">${ICONS.auto}</span><span class="ico-light">${ICONS.sun}</span><span class="ico-dark">${ICONS.moon}</span></button>
    </span>
</div>
<div id="main">
    <div id="blocklyDiv"></div>
    <div id="splitter" title="Drag to resize the Python pane; double-click to reset"></div>
    <div id="codePane">
        <header>
            <span class="dot"></span><span>MicroPython</span><span class="spacer"></span>
            <button id="btnCopy" class="btn" title="Copy the program to the clipboard">${ICONS.copy} Copy</button>
            <button id="btnCollapse" class="btn icon" title="Minimise the Python pane">${ICONS.collapse}</button>
        </header>
        <pre id="code" class="empty"></pre>
    </div>
    <button id="codePill" class="pill" title="Show the generated MicroPython">${ICONS.code} Python</button>
</div>
<script nonce="${nonce}">window.evnBlocksConfig = ${JSON.stringify(config)};</script>
<script nonce="${nonce}" src="${media('blockly', 'blockly_compressed.js')}"></script>
<script nonce="${nonce}" src="${media('blockly', 'blocks_compressed.js')}"></script>
<script nonce="${nonce}" src="${media('blockly', 'python_compressed.js')}"></script>
<script nonce="${nonce}" src="${media('blockly', 'msg', 'en.js')}"></script>
<script nonce="${nonce}" src="${media('blocks', 'evn_blocks.js')}"></script>
<script nonce="${nonce}" src="${media('blocks', 'editor.js')}"></script>
</body>
</html>`;
    }
}

/** Where the MicroPython generated from a blocks file goes: next to it, as <name>.evnblocks.py. */
export function generatedPath(blocksFile: vscode.Uri): vscode.Uri {
    return blocksFile.with({ path: blocksFile.path + '.py' });
}

/** Create a new, empty blocks file (asks where) and open it in the blocks editor. */
export async function newBlocksFile(ctx: vscode.ExtensionContext): Promise<void> {
    const folder = vscode.workspace.workspaceFolders?.[0]?.uri ?? await ensureProjectsFolder(ctx);
    const target = await vscode.window.showSaveDialog({
        defaultUri: vscode.Uri.joinPath(folder, 'program' + BLOCKS_EXT),
        filters: { 'EVN blocks': ['evnblocks'] },
        saveLabel: 'Create blocks file',
    });
    if (!target) { return; }
    const file = target.path.endsWith(BLOCKS_EXT) ? target : target.with({ path: target.path + BLOCKS_EXT });
    if (!await exists(file)) {
        await vscode.workspace.fs.writeFile(file, new TextEncoder().encode(EMPTY_DOCUMENT));
    }
    await vscode.commands.executeCommand('vscode.openWith', file, BLOCKS_EDITOR_ID);
}
